window.STUDY_SECTIONS = window.STUDY_SECTIONS || {};
window.STUDY_SECTIONS["area-psi-salud-publica"] = {"sheet-ottawa-01":[{"title":"Salud como recurso cotidiano","depth":"core","body":["La Carta de Ottawa define la promoción de la salud como el proceso de proporcionar a las personas los medios necesarios para mejorar su salud y ejercer un mayor control sobre ella. La salud se entiende como un recurso para la vida diaria, no como el objetivo último de la existencia.","Para alcanzarla se requieren condiciones básicas: paz, educación, vivienda, alimentación, renta, un ecosistema estable, justicia social y equidad. Sin esas bases, las acciones educativas aisladas tienen poco efecto."],"bullets":["La promoción actúa sobre las condiciones que producen salud, no solo sobre la enfermedad.","La equidad es el centro: reducir diferencias evitables e injustas.","El sector salud no puede solo: necesita gobiernos, sectores sociales, comunidad y medios."]},{"title":"Las cinco estrategias","depth":"core","table":{"headers":["Estrategia","Qué busca"],"rows":[["Política pública sana","Que todos los sectores consideren las consecuencias de sus decisiones sobre la salud."],["Ambientes favorables","Crear entornos de vida, trabajo y ocio seguros y estimulantes."],["Acción comunitaria","Que la comunidad fije prioridades y participe en las decisiones y en la ejecución."],["Aptitudes personales","Información, educación y habilidades para la vida que amplíen las opciones de autocuidado."],["Reorientación de servicios","Que los servicios sanitarios incorporen la promoción y respondan a las necesidades culturales."]]}},{"title":"Qué implica en el primer nivel","depth":"full","body":["La Carta no propone una campaña única sino una combinación de estrategias. El primer nivel puede abogar por ordenanzas saludables, mejorar sus propios entornos, facilitar la participación de la comunidad y reorientar la consulta hacia la prevención y el acompañamiento.","La mediación entre intereses contrapuestos es parte del rol: no se trata solo de informar, sino de construir acuerdos con otros sectores para que la opción saludable sea también la más fácil."],"callout":{"tone":"info","title":"Idea para retener","text":"Promoción no es repartir folletos: es cambiar las condiciones que hacen difícil cuidarse y facilitar las que lo hacen posible."}}],"sheet-promocion-politica-01":[{"title":"Enfoques y determinantes","depth":"core","body":["La política se apoya en cuatro enfoques: territorial, de equidad en salud, de derechos humanos y de interculturalidad. El territorio no es solo un espacio físico: es un sistema de relaciones entre actores, instituciones, ambiente y cultura.","Las inequidades en salud son diferencias evitables e injustas. Para cerrarlas hay que actuar sobre los determinantes estructurales —gobernanza, políticas macroeconómicas, posición socioeconómica— y sobre los intermedios —condiciones materiales, trabajo, vivienda, alimentación—."]},{"title":"Los cuatro lineamientos","depth":"core","table":{"headers":["Lineamiento","Foco"],"rows":[["1. Salud como eje de todas las políticas","Incorporar la salud en la agenda de todos los sectores y niveles de gobierno."],["2. Persona, familia y comunidad en el centro","Gestión territorial con participación y decisión local."],["3. Abordaje de determinantes para cerrar brechas","Articular educación, vivienda, trabajo, ambiente y protección social."],["4. Empoderamiento y participación social","Fortalecer capacidades y control ciudadano sobre las decisiones."]]}},{"title":"Del discurso a la gestión territorial","depth":"full","body":["La unidad territorial básica propuesta es el distrito. Allí se pueden articular autoridades locales, instituciones, organizaciones sociales y sector salud. La coordinación intersectorial puede ser informativa, de cooperación, de coordinación o de integración; no son etapas rígidas y pueden coexistir.","La participación social tiene valor intrínseco —derecho a decidir sobre lo que afecta— y valor instrumental —mejora la pertinencia y sostenibilidad de las intervenciones—. La vigilancia ciudadana completa el ciclo al exigir rendición de cuentas."],"callout":{"tone":"warn","title":"Cuidado con la trampa sectorial","text":"Si salud planifica sola y luego pide apoyo, la intersectorialidad se vuelve trámite. Debe participar desde el diagnóstico y la priorización."}}],"sheet-modelo-sujetos-01":[{"title":"Tres sujetos, distintas necesidades","depth":"core","body":["El modelo reconoce a la persona como ser biopsicosocial inmerso en relaciones políticas, sociales, culturales y ecológicas. Las intervenciones son más efectivas cuando se adaptan a cada etapa de vida: niño, adolescente, joven, adulto y adulto mayor.","La familia es el espacio donde se aprenden normas, valores y conductas de salud; por eso se considera la unidad de intervención de mayor eficacia potencial. La comunidad aporta participación, reflexión, cooperación y movilización para sostener las acciones."]},{"title":"Escenarios donde se vive la salud","depth":"core","table":{"headers":["Escenario","Qué se promueve"],"rows":[["Vivienda","Saneamiento, ventilación, higiene, prevención de accidentes y convivencia."],["Municipio","Políticas públicas locales, espacios públicos y entornos saludables."],["Institución educativa","Habilidades para la vida, alimentación, actividad física y convivencia."],["Centro laboral","Entornos y conductas saludables para trabajadores y sus familias."],["Comunidad","Participación, redes sociales y movilización de recursos locales."]]}},{"title":"Los siete ejes temáticos","depth":"full","bullets":["Alimentación y nutrición saludable.","Higiene y ambiente.","Actividad física.","Salud sexual y reproductiva.","Habilidades para la vida.","Seguridad vial y cultura de tránsito.","Promoción de la salud mental, buen trato y cultura de paz."],"callout":{"tone":"info","title":"No son compartimentos","text":"Una intervención escolar sobre alimentación también puede fortalecer habilidades para la vida y salud mental. Los ejes se combinan en cada escenario."}}],"sheet-modelo-programas-01":[{"title":"Familias y viviendas saludables","depth":"core","body":["El programa busca que las familias adopten prácticas de cuidado y que la vivienda ofrezca condiciones seguras: saneamiento básico, ventilación, higiene, cocina saludable y prevención de accidentes. La vivienda se entiende como parte del entorno que condiciona la salud, no solo como un espacio físico.","Las acciones se conciertan con otros sectores para mejorar infraestructura, saneamiento y actividades productivas. La familia es el punto de entrada para cambiar rutinas de alimentación, higiene y convivencia."]},{"title":"Municipios, escuelas y centros laborales","depth":"core","bullets":["Municipio saludable: autoridades, instituciones y sociedad civil mejoran condiciones de vida y entornos con políticas públicas locales.","Institución educativa saludable: involucra a docentes, directivos, familias, estudiantes y líderes escolares en comportamientos y entornos saludables.","Centro laboral saludable: aprovecha el tiempo de trabajo para promover actividad física, alimentación, salud mental y prevención de riesgos."]},{"title":"Cómo se articulan","depth":"full","body":["Los programas comparten enfoques y estrategias: abogacía y políticas públicas, comunicación y educación para la salud, participación comunitaria y acción intersectorial. No son campañas aisladas: cada uno debe insertarse en el plan operativo de la institución y en el presupuesto disponible.","El sector salud cumple un rol facilitador: sensibiliza, brinda asistencia técnica, articula actores y acompaña la evaluación. La sostenibilidad depende de que la comunidad y las autoridades locales asuman el proceso."],"callout":{"tone":"info","title":"Regla práctica","text":"Un programa sin actor local que lo sostenga se apaga cuando termina la campaña."}}],"sheet-municipios-01":[{"title":"Qué es un municipio saludable","depth":"core","body":["Es un espacio territorial donde las políticas públicas han consolidado entornos y comportamientos saludables para personas, familias y comunidades. Requiere la participación de autoridades políticas y civiles, instituciones, organizaciones y ciudadanía.","El programa tiene dos componentes: el municipio (gobierno local, espacios públicos) y la comunidad (organizaciones, barrios, zonas rurales y urbano marginales). Ambos comparten las mismas fases."]},{"title":"Las cinco fases","depth":"core","table":{"headers":["Fase","Producto o sentido"],"rows":[["1. Sensibilización","Identificar el municipio, capacitar al personal y lograr el acta de compromiso."],["2. Organización","Conformar el comité multisectorial distrital o provincial."],["3. Planificación participativa","Elaborar y aprobar el plan de acción con los actores locales."],["4. Ejecución","Implementar las acciones y proyectos priorizados."],["5. Seguimiento y evaluación participativa","Revisar avances y ajustar; acompaña todo el proceso."]]}},{"title":"Actores y evaluación","depth":"full","body":["El personal de salud facilita el proceso, articula recursos y brinda acompañamiento técnico. La municipalidad lidera la política local; la comunidad organizada participa en la identificación de problemas y en las decisiones.","La evaluación no es solo un informe final: es un proceso continuo de reflexión sobre lo logrado. Se evalúan la participación social, la intersectorialidad, las ordenanzas y políticas públicas y la sostenibilidad de los procesos."],"callout":{"tone":"info","title":"El acta no es el final","text":"Firmar el compromiso abre el proceso; la fase de organización y el plan participativo son las que lo vuelven operativo."}}],"sheet-escuelas-01":[{"title":"Qué es una escuela saludable","depth":"core","body":["El programa busca contribuir al desarrollo humano integral de los estudiantes y de la comunidad educativa mediante acciones de promoción de la salud en las instituciones educativas. Una escuela saludable es aquella que ha alcanzado estándares de mejora en su entorno y cuya comunidad mantiene comportamientos saludables en la vida cotidiana.","No se trata solo de transmitir información: se interviene sobre el ambiente físico, las relaciones interpersonales, las políticas escolares y la participación de las familias."]},{"title":"Cuatro líneas de acción","depth":"core","table":{"headers":["Línea","Qué implica"],"rows":[["Comportamientos saludables","Educación y desarrollo de habilidades para la alimentación, higiene, actividad física, salud sexual y salud mental."],["Entornos saludables","Espacios físicos seguros, limpios, ventilados y con condiciones para la actividad física."],["Intersectorialidad","Articulación entre salud, educación, municipalidad y organizaciones locales."],["Políticas que promueven salud","Normas escolares sobre tabaco, alimentación, convivencia y actividad física."]]}},{"title":"Cómo se organiza","depth":"full","body":["El consejo educativo institucional reúne al director, subdirector, representantes de docentes y estudiantes, y al personal de salud de la jurisdicción. El sector salud brinda asistencia técnica y capacitación; la escuela lidera la implementación.","Los ejes temáticos se adaptan a la realidad local. Se recomienda usar materiales educativos pertinentes y formar a docentes para que repliquen las sesiones con estudiantes y familias."],"callout":{"tone":"info","title":"El ejemplo también educa","text":"Una escuela que vende comida ultraprocesada en su kiosco y no facilita actividad física contradice el mensaje que enseña."}}],"sheet-agente-01":[{"title":"Quién es y qué hace","depth":"core","body":["El agente comunitario de salud (ACS) es una persona elegida o reconocida por su comunidad. Realiza acciones voluntarias de promoción de la salud y prevención de enfermedades en coordinación con el personal de salud y otras instituciones locales, y cumple un rol articulador entre la comunidad y las autoridades.","Su labor se centra inicialmente en salud materno-perinatal y nutrición infantil, y luego se amplía a otras etapas de vida. Apoya campañas, vigilancia comunitaria y actividades de educación."]},{"title":"Tres niveles de rol","depth":"core","table":{"headers":["Nivel","Rol"],"rows":[["Básico","Educador sanitario: promueve comportamientos saludables, primeros auxilios y referencia de riesgos."],["Intermedio","Supervisor-capacitador: apoya y capacita a otros agentes."],["Avanzado","Gestor comunal: articula con autoridades, presupuesto participativo y determinantes sociales."]]}},{"title":"Formación y sostenibilidad","depth":"full","bullets":["Capacitación básica inicial para ser reconocido como ACS.","Capacitación continua y recalificación anual.","Criterios de calificación: >80% de asistencia, >75% de logros de aprendizaje y evaluación.","Compromiso mínimo de dos años; inactividad tras tres meses sin reportar actividades.","Evitar que el ACS financie de su bolsillo sus traslados o alimentación; gestionar incentivos y reconocimiento."],"callout":{"tone":"warn","title":"Voluntario no significa sin apoyo","text":"La sostenibilidad depende de capacitación, reconocimiento, condiciones y compensación de gastos operativos."}}],"sheet-agua-01":[{"title":"Qué significa agua apta","depth":"core","body":["El reglamento define el agua de consumo humano como aquella apta para beber y para todo uso doméstico habitual, incluida la higiene personal. El agua tratada es la que fue sometida a procesos físicos, químicos o biológicos para volverla inocua.","La norma busca garantizar la inocuidad, prevenir factores de riesgo sanitario y proteger la salud. Se aplica a toda persona natural o jurídica, pública o privada, que produzca, transporte, almacene o suministre agua."]},{"title":"Límites que importan en la práctica","depth":"core","table":{"headers":["Parámetro","Referencia"],"rows":[["Coliformes totales, termotolerantes y E. coli","0 UFC/100 mL"],["Bacterias heterotróficas","menos de 500 UFC/mL a 35 °C"],["Cloro residual libre","no menos de 0,5 mg/L en la red"],["pH","6,5 a 8,5"],["Turbiedad","5 UNT"],["Arsénico","0,010 mg/L"],["Plomo","0,010 mg/L"],["Mercurio","0,001 mg/L"]]}},{"title":"Roles y obligaciones","depth":"full","bullets":["DIGESA: política nacional, normas de vigilancia y consolidación de información.","DIRESA, GRS o DISA: vigilancia y control en su jurisdicción.","Proveedor: plan de control de calidad, tratamiento, muestreo y medidas correctivas.","Consumidor: usar y almacenar el agua de forma segura y colaborar con el cuidado de la fuente."],"callout":{"tone":"warn","title":"No todo pozo es una fuente segura","text":"La vigilancia debe cubrir también camiones cisterna, surtidores y conexiones provisionales, no solo la red formal."}}],"sheet-agua-02":[{"title":"Vigilar no es lo mismo que controlar","depth":"core","body":["El proveedor controla la calidad de su sistema: trata, muestrea y corrige. La autoridad sanitaria vigila la calidad del agua que llega a la población y fiscaliza el cumplimiento. Ambas funciones se complementan, pero no se sustituyen.","La vigilancia incluye inspecciones, muestreos, revisión de registros y análisis de información. Si detecta un riesgo, puede emitir medidas de seguridad y sanciones."]},{"title":"Respuesta ante un resultado adverso","depth":"core","table":{"headers":["Hallazgo","Respuesta inmediata"],"rows":[["Coliformes totales o termotolerantes en la red","Investigar causas, corregir y muestrear a diario hasta dos resultados negativos consecutivos."],["Parámetro químico sobre el límite","Repetir el muestreo; si se confirma, investigar y comunicar a la autoridad sanitária."],["Emergencia o desastre natural","Excepción temporal otorgada por la autoridad, sin daño a la salud."],["Incumplimiento del proveedor","Fiscalización, medidas de seguridad y sanción."]]}},{"title":"Comunicar también es proteger","depth":"full","body":["La norma incluye la difusión y el acceso a la información sobre la calidad del agua. Una comunidad informada puede exigir mejoras, proteger sus reservorios y adoptar prácticas seguras de almacenamiento.","El registro oportuno de muestras, resultados y acciones correctivas permite reconstruir lo ocurrido y evaluar si la respuesta fue suficiente."],"callout":{"tone":"info","title":"Para recordar","text":"Un resultado negativo aislado no cierra el problema: hay que demostrar que la corrección funcionó."}}],"sheet-ambiental-politica-01":[{"title":"El ambiente como determinante","depth":"core","body":["La política señala que la salud depende de alimentación inocua, vivienda saludable, trabajo digno, educación y condiciones ambientales adecuadas. El agua contaminada, el aire sucio, los residuos mal manejados y los vectores producen enfermedades que afectan sobre todo a los más pobres.","La salud ambiental no es un tema exclusivo del sector salud: es transversal y requiere articulación con vivienda, agricultura, ambiente, trabajo y gobiernos locales."]},{"title":"Cinco principios","depth":"core","bullets":["Respeto a la vida en un entorno saludable.","Enfoque preventivo, antes que remedial.","Decisiones basadas en evidencia científica.","Facilitación del comercio que fomenta la salud.","Transparencia y participación de la población."]},{"title":"Los problemas prioritarios","depth":"full","table":{"headers":["Ámbito","Ejemplo de riesgo"],"rows":[["Agua y recursos hídricos","Contaminación bacteriana, metales, vertimientos."],["Aire","Partículas y gases de transporte, industria y cocina."],["Alimentos","Contaminación microbiológica y química."],["Residuos sólidos","Vertederos abiertos y quema informal."],["Vectores y zoonosis","Dengue, roedores, animales de compañía."],["Sustancias peligrosas","Plaguicidas, mercurio, plomo y otros químicos."]]},"callout":{"tone":"info","title":"Mirada de equidad","text":"Los riesgos ambientales no se distribuyen por igual: suelen concentrarse en las poblaciones con menos recursos y menor capacidad de exigir protección."}}],"sheet-ambiental-politica-02":[{"title":"Las seis políticas","depth":"core","table":{"headers":["Política","Foco"],"rows":[["1. Agua de consumo humano","Vigilancia y fiscalización sanitaria; tecnologías intradomiciliarias en zonas dispersas."],["2. Inocuidad de alimentos","Producción, comercio y control sanitario; referencia al Codex Alimentarius."],["3. Calidad del aire","Estándares, estudios de costo-efectividad e intervenciones."],["4. Peligros y alertas","Recursos hídricos, residuos, químicos, vectores y zoonosis."],["5. Descentralización","Fortalecer capacidades regionales y locales."],["6. Emergencias y desastres","Planes de respuesta del sector salud."]]}},{"title":"Qué se espera del nivel local","depth":"core","body":["La política no se ejecuta solo desde Lima. Las DIRESA y los gobiernos locales deben vigilar el agua, los alimentos y los riesgos ambientales de su jurisdicción, con planes operativos y personal responsable.","La descentralización implica transferir funciones y capacidades, no solo responsabilidades. Sin presupuesto, laboratorio y personal capacitado, la vigilancia se queda en el papel."]},{"title":"Emergencias: prepararse antes","depth":"full","body":["Inundaciones, deslizamientos, derrames y otros eventos pueden contaminar el agua, afectar los alimentos y generar brotes. La política pide planes articulados y capacidad de respuesta oportuna.","La preparación incluye identificar fuentes de riesgo, mantener reservas y protocolos, y coordinar con defensa civil, gobiernos locales y otros sectores."],"callout":{"tone":"warn","title":"La emergencia no crea el riesgo","text":"Muchas veces lo visibiliza: agua insegura, viviendas mal ubicadas y sistemas de salud frágiles ya existían antes del desastre."}}],"sheet-metales-01":[{"title":"Exposición no es lo mismo que intoxicación","depth":"core","body":["La exposición es el contacto con una fuente de metales pesados o metaloides. La intoxicación implica daño a la salud. Una persona puede estar expuesta sin síntomas y aun así requerir seguimiento.","La norma define factor de riesgo como cualquier condición, característica o exposición que pueda producir daño. Las fuentes pueden ser naturales o antropogénicas: minería, fundición, industria, agua contaminada, alimentos o suelo."]},{"title":"Definiciones de caso","depth":"core","table":{"headers":["Tipo de caso","Criterio"],"rows":[["Sospechoso (expuesto)","Antecedente de exposición a fuente confirmada, sin manifestaciones clínicas."],["Probable","Cuadro clínico o resultado de laboratorio compatible, sin confirmación completa."],["Confirmado","Caso con confirmación clínica, epidemiológica o de laboratorio según la norma."],["Descartado","Investigación que excluye la exposición o la intoxicación."]]}},{"title":"Notificación y vigilancia","depth":"full","bullets":["Notificación mensual obligatoria de casos sospechosos, probables y confirmados.","Notificación negativa cuando no se presentan casos.","Notificación inmediata de contingencias por exposición.","Vigilancia pasiva a partir de las atenciones y vigilancia centinela en establecimientos seleccionados."],"callout":{"tone":"warn","title":"No esperar síntomas","text":"La exposición puede ser silenciosa. La vigilancia busca identificar riesgo antes de que aparezca el daño clínico."}}],"sheet-metales-02":[{"title":"Investigar antes de concluir","depth":"core","body":["La investigación epidemiológica reconstruye la cadena de exposición: fuente, vía, tiempo, población afectada y factores de riesgo. No basta con un resultado de laboratorio aislado; hay que interpretarlo con la historia de exposición y el cuadro clínico.","El equipo debe identificar localidades en riesgo, personas expuestas, actividades económicas y posibles fuentes ambientales: aire, agua, suelo y alimentos."]},{"title":"Plazos y productos","depth":"core","table":{"headers":["Producto","Plazo"],"rows":[["Notificación de contingencia","Inmediata"],["Informe preliminar de investigación","Dentro de 72 horas"],["Informe de seguimiento","Según evolución del evento"],["Informe final","Al concluir la investigación"],["Notificación mensual de casos","Cada mes, incluida la negativa"]]}},{"title":"Una respuesta que no termina en el laboratorio","depth":"full","body":["Confirmar un caso exige comunicar, orientar y derivar a la atención correspondiente. También implica coordinar con ambiente, minería, agricultura y gobiernos locales para controlar la fuente.","La información debe retroalimentar a los niveles local y regional mediante boletines, reportes y salas de situación. La vigilancia sirve para decidir, no solo para registrar."],"callout":{"tone":"info","title":"Pregunta clave","text":"Si se confirma un caso, ¿ya sabemos de dónde viene la exposición y quiénes más están expuestos?"}}],"sheet-psi-sp-1-1":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La salud pública se define por su objeto y por su método: toma como unidad de análisis a la población de un territorio y actúa sobre las condiciones que producen salud, enfermedad y brechas. Su resultado no es la mejoría de una persona concreta, sino el cambio en la frecuencia, la gravedad o la distribución de un problema colectivo. Por eso combina promoción, prevención, vigilancia, regulación, planificación y evaluación en una misma lógica de decisión.","Una función esencial es una capacidad, no un servicio. Se reconoce porque permanece en el tiempo, tiene responsables institucionales, consume recursos de forma estable y produce un resultado verificable incluso bajo presión. Una campaña puntual, un consultorio adicional o una compra de medicamentos pueden ser necesarios, pero no constituyen por sí mismos una función esencial: sin financiamiento oportuno, talento humano estable y registro confiable, la capacidad se pierde cuando termina el proyecto."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El mecanismo central es la cadena de determinantes. Las condiciones estructurales, como el ingreso, la educación y el territorio, ubican a los grupos en posiciones sociales distintas; esas posiciones definen determinantes intermedios, como vivienda, alimentación, trabajo, apoyo social y acceso a servicios; esos determinantes distribuyen la exposición y la vulnerabilidad, y de allí resultan las diferencias en enfermedad y muerte. La consecuencia práctica es directa: intervenir solo sobre el caso clínico deja intacta la exposición que sigue produciendo casos.","La segunda razón teórica es económica y organizacional. La vigilancia, el agua segura, la vacunación y la información sanitaria producen beneficios que no pueden reservarse a quien paga por ellos, mientras su costo se concentra en un presupuesto visible. Esa asimetría explica por qué el mercado no las provee en cantidad suficiente y por qué se requiere financiamiento público, rectoría y rendición de cuentas. Sin dato no hay prioridad, y sin prioridad explícita el presupuesto se reparte por presión y no por necesidad."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["Las once funciones se agrupan en cuatro fases que funcionan como un ciclo: cada fase entrega un producto que alimenta a la siguiente y devuelve información a la primera. Cuando una fase falla, el efecto aparece más adelante en forma de política mal priorizada, recurso mal asignado o acceso desigual, aunque el origen esté en la fase anterior. La tabla resume el producto esperado y la señal que revela una capacidad debilitada."],"table":{"headers":["Fase del ciclo","Producto que entrega","Señal de capacidad debilitada"],"rows":[["Evaluar","Diagnóstico con magnitud, distribución y tendencia","Se decide por anécdota o por presión del momento"],["Formular políticas","Prioridades explícitas con acuerdo de actores","Planes sin responsables ni plazos verificables"],["Asignar recursos","Talento humano, tecnologías y presupuesto oportuno","Brechas de personal y desabastecimiento recurrente"],["Garantizar acceso","Servicios integrales y acción sobre determinantes","Cobertura desigual y barreras que persisten"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Delimitar población, territorio y periodo antes de describir cualquier problema de salud.","2. Describir magnitud, gravedad, tendencia y distribución del daño por edad, sexo y territorio.","3. Comparar el hallazgo con una referencia regional o nacional para juzgar si existe un exceso.","4. Identificar los determinantes implicados y los actores que controlan cada uno de ellos.","5. Priorizar con criterios explícitos: magnitud, gravedad, tendencia, factibilidad, equidad y costo de oportunidad.","6. Asignar responsables, recursos y plazos por fase, con un producto verificable en cada una.","7. Ejecutar con monitoreo de cobertura y calidad, no solo de actividades realizadas.","8. Evaluar resultados, rendir cuentas y ajustar la política con la evidencia producida."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un distrito de la sierra, el centro de salud registra un aumento de infecciones respiratorias en menores de cinco años durante los meses fríos. La DIRESA solicita un plan de respuesta. El equipo revisa los registros y encuentra que varias viviendas cocinan con leña dentro de la cocina y que dos escuelas tienen aulas cerradas y con grupos numerosos. La municipalidad ofrece donar medicamentos, la escuela propone reabrir ventanas y las familias piden más consultorios. El equipo acuerda medir el problema por sector, priorizar ventilación y cocinas mejoradas, sostener la atención de los casos y pactar con la municipalidad y la UGEL responsables y plazos. Al trimestre siguiente disminuyen las consultas por infección respiratoria y mejora la asistencia escolar."],"bullets":["Lectura del caso: el problema se define en la población y no en el consultorio, por eso la respuesta convoca a vivienda, educación y salud.","Lectura del caso: donar medicamentos atiende el episodio, pero no modifica la exposición al humo ni el hacinamiento del aula.","Lectura del caso: la fase de evaluar produjo magnitud y distribución; sin ese dato la prioridad habría sido la presión del momento.","Lectura del caso: se evita confundir una función esencial con un servicio asistencial y se fijan responsables verificables."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: salud pública no es medicina clínica, porque su unidad de análisis es la población y su resultado se mide con indicadores colectivos.","Distinción: multisectorial no es intersectorial; lo primero convoca a varios sectores y lo segundo exige responsabilidades y recursos compartidos.","Error: llamar función esencial a una campaña puntual, porque la capacidad debe sostenerse y funcionar bajo presión.","Error: atribuir el problema a la conducta individual, porque omitir los determinantes que distribuyen la exposición conduce a intervenciones ineficaces.","Distinción: promoción no es prevención; la primera actúa sobre condiciones y capacidades y la segunda sobre riesgos específicos.","Error: medir la gestión por actividades realizadas, porque el resultado se verifica en cobertura, calidad y reducción de brechas.","Distinción: política no es plan operativo; la política fija prioridades y el plan asigna responsables, recursos y plazos."]},{"title":"Puntos clave","depth":"core","bullets":["La unidad de análisis es la población: sin denominador poblacional no se puede juzgar la magnitud de un problema.","Las once funciones se agrupan en cuatro fases encadenadas, y una falla al evaluar se paga en políticas mal priorizadas.","La participación y movilización social pertenece a la formulación de políticas, junto con la legislación y la rectoría.","Sostener una función exige financiamiento oportuno y talento humano estable, no solo lineamientos escritos.","La acción sobre determinantes sociales es una función esencial y no un añadido de la promoción.","Rendir cuentas cierra el ciclo, porque convierte el gasto en resultados verificables y permite corregir la política."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Fase antes que servicio","text":"Ante un caso conviene preguntar primero si la respuesta es poblacional, intersectorial y sostenida. Si lo es, el distractor típico ofrece atención individual, compra de medicamentos o una campaña aislada. Después corresponde ubicar la fase: evaluar, formular políticas, asignar recursos o garantizar acceso. La participación social se ubica en la formulación, junto con la legislación."}},{"title":"Rol del psicólogo en las funciones esenciales","depth":"core","bullets":["Aporta al monitoreo de salud mental con registros de tamizaje, demanda y continuidad del cuidado en el primer nivel.","Sostiene la vigilancia de eventos de salud mental y de violencia, con definiciones de caso claras y notificación oportuna.","Diseña y evalúa intervenciones de promoción con la comunidad, la escuela y la municipalidad, midiendo cobertura y no solo asistencia.","Asesora la formulación de políticas locales con evidencia sobre barreras de acceso y determinantes psicosociales.","Participa en la asignación de talento humano y en la capacitación del equipo para detectar y derivar casos.","Rinde cuentas con indicadores comprensibles para la comunidad y para la autoridad sanitaria."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OPS/OMS — Las funciones esenciales de salud pública en las Américas, 2020.","Fuente: OMS — Primary health care, servicios integrados, acción multisectorial y participación.","Fuente: OMS — A conceptual framework for action on the social determinants of health, determinantes estructurales e intermedios."]}],"sheet-psi-sp-1-2":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["Todo indicador epidemiológico es un cociente y cada cociente exige tres decisiones: qué evento se cuenta, qué población se usa como referencia y en qué intervalo se observa. Cambiar cualquiera de esas piezas cambia el significado aunque la cifra permanezca. Un mismo número puede describir riesgo, carga o gravedad según el denominador elegido, y por eso la primera tarea no es calcular sino formular la pregunta que se quiere responder.","Razón, proporción y tasa no son sinónimos. La razón compara dos cantidades independientes y su valor no está acotado; la proporción compara una parte con el total que la contiene y se expresa entre cero y uno; la tasa incorpora el tiempo en el denominador y por eso comunica velocidad. Confundir estas formas produce afirmaciones que suenan técnicas pero no responden a la pregunta original, como presentar una razón de masculinidad como si fuera una proporción de la población."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El mecanismo que ordena las medidas es el tránsito entre estados: una persona susceptible pasa a ser caso y luego se recupera, permanece enferma o muere. La incidencia mide el flujo de entrada a ese estado y la prevalencia mide el volumen acumulado dentro de él. En una población estable, la prevalencia se aproxima al producto de la incidencia por la duración media del problema, de modo que sube si aumentan los casos nuevos, si la enfermedad dura más o si se detectan más casos que antes permanecían ocultos.","Esa relación explica por qué un aumento de prevalencia no equivale a un aumento de riesgo. Puede crecer porque mejora la supervivencia, porque el tratamiento convierte un problema agudo en crónico o porque el registro se amplió; las tres situaciones llevan a decisiones sanitarias distintas. Del mismo modo, la mortalidad puede descender por mejor tratamiento sin que la incidencia cambie, y la letalidad puede bajar mientras la carga poblacional aumenta. El indicador aislado nunca basta: hay que leerlo junto con la tendencia y con la fuente del dato."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["Elegir la medida es elegir la pregunta. La tabla ordena las medidas de uso frecuente por su numerador, su denominador y la pregunta que responden, de modo que la decisión se justifique antes del cálculo y no después."],"table":{"headers":["Medida","Numerador","Denominador","Pregunta que responde"],"rows":[["Incidencia acumulada","Casos nuevos del periodo","Personas libres del problema al inicio","¿Qué riesgo tiene una persona de desarrollarlo?"],["Densidad de incidencia","Casos nuevos del periodo","Persona-tiempo en riesgo","¿A qué velocidad aparecen los casos?"],["Prevalencia puntual","Casos existentes en la fecha","Población en ese momento","¿Cuánta carga existe hoy?"],["Tasa de ataque","Casos entre expuestos","Personas expuestas al brote","¿Qué proporción enfermó tras la exposición?"],["Mortalidad","Defunciones por la causa","Población total del periodo","¿Cuál es el impacto de la muerte en la población?"],["Letalidad","Defunciones por la causa","Casos de esa causa","¿Qué tan grave es entre quienes enferman?"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Formular la pregunta: frecuencia, riesgo, gravedad o impacto poblacional.","2. Definir el evento con un criterio verificable y estable a lo largo del tiempo.","3. Fijar población, territorio y periodo antes de contar los eventos.","4. Excluir del denominador a quienes no podían presentar el evento.","5. Decidir si se cuenta personas o persona-tiempo según el seguimiento disponible.","6. Calcular y expresar el resultado con base, periodo y fuente del dato.","7. Comparar con una referencia y revisar exhaustividad, duplicados y cambios de definición.","8. Comunicar el denominador junto con la cifra, porque sin él la cifra no es interpretable."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Un centro de salud de la costa informa que la depresión afecta a 40 de cada 100 personas del distrito. El dato proviene de 250 tamizajes aplicados en el consultorio, con 100 resultados positivos. La DIRESA pide verificar la cifra antes de difundirla. El equipo revisa la fuente: las personas tamizadas acudieron por algún motivo, muchas tenían antecedente de malestar y el tamizaje no confirma diagnóstico. Calcula la proporción de positividad, la presenta como rendimiento del tamizaje y propone una encuesta poblacional para estimar prevalencia. Revisa además la cobertura: los tamizajes se aplicaron solo a quienes acudieron al servicio, de modo que la población con barreras de acceso quedó fuera. Advierte que sin seguimiento de personas libres del problema no puede calcular incidencia. La comunicación final distingue tamizaje, diagnóstico y carga poblacional."],"bullets":["Lectura del caso: el denominador eran personas tamizadas y no habitantes, así que el cociente describe rendimiento y no prevalencia.","Lectura del caso: un tamizaje positivo no equivale a diagnóstico confirmado, y confundirlos sobreestima la carga y estigmatiza.","Lectura del caso: se descartó presentar el dato como incidencia, porque no hubo seguimiento de personas libres del problema.","Lectura del caso: explicitar denominador y fuente evita que la cifra circule sin contexto y termine convertida en política."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: incidencia no es prevalencia, porque la primera cuenta casos nuevos y la segunda casos existentes.","Error: dividir casos nuevos entre la población total, porque el cociente cambia según cuántos ya tenían el problema.","Distinción: letalidad no es mortalidad; la primera usa como denominador a los enfermos y la segunda a la población.","Distinción: tasa no es proporción, porque la tasa incorpora el tiempo en el denominador y expresa velocidad.","Error: comparar tasas de periodos con definiciones distintas, porque el cambio puede reflejar el registro y no la enfermedad.","Error: interpretar una proporción de positividad como prevalencia, porque el denominador son personas que buscaron atención.","Distinción: prevalencia de periodo no es puntual; la primera acumula casos presentes en un lapso y la segunda en una fecha."]},{"title":"Puntos clave","depth":"core","bullets":["Toda medida necesita evento, denominador y periodo; sin los tres la cifra no es interpretable.","La incidencia responde al riesgo y la prevalencia responde a la carga, que también depende de la duración.","Un aumento de prevalencia puede reflejar más casos, mayor supervivencia o mejor detección.","La letalidad mide gravedad entre quienes enfermaron y no debe presentarse como riesgo de la población.","El denominador debe excluir a quienes no podían presentar el evento para no diluir el riesgo.","Los datos consolidados permiten calcular indicadores; los individuales exigen protección de la identidad."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"El denominador primero","text":"Casos nuevos llevan a incidencia; carga total lleva a prevalencia; gravedad entre enfermos lleva a letalidad; muertes en la población llevan a mortalidad. Antes de elegir, revise el denominador y el periodo. El distractor habitual conserva la etiqueta y cambia el denominador, o presenta la proporción de positividad como prevalencia poblacional."}},{"title":"Lectura del indicador en el primer nivel","depth":"core","body":["En un establecimiento del primer nivel, el registro asistencial describe demanda y no enfermedad de la comunidad. Las consultas contabilizan atenciones y no personas, de modo que una misma persona con varios controles infla el numerador sin cambiar el riesgo poblacional. Para usar ese registro como indicador se necesita depurar duplicados, definir el episodio y comparar contra la población asignada al establecimiento.","La utilidad práctica aparece cuando el equipo distingue tres preguntas: cuántas personas con un problema fueron captadas, qué proporción de la población asignada representan y cuántas continuaron el cuidado. La captación temprana se evalúa con la fracción de casos detectados antes de la complicación; la continuidad, con el seguimiento efectivo. Ninguna de esas preguntas se responde con el número de consultas ni con el número de tamizajes aplicados."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 3: medidas de frecuencia.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 2: medidas estadísticas.","Fuente: MINSA — Contenidos temáticos oficiales SERUMS 2026-II, Psicología."]}],"sheet-psi-sp-1-3":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["Una exposición es cualquier condición que precede al desenlace y que podría modificarlo: un turno laboral, una pérdida, un tóxico ambiental o una intervención. Un factor de riesgo es una exposición asociada con mayor probabilidad del daño, y un factor protector es una exposición asociada con menor probabilidad. En ambos casos la palabra factor describe una relación probabilística y no una sentencia: la presencia del factor no determina el desenlace en cada persona, y su ausencia no garantiza protección.","La causalidad se plantea como una pregunta contrafactual: qué habría ocurrido con la misma persona si no hubiera estado expuesta. Como esa comparación nunca se observa completa, se aproxima con un grupo de comparación que debería ser intercambiable. Toda la metodología epidemiológica gira alrededor de esa sustitución: si los grupos difieren en algo distinto de la exposición, la diferencia observada no puede atribuirse con limpieza a la exposición."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["Una asociación puede aparecer por cuatro vías distintas y solo una es causal. El azar produce asociaciones por variación del muestreo; el sesgo de selección las produce porque la entrada o la permanencia en el estudio depende del desenlace o de la exposición; el sesgo de información las produce porque la medición difiere entre grupos; y la confusión las produce porque un tercer factor antecede y se asocia con ambos. A esas vías se añade la causalidad inversa, cuando el desenlace o su pródromo modifican la exposición observada.","Los criterios de Hill no funcionan como un puntaje. Fueron propuestos como consideraciones para juzgar si una asociación admite una interpretación causal, y su valor está en el conjunto y en el diseño que la sostiene. La fuerza y el gradiente biológico son los apoyos más sólidos cuando la medición es buena, porque un error de medición no genera por sí solo una relación dosis-respuesta ordenada. La especificidad ayuda poco en daños multifactoriales, y la plausibilidad depende del conocimiento disponible en cada momento."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["Los nueve criterios se ordenan en tres grupos según lo que aportan. La temporalidad es una condición lógica sin la cual no existe hipótesis causal posible. La fuerza, el gradiente y la consistencia aportan apoyo empírico. La especificidad, la plausibilidad, la coherencia, el experimento y la analogía aportan apoyo interpretativo. La tabla formula cada criterio como pregunta y señala su límite, porque el error más frecuente es convertir el apoyo en demostración."],"table":{"headers":["Criterio","Pregunta que obliga a responder","Límite o mal uso"],"rows":[["Temporalidad","¿La exposición ocurrió antes del desenlace?","Único criterio indispensable; sin él no hay inferencia posible"],["Fuerza","¿Qué tan alejada de uno está la medida de asociación?","Una asociación fuerte también puede deberse a confusión no medida"],["Consistencia","¿Se repite en poblaciones, lugares y diseños distintos?","La repetición puede reflejar el mismo sesgo replicado"],["Especificidad","¿La exposición se vincula con un efecto particular?","Suele faltar en daños multifactoriales"],["Gradiente biológico","¿El efecto cambia con la dosis o la intensidad?","Puede no aparecer cuando existe un umbral de daño"],["Plausibilidad y coherencia","¿Existe mecanismo compatible y encaje con otra evidencia?","Un mecanismo desconocido no refuta por sí solo la asociación"],["Experimento y analogía","¿Modificar la exposición modifica el desenlace?","Los ensayos no siempre son éticos ni factibles"]]}},{"title":"Modelos de causalidad y piezas de Rothman","depth":"full","body":["El modelo unicausal explica de forma aceptable algunos daños infecciosos o tóxicos, donde un agente identificable resulta necesario, aunque el desenlace real también dependa del huésped. El modelo multicausal describe mejor los problemas crónicos y de salud mental, porque varios factores interactúan de manera probabilística y ninguno explica todos los casos. La tríada epidemiológica ordena esa interacción en agente, huésped y ambiente, y evita que identificar un agente haga olvidar las otras dos dimensiones.","La propuesta de Rothman representa cada mecanismo como un pastel: la causa suficiente es el conjunto completo de causas componentes que produce el desenlace, y puede haber varios pasteles para un mismo daño. La causa necesaria aparece en todos los pasteles, pero por sí sola no basta. La consecuencia preventiva es clara: bloquear una causa componente impide los mecanismos que la contienen, aunque no sea necesario eliminar todas las piezas para reducir la incidencia."],"table":{"headers":["Concepto","Definición operativa","Cómo se reconoce en un informe"],"rows":[["Modelo unicausal","Una causa específica se plantea como explicación directa del efecto","Se nombra un agente y se atribuye el daño sin analizar condiciones del huésped"],["Modelo multicausal","Varios factores interactúan de manera probabilística","Se describen factores personales, ambientales y sociales en conjunto"],["Tríada epidemiológica","Agente, huésped y ambiente interactúan","El análisis separa las tres dimensiones y las relaciona"],["Causa suficiente","Conjunto completo de componentes que produce el desenlace","Se describe un mecanismo completo y se reconocen otros posibles"],["Causa componente","Factor que integra un mecanismo pero no basta solo","Se identifica una pieza cuya remoción interrumpe ese mecanismo"],["Causa necesaria","Factor presente en todos los mecanismos del daño","Sin ese factor el desenlace no ocurre en ningún caso conocido"]]}},{"title":"Medidas de asociación y de impacto","depth":"full","body":["En una cohorte seguida un año, con 20 enfermos entre 100 expuestos y 10 entre 100 no expuestos, la incidencia acumulada es 20 % en expuestos y 10 % en no expuestos. El riesgo relativo es 2, el odds ratio es 2,25 y la diferencia de riesgos es 0,10. La fracción atribuible en expuestos es 50 %. Las cuatro cifras provienen de la misma tabla y responden preguntas distintas, así que ninguna reemplaza a las otras.","La lectura correcta separa lo relativo de lo absoluto. Diez puntos porcentuales es una diferencia absoluta, mientras que un 100 % de incremento relativo describe el paso de 10 % a 20 %; no son magnitudes intercambiables y la segunda suena más alarmante sin informar más. El riesgo atribuible poblacional estima cuánto descendería el riesgo de toda la población si se eliminara la exposición, pero interpretarlo como evitable exige causalidad y una intervención pertinente. Una asociación sola no autoriza esa promesa."],"table":{"headers":["Medida","Qué compara","Uso en la decisión"],"rows":[["Riesgo relativo","Riesgo de expuestos sobre riesgo de no expuestos","Juzgar fuerza de la asociación y orientar hipótesis"],["Odds ratio","Odds de expuestos sobre odds de no expuestos","Estimar asociación en casos y controles"],["Diferencia de riesgos","Riesgo de expuestos menos riesgo de no expuestos","Dimensionar el exceso absoluto y la carga esperada"],["Fracción atribuible","Proporción del riesgo de expuestos atribuible a la exposición","Estimar el beneficio potencial de retirar la exposición"]]}},{"title":"Validez interna y externa","depth":"core","body":["La validez interna pregunta si la comparación del estudio estima lo que dice estimar, es decir, si el efecto observado se debe a la exposición y no al azar, al sesgo o a la confusión. La validez externa pregunta si ese resultado se sostiene en otra población, otro territorio u otro momento. Son exigencias distintas y no se compensan: un estudio internamente inválido no se vuelve útil por ser representativo, y un estudio internamente sólido puede no ser transportable si el contexto local cambia la exposición o el acceso.","La distinción tiene consecuencias prácticas para el equipo de salud. Antes de aplicar un hallazgo a la población asignada hay que comparar la definición del desenlace, la composición de la población, la intensidad de la exposición y la existencia de servicios que hagan posible la intervención. Cuando esas condiciones difieren, la decisión razonable es adaptar y evaluar localmente, no extrapolar la magnitud del efecto como si fuera una constante."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Verificar la temporalidad antes de discutir cualquier otro criterio.","2. Descartar el azar con intervalo de confianza y revisión de la potencia del estudio.","3. Revisar sesgo de selección, pérdidas y forma de ingreso de los participantes.","4. Revisar sesgo de información y errores diferenciales en la medición de exposición y desenlace.","5. Identificar confusores plausibles y decidir si se controlan por diseño, estratificación o ajuste.","6. Valorar magnitud, gradiente y consistencia con otros estudios y con el mecanismo conocido.","7. Clasificar la evidencia como suficiente, limitada o insuficiente, explicitando los supuestos.","8. Traducir la evidencia en una recomendación graduada y señalar qué dato local falta para decidir."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Un equipo de salud mental de una DIRESA revisa un informe que compara adolescentes que asistieron a talleres de habilidades sociales con quienes no asistieron. Los asistentes presentan menos síntomas de ansiedad al final del año y el informe concluye que el taller reduce la ansiedad. El informe no describe cómo se midió la ansiedad ni si hubo evaluación al inicio del periodo. El equipo observa que la asistencia fue voluntaria, que varios participantes fueron derivados por docentes atentos y que los adolescentes con menos síntomas tenían más disponibilidad para asistir. El informe tampoco midió el nivel socioeconómico ni el apoyo familiar, asociados con ambas variables, y no registró cuántos abandonaron el taller. El equipo propone un diseño con asignación aleatoria y medición basal, y mientras tanto presenta el hallazgo como asociación exploratoria."],"bullets":["Lectura del caso: la asociación es compatible con causalidad inversa, porque el malestar previo pudo impedir la asistencia al taller.","Lectura del caso: la asistencia voluntaria y la derivación docente introducen sesgo de selección que la comparación no corrige.","Lectura del caso: sin medición basal ni control de confusores, el resultado no sostiene una recomendación de política.","Lectura del caso: se evita convertir una asociación exploratoria en efectividad comprobada y se propone un diseño que permita inferir."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: asociación no es causalidad, porque el azar, el sesgo y la confusión producen asociaciones sin mecanismo.","Distinción: confusión no es modificación de efecto; la primera distorsiona y la segunda describe diferencias reales entre grupos.","Distinción: riesgo relativo no es riesgo absoluto, porque duplicar un riesgo pequeño puede ser irrelevante en salud pública.","Error: usar el odds ratio como si fuera riesgo relativo, porque solo lo aproxima cuando el evento es raro.","Error: sumar criterios de Hill como puntaje, porque la inferencia exige juicio sobre el conjunto y sobre el diseño.","Distinción: factor de riesgo no es marcador de riesgo; el factor se asocia causalmente con el desenlace y el marcador solo predice su probabilidad.","Error: ajustar por una variable que forma parte del mecanismo, porque el ajuste elimina el efecto que se quiere estimar."]},{"title":"Puntos clave","depth":"core","bullets":["La temporalidad es el único criterio indispensable, y sin ella no existe inferencia causal posible.","El diseño manda: la aleatorización produce grupos intercambiables y reduce la confusión no medida.","La confusión se previene al diseñar y se controla al analizar, pero el ajuste no repara un sesgo de selección.","Las medidas relativas exageran cuando el riesgo basal es bajo, y la decisión necesita también la diferencia absoluta.","El riesgo atribuible traduce el efecto en carga evitable y por eso orienta la prioridad sanitaria.","La validez externa no compensa la interna, porque un resultado sesgado no se vuelve útil por ser generalizable."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Temporalidad y magnitud","text":"Si el enunciado indica que la exposición precede al desenlace, la respuesta se refiere a temporalidad, el único criterio indispensable. Si ofrece un cociente alejado de uno, se refiere a fuerza. El distractor habitual convierte la lista de Hill en un puntaje o confunde confusión con modificación de efecto. Una asociación puede calcularse bien y estar distorsionada."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 1: causalidad e historia natural.","Fuente: OPS — Glosario sobre brotes y epidemias: un recurso para periodistas y comunicadores."]}],"sheet-psi-sp-1-4":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La demografía aporta los denominadores de casi todos los indicadores de salud. Su objeto tiene dos partes: la estructura, que se observa en un corte y describe cuántas personas hay en cada edad y sexo, y la dinámica, que explica cómo esa estructura cambia por nacimientos, defunciones y migraciones. Sin esas piezas no se puede comparar la frecuencia de un problema entre territorios, porque poblaciones del mismo tamaño pueden tener composiciones de edad muy distintas.","Los indicadores demográficos se expresan como tasas o razones y siempre requieren población y periodo. La tasa bruta de natalidad relaciona nacimientos con la población total; la fecundidad general relaciona nacimientos con mujeres en edad fértil, de 15 a 49 años; la razón de dependencia compara los grupos de 0 a 14 años y de 65 a más con la población de 15 a 64 años. Cada una responde a una pregunta distinta y ninguna sustituye a las otras."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La transición demográfica describe un recorrido con dos caídas sucesivas. Primero desciende la mortalidad, sobre todo la infantil, y la población crece porque sobreviven más personas; después desciende la fecundidad y el crecimiento se desacelera; al final, con mortalidad y natalidad bajas, la estructura envejece. El orden importa: si la fecundidad cayera antes que la mortalidad, el crecimiento se frenaría de inmediato, y si la mortalidad no cayera, el volumen poblacional no aumentaría.","La pirámide es un registro de cohortes y no una fotografía instantánea. Una caída de nacimientos produce un angostamiento en la base que se desplaza con los años y envejece con quienes nacieron después; una epidemia o una guerra deja una muesca que permanece visible durante décadas. Esa propiedad explica por qué la estructura actual contiene información sobre la demanda futura, y por qué una proyección construida sobre la estructura de hace años conduce a decisiones equivocadas.","El bono demográfico es la fase transitoria en que la población en edad de trabajar supera a los grupos dependientes. No produce beneficios por sí mismo: exige inversión en educación, empleo y protección social para que esa ventaja se convierta en capacidad instalada. Cuando la fecundidad baja de forma sostenida, la relación se invierte y la dependencia vuelve a subir por envejecimiento, con mayor demanda de cuidado y de servicios de salud."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["Los indicadores se eligen según la decisión que deben informar. La tabla los ordena por su forma de cálculo en palabras y por lo que cada uno no permite concluir, porque el uso más frecuente consiste en pedirle al indicador algo que no puede responder."],"table":{"headers":["Indicador","Cómo se calcula","Qué informa","Qué no permite concluir"],"rows":[["Natalidad","Nacidos vivos sobre población total, por mil","Frecuencia de nacimientos","La capacidad reproductiva de las mujeres"],["Fecundidad general","Nacidos vivos sobre mujeres de 15 a 49 años, por mil","Intensidad reproductiva en edad fértil","La fecundidad de cada grupo de edad"],["Mortalidad general","Defunciones sobre población total, por mil","Impacto de la muerte en la población","La causa ni la edad de las muertes"],["Dependencia","Grupos de 0 a 14 y de 65 a más sobre 15 a 64 años","Carga demográfica potencial","La carga real de cuidado ni el empleo"],["Crecimiento natural","Nacimientos menos defunciones","Cambio poblacional sin migración","El crecimiento total del territorio"]]}},{"title":"Lectura de pirámides y criterios de interpretación","depth":"full","body":["La pirámide se lee de abajo hacia arriba: la base corresponde a las edades jóvenes y la cima a las mayores; el eje horizontal compara mujeres y varones. La forma general orienta la interpretación, pero no reemplaza el análisis de natalidad, mortalidad y migración. Una base estrecha puede deberse a menos nacimientos o a la salida de familias jóvenes, y esa diferencia cambia por completo la respuesta sanitaria."],"table":{"headers":["Forma","Rasgo visible","Interpretación","Error al leerla"],"rows":[["Expansiva","Base ancha y cima estrecha","Alta natalidad y población joven","Suponer que la natalidad seguirá igual"],["Estacionaria","Anchura relativamente uniforme","Natalidad y mortalidad equilibradas","Ignorar el envejecimiento que ya avanza"],["Regresiva","Base estrecha y peso en edades medias o altas","Baja natalidad y envejecimiento","Atribuir toda la forma a la natalidad"],["Desequilibrada","Entrantes, salientes o asimetrías marcadas","Migración, guerra u otro evento altera la estructura","Leerla solo por la base y no por la muesca"]]}},{"title":"Transición demográfica y transición epidemiológica","depth":"core","body":["La transición demográfica describe los componentes del crecimiento poblacional: natalidad y mortalidad que descienden en secuencia. La transición epidemiológica describe el cambio en el perfil de enfermedad: la carga se desplaza de las infecciones y la mortalidad temprana hacia las enfermedades crónicas, los trastornos mentales y las causas externas. Son procesos relacionados, porque una población que envejece acumula riesgo crónico, pero no son sinónimos y pueden avanzar a velocidades distintas.","La distinción tiene consecuencias. Un territorio puede mostrar transición demográfica avanzada y, al mismo tiempo, mantener una carga alta de infecciones por deficiencias de acceso y saneamiento. Esa convivencia se describe como carga doble o superpuesta: el sistema debe sostener a la vez programas de detección y control crónico y respuestas frente a brotes. Planificar solo para una de las dos cargas deja a la otra sin recursos, y el error es frecuente cuando se lee el promedio nacional como si describiera cada distrito."]},{"title":"Procedimiento y criterios de decisión","depth":"full","body":["En el análisis de situación de salud local, la demografía fija el marco de la comparación: define cuántas personas hay en cada grupo y, con ello, qué denominadores corresponden a cada indicador. La lectura útil no es la cifra aislada, sino la diferencia entre la estructura local y la de referencia, porque esa diferencia explica por qué una tasa bruta puede ser alta sin que el riesgo sea mayor."],"bullets":["1. Delimitar el territorio y el periodo con la misma referencia usada por la autoridad sanitaria.","2. Reunir la estructura por edad y sexo y verificar la fuente y el año de cada dato.","3. Calcular los indicadores con los denominadores correspondientes y anotar su base.","4. Graficar la pirámide y compararla con la estructura regional o nacional.","5. Identificar grupos con mayor demanda potencial y brechas de oferta en el territorio.","6. Contrastar la estructura con la morbilidad registrada y con la capacidad de los servicios.","7. Proyectar necesidades con supuestos explícitos y revisar la proyección cada vez que cambie la estructura."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Un distrito rural de la sierra presenta una pirámide con base estrecha, un angostamiento marcado entre los 20 y 35 años y una cima más ancha que la de distritos vecinos. El equipo de salud concluye que hay envejecimiento por baja natalidad y propone ampliar solo la atención del adulto mayor. Al revisar los registros de migración, encuentra que la mayoría de jóvenes sale para estudiar y trabajar y que muchos niños quedan al cuidado de sus abuelos. La razón de dependencia parece alta, pero la carga real recae en adultos mayores que cuidan niños sin apoyo. El equipo reorienta el plan: consejería familiar, soporte a cuidadores, control de niños y adolescentes y coordinación con la municipalidad. Ajusta además la proyección y advierte que la población infantil disminuirá mientras crece la demanda de cuidado."],"bullets":["Lectura del caso: el angostamiento no era baja natalidad sino emigración selectiva, y la forma desequilibrada lo delataba.","Lectura del caso: la razón de dependencia describe grupos de edad y no la carga efectiva de cuidado.","Lectura del caso: se descartó el plan centrado solo en adultos mayores porque los niños también demandaban atención.","Lectura del caso: cruzar demografía con migración y estructura familiar evita una proyección de servicios equivocada."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: transición demográfica no es epidemiológica; la primera cambia natalidad y mortalidad y la segunda el perfil de enfermedad.","Distinción: crecimiento natural no es crecimiento total, porque el segundo incorpora la migración neta.","Distinción: natalidad no es fecundidad, porque la primera usa la población total y la segunda las mujeres en edad fértil.","Error: leer la pirámide solo por su base, porque una muesca en edades medias puede explicar el problema y no la natalidad.","Error: interpretar la razón de dependencia como carga real, porque no mide empleo, cuidado ni necesidad de servicios.","Distinción: tasa bruta no es tasa específica, porque la primera se afecta por la estructura de edad y la segunda no.","Error: proyectar demanda con la población de hace una década, porque la estructura cambia y la proyección queda obsoleta."]},{"title":"Puntos clave","depth":"core","bullets":["La pirámide acumula cohortes, y una caída de nacimientos se desplaza con los años produciendo un angostamiento que envejece.","El descenso de la mortalidad infantil es el motor inicial del crecimiento poblacional.","El bono demográfico es una ventana que exige empleo y educación para convertirse en capacidad.","La transición epidemiológica no elimina las infecciones, sino que superpone la carga crónica.","La migración altera la estructura y puede simular envejecimiento o juventud en la pirámide.","Los indicadores demográficos definen denominadores y, con ellos, la comparación entre territorios."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Forma y migración","text":"Base ancha indica población joven; base estrecha, envejecimiento; asimetrías o entrantes, migración u otro evento que afecta a un grupo. El distractor típico atribuye toda base estrecha a baja natalidad y omite la emigración. La razón de dependencia usa los grupos de 0 a 14 y de 65 a más sobre la población de 15 a 64 años."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Metodología para el análisis de situación de salud local, perfil territorial y poblacional.","Fuente: OMS — A conceptual framework for action on the social determinants of health, determinantes estructurales e intermedios."]}],"sheet-psi-sp-1-5":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La historia natural supone observar el proceso sin intervención y describir su secuencia. Esa supuesta ausencia de intervención es un recurso analítico: permite identificar en qué punto se puede modificar el curso y qué se esperaría si no se actúa. El recorrido empieza en el periodo prepatogénico, donde interactúan factores de riesgo y protectores sin daño establecido, continúa en el periodo patogénico, que puede ser subclínico o clínico, y termina en un desenlace que no siempre es la curación.","La fase subclínica exige precisión: el proceso patológico ya comenzó, aunque no haya manifestaciones reconocibles. No es lo mismo que exposición, porque estar en contacto con un agente no implica que el proceso se haya iniciado, ni que la persona esté infectada, ni que vaya a enfermar. Esa distinción evita dos errores opuestos: tranquilizar por la ausencia de síntomas y diagnosticar por la sola presencia de un contacto o de un resultado reactivo. Una gestante expuesta a rubéola ilustra el punto: requiere evaluación oportuna, porque la ausencia de síntomas no descarta el riesgo ni confirma el diagnóstico."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El proceso tarda porque el daño se acumula. Entre la exposición y la manifestación clínica hay un intervalo que depende del agente, de la dosis, de la susceptibilidad del huésped y de la respuesta inmunitaria o psicológica. En las infecciones ese intervalo se llama periodo de incubación; en los problemas crónicos, periodo de latencia; en salud mental, la fase prodrómica cumple una función equivalente, con cambios sutiles antes de que se complete el cuadro. La duración de ese intervalo define la ventana en la que la detección es posible.","La longitud de la fase subclínica tiene una consecuencia metodológica decisiva. Detectar antes alarga el tiempo con diagnóstico conocido y puede mejorar el pronóstico, pero también puede solo adelantar la etiqueta sin cambiar el desenlace; ese fenómeno se conoce como sesgo de adelanto diagnóstico. Además, los tamizajes tienden a captar los casos de evolución más lenta, que permanecen más tiempo detectables, lo que se denomina sesgo de longitud. Ambos explican por qué un programa de detección debe evaluarse con mortalidad o con discapacidad y no con tiempo de supervivencia desde el diagnóstico.","En salud mental operan mecanismos adicionales. El apoyo social, la continuidad del cuidado y la adherencia modifican la velocidad de la transición entre fases, y la etiqueta diagnóstica también interviene: puede facilitar el acceso o producir estigma y profecía autocumplida de incapacidad. Por eso la lectura de la historia natural no es solo cronológica, sino también social: el mismo proceso tiene cursos distintos según los recursos y el vínculo con los servicios."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["Cada etapa se reconoce por lo que ocurre y por la evidencia disponible, no por el nombre del servicio que atiende. La tabla ordena la etapa, la forma de reconocerla y la consecuencia práctica que se deriva, de modo que la decisión se apoye en el momento del proceso y no en la costumbre institucional."],"table":{"headers":["Etapa","Qué ocurre","Cómo se reconoce","Consecuencia para la decisión"],"rows":[["Prepatogénico","Interactúan factores de riesgo y protectores sin daño establecido","Exposición o vulnerabilidad sin proceso demostrado","Actuar sobre condiciones y proteger antes del daño"],["Subclínico","El proceso ya comenzó sin manifestaciones clínicas","Tamizaje o evaluación dirigida con hallazgos incipientes","Confirmar, evaluar y hacer seguimiento oportuno"],["Clínico","Aparecen signos y síntomas que permiten diagnóstico","Demanda de atención y criterios clínicos completos","Tratamiento, derivación y control del daño"],["Desenlace","Evoluciona hacia recuperación, secuela, cronicidad o muerte","Seguimiento y evaluación de funcionalidad","Rehabilitación, reinserción y cuidado continuo"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Identificar la exposición y los factores de riesgo y protectores presentes.","2. Verificar si existe un proceso iniciado mediante evaluación dirigida y pruebas pertinentes.","3. Distinguir exposición de infección y de enfermedad antes de nombrar la etapa.","4. Ubicar el momento del proceso y no el servicio disponible en la tabla de etapas.","5. Elegir la intervención correspondiente al momento y a la gravedad observada.","6. Registrar el hallazgo con lenguaje probabilístico y sin rótulos definitivos.","7. Programar seguimiento y definir el criterio de derivación si el cuadro progresa.","8. Revisar si la intervención evita daño innecesario antes de ampliar pruebas o tratamientos."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de la costa, un adolescente de 15 años acude por bajo rendimiento escolar después del fallecimiento de su padre. No refiere tristeza persistente ni ideas de muerte, duerme algo menos y ha dejado de asistir a sus entrenamientos. El tamizaje de depresión resulta positivo. El psicólogo revisa el tiempo transcurrido, descarta criterios completos y ubica el caso en una fase subclínica con factores de riesgo activos. El duelo reciente se registra como factor de riesgo y no como diagnóstico. Programa seguimiento quincenal, entrevista con la madre y coordinación con el colegio, y evita iniciar tratamiento farmacológico. Acuerda con la institución educativa revisar asistencia y rendimiento. Un mes después el adolescente retoma sus actividades y el tamizaje deja de ser positivo."],"bullets":["Lectura del caso: el tamizaje positivo abrió la evaluación y no la cerró, porque no equivale a diagnóstico.","Lectura del caso: había un proceso en curso sin criterios completos, lo que corresponde a la fase subclínica y no al periodo prepatogénico.","Lectura del caso: se descartó tratar de inmediato porque la intervención debe corresponder al momento y a la gravedad.","Lectura del caso: el seguimiento y la coordinación evitan el rótulo prematuro y permiten detectar si el cuadro progresa."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: exposición no es infección ni enfermedad, porque la primera solo indica contacto o vulnerabilidad.","Distinción: periodo prepatogénico no es fase subclínica, porque en la segunda el proceso patológico ya comenzó.","Distinción: historia natural no es curso clínico, porque la primera supone ausencia de intervención.","Error: adelantar un diagnóstico por un tamizaje positivo, porque el tamizaje estima probabilidad y requiere confirmación.","Distinción: detección oportuna no es prevención primaria, porque la primera actúa cuando el daño ya se inició.","Error: atribuir la mejoría a la detección temprana sin comparar, porque el adelanto diagnóstico alarga el tiempo observado sin cambiar el desenlace.","Distinción: factor de riesgo no es factor pronóstico; el primero antecede al inicio y el segundo predice la evolución."]},{"title":"Puntos clave","depth":"core","bullets":["Ubicar el momento evita elegir mal la intervención: antes del daño, en la fase subclínica o con daño establecido.","La exposición sin síntomas no confirma ni descarta infección, y por eso exige evaluación dirigida.","La duración de la fase subclínica define la ventana de detección y el beneficio posible del tamizaje.","El desenlace no es un punto, porque puede incluir secuelas y cronicidad que demandan seguimiento.","Nombrar la etapa no autoriza a rotular a la persona, ya que la etiqueta también modifica el curso.","La lectura de la historia natural ordena la conversación con la persona y con su familia."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Primero el momento","text":"Primero se ubica el momento y después se nombra el nivel preventivo. Si hay proceso iniciado sin síntomas, la respuesta es detección oportuna y confirmación, no tratamiento inmediato ni espera pasiva. El distractor habitual convierte una exposición en diagnóstico o adelanta fármacos sin criterios. Vacunar es primaria, tamizar es secundaria y rehabilitar es terciaria."}},{"title":"Rol del psicólogo en cada momento","depth":"core","bullets":["En el periodo prepatogénico participa en promoción y en acciones sobre determinantes con la escuela y la comunidad.","En la fase subclínica aplica instrumentos válidos, confirma con evaluación y evita rotular antes de completar el estudio.","En la fase clínica participa del diagnóstico, del plan de tratamiento y de la derivación cuando corresponde.","En el desenlace acompaña la adherencia, la rehabilitación y la reinserción escolar o laboral.","En todos los momentos registra lo observado, comunica sin alarmar y coordina con la familia y el equipo."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 1: historia natural de la enfermedad.","Fuente: OMS/EMRO — Noncommunicable diseases: a major challenge to public health in the Region, prevención primordial y primaria.","Fuente: CDC Perú — Vigilancia de enfermedades prevenibles por vacunas, sarampión-rubéola: definiciones de caso."]}],"sheet-psi-sp-1-6":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El nivel se nombra por el momento y la intención, porque una misma actividad puede pertenecer a niveles distintos según la población a la que se dirige.","La historia natural ordena la decisión: primero se ubica el momento del proceso y después se elige la intervención correspondiente.","La prevención primordial modifica condiciones de vida y patrones de consumo que distribuyen el riesgo en toda la población.","La prevención primaria supone exposición o riesgo presente y busca que la enfermedad no llegue a manifestarse.","La prevención secundaria depende de una prueba que detecte temprano y de una ruta de confirmación y tratamiento ya disponible.","La prevención terciaria incluye rehabilitación física, psicológica, laboral y social, además del control de la enfermedad de base.","La prevención cuaternaria exige criterios explícitos para no indicar pruebas, tratamientos o ingresos que no aportan beneficio."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La historia natural describe un proceso continuo: antes de la enfermedad interactúan agente, huésped y ambiente; luego el proceso patológico avanza sin síntomas y finalmente aparece el cuadro clínico. Cada nivel preventivo interviene en un tramo distinto de esa secuencia y su efecto se mide por lo que evita, no por lo que hace. Por eso la vacunación se ubica en la primaria y el tamizaje en la secundaria, aunque ambos sean actos preventivos.","La prevención primordial responde a un hallazgo epidemiológico: las poblaciones con alimentación, tabaco o inequidad más desfavorables enferman más. Ese exceso no se corrige atendiendo solo a las personas ya expuestas. Actuar sobre las condiciones que generan el riesgo desplaza la distribución completa de la exposición. De ahí que las políticas de entornos saludables, transporte, alimentación o vivienda se consideren preventivas aunque no nombren una enfermedad.","La prevención cuaternaria corrige un efecto paradójico del progreso diagnóstico: cuanto más se busca, más hallazgos incidentales aparecen y más se trata a personas que no obtendrían beneficio. Su mecanismo es la decisión informada y compartida, no la abstención indiscriminada de atención. Su límite es claro: nunca justifica dejar de atender una necesidad real."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Nivel","Momento","Criterio para decidir","Riesgo de error"],"rows":[["Primordial","Antes de que existan los factores de riesgo","La acción modifica condiciones que generan el riesgo en la población","Llamar primordial a una consejería individual"],["Primaria","Exposición presente, enfermedad ausente","La persona ya está expuesta y se busca evitar la enfermedad","Confundir protección específica con diagnóstico precoz"],["Secundaria","Fase subclínica detectable","Existe prueba válida y tratamiento que cambia el pronóstico","Tamizar sin ruta de confirmación ni tratamiento"],["Terciaria","Enfermedad manifestada con daño establecido","Se busca reducir secuela, recuperar función o evitar recaída","Llamar terciaria a la prevención de una enfermedad nueva"],["Cuaternaria","Riesgo de daño por la propia intervención","El beneficio esperado supera el riesgo de sobrediagnóstico o sobretratamiento","Convertirla en excusa para no atender"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Describir la situación en términos de persona, tiempo y lugar, sin proponer todavía la intervención.","2. Ubicar el momento en la historia natural: prepatogénico, subclínico o clínico con daño establecido.","3. Verificar si el factor de riesgo ya existe; si no existe, la acción corresponde a prevención primordial.","4. Definir el objetivo operativo: evitar aparición, detectar temprano, limitar secuela o reducir sobreuso.","5. Comprobar que la intervención elegida tiene evidencia, ruta de confirmación y capacidad resolutiva disponible.","6. Registrar el nivel asignado y el criterio usado, para que el equipo audite la coherencia de su cartera.","7. Revisar la decisión cuando cambia el estado clínico, porque un mismo usuario puede requerir varios niveles a la vez."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de una zona urbano-marginal de Arequipa, el equipo de salud mental observa que varios adolescentes de dos colegios intentaron suicidarse en el mismo mes. El psicólogo propone dos acciones. La primera es aplicar un cuestionario de tamizaje a todo el nivel secundario. La segunda es coordinar con la municipalidad y los colegios la restricción del acceso a plaguicidas domésticos y la capacitación docente en señales de alarma. La dirección cuestiona por qué se tamiza si no hay casos confirmados y pide priorizar solo charlas informativas.","El equipo distingue niveles: la restricción del método es prevención primaria porque actúa sobre un factor de riesgo específico; la capacitación docente en señales de alarma es prevención secundaria porque busca detección temprana; el tamizaje también es secundario. La prevención primordial actuaría antes, sobre condiciones estructurales que generan el riesgo. Ninguna de estas acciones sustituye la evaluación individual ni la ruta de referencia."],"bullets":["Lectura del caso: la restricción del método es prevención primaria; la capacitación docente en señales de alarma es prevención secundaria.","Lectura del caso: el tamizaje en estudiantes aparentemente sanos es prevención secundaria y exige entrevista y referencia antes de informar resultados.","Alternativa descartada: limitar la respuesta a charlas confunde promoción con prevención y no modifica la exposición ni detecta casos.","Error que se evita: llamar prevención primaria al tamizaje, lo que promete detección sin confirmación ni tratamiento disponible."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: llamar prevención primaria al tamizaje, porque la primaria evita la aparición y el tamizaje busca casos ya iniciados en fase subclínica.","Error: usar la prevención cuaternaria como argumento para negar atención, porque su criterio es evitar lo que no beneficia y no reducir cobertura.","Distinción: promoción de la salud no es un nivel, porque puede sostener acciones de varios niveles a la vez.","Distinción: prevención primordial no es primaria, porque la primera cambia las condiciones que producen el riesgo y la segunda actúa sobre personas ya expuestas.","Error: deducir fase subclínica por contacto con un caso, porque la exposición no demuestra infección; una gestante expuesta a rubéola requiere evaluación oportuna.","Distinción: rehabilitación no es paliación, porque la rehabilitación busca recuperar función y la paliación alivia sin ese objetivo.","Error: asignar un solo nivel a toda la cartera del servicio, porque la misma persona puede necesitar varios niveles en momentos distintos."]},{"title":"Puntos clave","depth":"core","bullets":["El nivel se identifica por el momento y la intención, porque la actividad aislada admite lecturas distintas según la población.","La prevención primordial opera sobre determinantes, y por eso su resultado se observa en la población y no en un paciente.","La prevención secundaria se justifica con prueba válida y tratamiento que cambie el pronóstico, de lo contrario solo etiqueta.","La prevención terciaria sostiene la continuidad del cuidado y reduce la discapacidad asociada a la enfermedad establecida.","La prevención cuaternaria protege del sobrediagnóstico y exige criterios explícitos de indicación clínica.","La fase subclínica se establece con pruebas, no con la sospecha, porque el contacto sin síntomas no equivale a infección."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"El momento manda","text":"Vacunar es prevención primaria; tamizar es secundaria; rehabilitar es terciaria; evitar pruebas o tratamientos sin beneficio es cuaternaria. La primordial actúa antes de que aparezcan los factores de riesgo. El distractor habitual ofrece una actividad atractiva y pide el nivel sin describir el momento: primero ubica el momento y después nombra el nivel."}},{"title":"APS y niveles de prevención","depth":"full","body":["En APS la prevención no es una campaña añadida: es una forma de organizar el cuidado. La prevención primordial actúa sobre las condiciones sociales que generan riesgo; la primaria evita la aparición; la secundaria detecta y trata temprano; la terciaria reduce complicaciones y discapacidad; la cuaternaria evita intervenciones innecesarias.","El primer nivel es el escenario donde coinciden el tamizaje, la consejería, la vacunación, el control del daño y la continuidad. La decisión no depende solo del nombre de la actividad, sino del momento del proceso salud-enfermedad y de la intención de la intervención.","El MCI organiza el cuidado por curso de vida y en escenarios —hogar, institución educativa, centro laboral, municipio y comunidad—; la prevención se integra a ese cuidado y no se reduce a campañas. La prevención primordial actúa sobre las condiciones estructurales; la primaria sobre factores de riesgo específicos; la secundaria sobre detección temprana; la terciaria sobre complicaciones y la cuaternaria sobre intervenciones innecesarias."],"bullets":["Tamizaje no es diagnóstico: un resultado positivo abre evaluación y no confirma por sí solo.","La prevención cuaternaria evita tratar hallazgos que no producirán daño o que no cambiarán el curso.","La prevención primordial requiere acción intersectorial sobre vivienda, agua, empleo y entornos.","La continuidad en APS evita que la prevención secundaria se pierda después del resultado anormal."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS/EMRO — Noncommunicable diseases: a major challenge to public health in the Region, distinción entre prevención primordial y primaria.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 1: historia natural y niveles de prevención.","Fuente: CDC Perú — Vigilancia de enfermedades prevenibles por vacunas, sarampión-rubéola: definiciones de caso.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: OMS — Informe mundial 2008: APS renovada y prevención a lo largo del curso de vida."]}],"sheet-psi-sp-1-7":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["Falso positivo: la prueba resulta positiva sin condición presente, y su peso relativo crece cuando la prevalencia del grupo es baja.","Punto de corte: valor que separa positivo de negativo; al moverlo se gana sensibilidad a costa de especificidad.","La tabla de dos por dos organiza la decisión: las columnas describen la realidad y las filas, el resultado de la prueba.","El denominador cambia la pregunta: enfermos para sensibilidad, sanos para especificidad, positivos para valor predictivo positivo.","La probabilidad previa resume lo que se sabe antes de la prueba y se actualiza con el resultado obtenido.","Un resultado extremo informa más que uno cercano al punto de corte, porque desplaza más la probabilidad posterior."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["Una prueba no informa sobre la realidad, informa sobre la probabilidad de que la realidad sea una u otra. Esa probabilidad se actualiza con la probabilidad previa: si la condición es frecuente en el grupo evaluado, un positivo convence más; si es rara, el mismo positivo deja dudas. El razonamiento bayesiano formaliza ese ajuste y explica por qué el valor predictivo no es una propiedad estable de la prueba.","La sensibilidad y la especificidad describen el comportamiento de la prueba en dos subpoblaciones definidas por el patrón de referencia. Por eso se calculan en columnas y no en filas: la sensibilidad mira a los enfermos y la especificidad a los sanos. El valor predictivo recorre la dirección contraria, desde el resultado hacia la condición, y por eso depende de cuántos enfermos haya en la población evaluada.","El espectro de pacientes modifica el rendimiento observado: una prueba evaluada en casos graves suele verse más sensible que en atención primaria, donde predominan formas leves. La verificación también introduce sesgo, porque si solo se confirma a los positivos, los falsos negativos quedan invisibles y la sensibilidad se sobreestima."]},{"title":"Rendimiento en una tabla de dos por dos","depth":"full","body":["Con 100 personas evaluadas, 40 tienen la condición: 36 verdaderos positivos y 4 falsos negativos; entre las 60 sin la condición hay 48 verdaderos negativos y 12 falsos positivos. La sensibilidad resulta 90 % y la especificidad 80 %. El valor predictivo positivo es 75 % y el negativo 92,3 %, porque los denominadores son los 48 positivos y los 52 negativos.","Otra composición de la misma tabla deja 32 verdaderos positivos y 8 falsos negativos, con 12 falsos positivos y 48 verdaderos negativos. Con esos valores, la sensibilidad es 80 % y la especificidad 80 %. El valor predictivo positivo llega a 72,7 % y el negativo a 85,7 %. El rendimiento por columna no cambió de forma sustantiva; cambió la proporción de personas con la condición en la muestra.","El efecto de la prevalencia se aprecia al aplicar una prueba de 90 % de sensibilidad y 90 % de especificidad en 1 000 personas. Con prevalencia de 1 % hay 9 verdaderos positivos y 99 falsos positivos, y el valor predictivo positivo es 8,3 %. Con prevalencia de 50 % hay 450 verdaderos positivos y 50 falsos positivos, y el valor predictivo positivo es 90 %. La prueba no cambió: cambió la población examinada."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Medida","Pregunta que responde","Denominador","Uso en la decisión"],"rows":[["Sensibilidad","De quienes tienen la condición, cuántos resultan positivos","Personas con la condición","Descartar: una prueba sensible negativa hace improbable la condición"],["Especificidad","De quienes no tienen la condición, cuántos resultan negativos","Personas sin la condición","Confirmar: un positivo en prueba específica respalda el diagnóstico"],["Valor predictivo positivo","Si el resultado es positivo, qué probabilidad hay de tener la condición","Todos los resultados positivos","Explicar el resultado y decidir la conducta inmediata"],["Valor predictivo negativo","Si el resultado es negativo, qué probabilidad hay de no tener la condición","Todos los resultados negativos","Sostener el alta o el diferimiento con seguimiento"],["Prevalencia","Qué proporción de la población evaluada tiene la condición","Población evaluada","Anticipar cuánto informará un positivo antes de aplicar la prueba"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir la pregunta clínica y la población, porque el rendimiento cambia con el espectro de personas evaluadas.","2. Establecer el patrón de referencia y el momento de verificación, para comparar positivos y negativos con el mismo criterio.","3. Fijar el punto de corte antes de aplicar la prueba y registrar la versión del instrumento utilizado.","4. Calcular sensibilidad y especificidad en la muestra local cuando sea posible, porque los valores publicados pueden no transferirse.","5. Estimar la prevalencia del grupo evaluado y con ella el valor predictivo esperado, antes de comunicar resultados.","6. Prever la ruta de confirmación, la entrevista diagnóstica y el tratamiento para cada positivo detectado.","7. Documentar personas únicas, fecha, punto de corte y destino de cada positivo, para auditar el tamizaje realizado."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un colegio de Lima, el equipo de salud mental aplica una prueba de tamizaje de depresión a 200 adolescentes y obtiene 40 positivos. Tras la entrevista clínica confirma 12 casos y deriva 8, mientras 28 positivos no cumplen criterios. La dirección del colegio pide informar que uno de cada cinco estudiantes está deprimido y suspender el tamizaje por considerarlo un fracaso.","El psicólogo explica que los 40 positivos son resultados de prueba y no diagnósticos. La confirmación alcanzó a 12 personas y los 28 restantes son falsos positivos esperables en un grupo de baja prevalencia. Propone mantener el tamizaje con entrevista prevista, registrar el punto de corte y reforzar la ruta de referencia."],"bullets":["Lectura del caso: el valor predictivo positivo observado es la proporción de positivos confirmados, y los falsos positivos no indican falla de la prueba.","Lectura del caso: la proporción de positivos de un tamizaje no estima la prevalencia, porque depende del punto de corte y de la población convocada.","Alternativa descartada: suspender el tamizaje por los falsos positivos elimina la detección temprana en lugar de corregir la ruta de confirmación.","Error que se evita: comunicar un resultado de tamizaje como diagnóstico, lo que produce etiquetas y tratamientos innecesarios."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: calcular el valor predictivo positivo entre todos los evaluados, porque el denominador son los resultados positivos y no la población completa.","Error: comparar sensibilidades de dos pruebas evaluadas con patrones distintos, porque el rendimiento solo es comparable con el mismo referente.","Distinción: sensibilidad no es valor predictivo, porque la primera parte de la condición y el segundo parte del resultado.","Distinción: tamizaje no es diagnóstico, porque el tamizaje selecciona y el diagnóstico confirma con evaluación y pruebas.","Error: subir el punto de corte para reducir falsos positivos sin revisar la pérdida de sensibilidad, porque ambas medidas se mueven en direcciones opuestas.","Error: trasladar el valor predictivo de un hospital a la comunidad, porque una prevalencia distinta cambia el significado del mismo resultado.","Distinción: incidencia no es prevalencia, porque la incidencia mide casos nuevos y la prevalencia, casos existentes en un momento."]},{"title":"Puntos clave","depth":"core","bullets":["La sensibilidad se calcula entre quienes tienen la condición y su valor alto reduce los falsos negativos.","La especificidad se calcula entre quienes no la tienen y su valor alto reduce los falsos positivos.","El valor predictivo positivo responde a la persona con resultado positivo y depende de la prevalencia del grupo evaluado.","El punto de corte es una decisión clínica, porque desplaza el equilibrio entre detectar de más y dejar pasar casos.","El tamizaje requiere ruta de confirmación y tratamiento disponibles, de lo contrario solo produce etiquetas.","Un resultado negativo en prueba muy sensible ayuda a descartar, pero no sustituye el juicio clínico ni el seguimiento."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Sensible descarta, específica confirma","text":"Prueba sensible negativa ayuda a descartar; prueba específica positiva ayuda a confirmar. Antes de calcular, identifica qué grupo va en el denominador: enfermos para sensibilidad, sanos para especificidad, positivos para valor predictivo positivo y negativos para valor predictivo negativo. El distractor típico ofrece el valor de sensibilidad como si fuera probabilidad de enfermedad."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CDC — Screening for HIV, apéndice, p. 12: fórmulas de rendimiento diagnóstico.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 2: medidas estadísticas."]}],"sheet-psi-sp-1-8":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El criterio común a todos los términos es la comparación con lo esperado, no el número absoluto de casos observados.","La agrupación localizada sugiere una fuente compartida y orienta la búsqueda hacia un espacio, una práctica o un alimento.","El exceso sobre lo esperado exige una línea de base confiable, construida con series históricas del mismo lugar y periodo.","La endemia no implica ausencia de casos, porque describe una presencia habitual que puede mantener carga sanitaria.","El término epizootia desplaza la alerta hacia la población animal y activa la coordinación con salud animal.","El alcance internacional distingue la pandemia de una epidemia nacional o regional.","Las medidas de control se adoptan con la información disponible, porque esperar el cierre del estudio amplía la exposición."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El criterio que separa estos términos es la comparación con lo esperado, no el número absoluto de casos. Ese esperado se construye con series históricas, población de referencia y notificación previa del mismo evento en el mismo lugar y periodo. Cuando la referencia cambia, cambia la clasificación: los mismos pocos casos pueden ser un brote en un distrito sin transmisión y una cifra habitual donde el evento es endémico.","R0 y Rt describen la transmisión con lógicas distintas. R0 resume el potencial de un patógeno en una población totalmente susceptible y sin intervenciones, por lo que es una referencia teórica y no una medida de lo que ocurre. Rt incorpora la inmunidad acumulada, el comportamiento de la población y las medidas vigentes, y por eso cambia semana a semana conforme avanza el evento.","La cadena de transmisión explica la forma de la curva. Un vehículo común produce un pico estrecho; la transmisión de persona a persona genera ondas separadas por el intervalo entre casos; una fuente continua mantiene casos durante más tiempo. La investigación busca el eslabón que puede cortarse primero, porque el control no espera a la confirmación etiológica."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Término","Referencia de comparación","Extensión o grupo","Consecuencia operativa"],"rows":[["Brote","Agrupación vinculada en un lugar y periodo","Localizada","Investigación de campo y control inmediato"],["Epidemia","Casos por encima del esperado","Población y periodo definidos","Respuesta organizada y vigilancia intensificada"],["Endemia","Presencia habitual o esperada","Área con transmisión sostenida","Control permanente y vigilancia de tendencia"],["Epizootia","Aumento inusual en animales","Población animal","Alerta zoonótica y coordinación intersectorial"],["Pandemia","Epidemia de amplia extensión","Varios países o continentes","Coordinación internacional y medidas sostenidas"]]}},{"title":"Procedimiento: investigación de un brote, primeros pasos","depth":"full","bullets":["1. Verificar la señal: confirmar que el aumento supera lo esperado y descartar cambios de registro, codificación o pruebas.","2. Confirmar el diagnóstico del evento y la definición de caso, con criterios de persona, lugar, tiempo y clínica.","3. Buscar y ordenar casos con listado nominal protegido, fecha de inicio de síntomas, exposiciones y desenlaces.","4. Describir el evento con curva por fecha de inicio, distribución territorial y grupos afectados.","5. Formular hipótesis sobre exposiciones plausibles y elegir el estudio analítico si es necesario y viable."]},{"title":"Procedimiento: control, comunicación y cierre","depth":"full","bullets":["6. Aplicar las medidas de control pertinentes de inmediato, sin esperar el cierre de la investigación.","7. Comunicar a la red de vigilancia y a la población con lenguaje claro, sin atribuir causas que aún no se verificaron.","8. Evaluar la respuesta: qué se contuvo, qué falló y qué capacidad local debe reforzarse.","9. Documentar la investigación y retroalimentar a los servicios que notificaron los casos.","10. Revisar la definición de caso y la vigilancia posterior, porque un brote cerrado deja aprendizaje y línea de base."]},{"title":"Leer la curva epidémica sin confundir fechas","depth":"core","bullets":["Un pico estrecho sugiere exposición común; ondas sucesivas separadas por el intervalo de incubación sugieren transmisión propagada.","La fecha de inicio de síntomas describe la secuencia de enfermedad, mientras la fecha de notificación refleja demoras administrativas.","La búsqueda activa de casos puede elevar la curva sin que exista un aumento real de la transmisión.","El periodo de incubación explica el desfase entre la exposición, la aparición de síntomas y el registro del caso.","Una curva no identifica la causa: se contrasta con exposiciones, resultados de laboratorio y distribución territorial."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un albergue de Piura, después de las lluvias, el puesto de salud atiende en una semana a varias personas con diarrea acuosa, muy por encima de lo habitual para esa época. El responsable de vigilancia verifica que el aumento supera lo esperado y revisa el registro de consumo de agua. Define caso como diarrea acuosa en residentes del albergue con inicio en la última semana. Mientras el laboratorio procesa muestras, el equipo clora el reservorio, instala lavamanos y restringe el uso del pozo. Un segundo pabellón notifica casos dos días después.","El equipo mantiene la investigación abierta, revisa historias del servicio y clasifica el evento según su extensión. La intervención no esperó el resultado microbiológico y la notificación se hizo al detectar el conglomerado."],"bullets":["Lectura del caso: el aumento por encima de lo esperado en un lugar y periodo definidos permite clasificar el evento como brote.","Lectura del caso: la curva por fecha de inicio y la revisión de exposiciones sostienen la hipótesis de una fuente común de agua.","Alternativa descartada: esperar la confirmación de laboratorio para intervenir prolonga la exposición y aumenta el número de casos.","Error que se evita: clasificar el evento como endemia por repetirse en dos pabellones, cuando la comparación sigue siendo con lo esperado."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: definir epidemia por un número absoluto de casos, porque el criterio es la comparación con lo esperado en población y periodo.","Error: llamar pandemia a cualquier epidemia extendida en un país, porque la pandemia exige amplia extensión internacional.","Distinción: brote no es epidemia, porque el brote es una agrupación localizada y la epidemia se define por exceso sobre lo esperado.","Distinción: endemia no es ausencia de casos, porque describe presencia habitual y puede implicar carga sostenida.","Error: atribuir a las medidas el cambio de R0, porque R0 describe el potencial sin intervenciones y no cambia con ellas.","Distinción: epizootia no es epidemia humana, porque el aumento inusual ocurre en animales y su relevancia es zoonótica.","Error: leer el pico de la curva como causa identificada, porque la curva describe tiempo y magnitud, no el mecanismo de transmisión."]},{"title":"Puntos clave","depth":"core","bullets":["El término se elige por la comparación con lo esperado, por la extensión y por el grupo afectado, no por la cifra absoluta.","Un brote exige investigación local y control inmediato, porque la fuente suele estar en un espacio o práctica identificable.","La endemia obliga a vigilar tendencias y mantener control permanente, porque la transmisión no desaparece.","Rt mayor que uno indica expansión, igual a uno transmisión estable y menor que uno descenso sostenido.","La curva epidémica orienta hipótesis, pero no reemplaza el análisis de exposiciones ni la confirmación por laboratorio.","La notificación y las medidas de control no esperan el cierre del estudio, porque el tiempo de exposición acumula casos."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Lo esperado define el brote","text":"La palabra decisiva suele ser por encima de lo esperado, no un número absoluto. Diferencia el criterio de comparación, la extensión del evento y el grupo afectado, que puede ser humano o animal. En R0 y Rt, recuerda que las medidas de control modifican Rt y no R0."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OPS — Glosario sobre brotes y epidemias: un recurso para periodistas y comunicadores, entrada Agente.","Fuente: Guzzetta y colaboradores — Impact of a Nationwide Lockdown on SARS-CoV-2 Transmissibility, definiciones y distinción de R0 y Rt.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 1: causalidad e historia natural."]}],"sheet-psi-sp-1-9":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El caso probable reúne evidencia adicional, como nexo epidemiológico o prueba de apoyo no definitiva, y no es una etapa obligatoria en todos los eventos.","La definición de caso fija qué se cuenta y permite comparar semanas, territorios y servicios con el mismo criterio operativo.","El ciclo de vigilancia incluye recolectar, analizar, difundir, intervenir y evaluar, y solo se cierra cuando la información se usó.","La oportunidad es la cualidad central del sistema, porque un dato tardío describe el pasado y no interrumpe la transmisión.","La sensibilidad del sistema depende de que el personal reconozca el evento y lo reporte, no solo de la capacidad de laboratorio.","La representatividad indica qué poblaciones quedan fuera del registro y, por lo tanto, qué decisiones se toman a ciegas.","La retroalimentación sostiene la notificación, porque quien reporta necesita ver que su dato produjo una acción."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La vigilancia no es un registro administrativo: es un sistema de observación que produce señales para decidir. Su valor depende de la oportunidad, porque un dato confirmado la semana siguiente sirve para el informe y no para interrumpir la transmisión. Por eso el circuito se diseña desde el servicio que atiende hasta el nivel que analiza y devuelve información al equipo local.","La notificación funciona como un filtro de sensibilidad: si el personal no reconoce el evento o no lo reporta, el sistema subestima la carga y responde tarde. Las definiciones de caso reducen la variabilidad entre notificadores y permiten comparaciones válidas. Un cambio en la definición modifica el conteo sin que cambie la enfermedad, y esa es una fuente clásica de falsa alarma.","La vigilancia activa y la centinela responden a límites distintos de la pasiva. La activa compensa el subregistro buscando casos donde el registro rutinario no llega; la centinela acepta no contar todo el territorio para obtener datos detallados y comparables. Ninguna reemplaza a la otra: se eligen según la pregunta y según el evento vigilado."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Estrategia","Cómo se captan los casos","Ventaja principal","Límite que obliga a vigilar"],"rows":[["Pasiva","El personal reconoce el caso en la atención habitual y lo notifica por el canal regular","Amplia cobertura con menor uso adicional de recursos","Subregistro y demora si el personal no reconoce o no reporta"],["Activa","Epidemiología busca casos en historias, laboratorios, servicios o comunidad","Mayor sensibilidad y oportunidad en situaciones prioritarias","Demanda tiempo y personal que compite con la atención"],["Centinela","Unidades seleccionadas aplican definiciones y registros estandarizados","Datos detallados y comparables sobre tendencias","No cuenta todos los casos y no estima la carga total del territorio"]]}},{"title":"Procedimiento de notificación y respuesta","depth":"full","bullets":["1. Reconocer el evento con la definición de caso vigente y la lista de notificación obligatoria del nivel correspondiente.","2. Notificar al responsable de vigilancia epidemiológica del establecimiento o a su delegado, sin esperar confirmación.","3. Registrar persona, tiempo, lugar y exposiciones en el formato establecido, con identificador único para evitar duplicados.","4. Asegurar la toma y el envío de muestra cuando la definición lo requiera, con rotulado y conservación correctos.","5. Aplicar las medidas de control inmediatas que correspondan al evento y a su vía de transmisión.","6. Verificar la clasificación final y actualizar el registro cuando llegue el resultado o la investigación cierre.","7. Participar en la retroalimentación y en la evaluación del sistema, porque la vigilancia se corrige con el uso de sus datos."]},{"title":"Criterios de clasificación del caso","depth":"full","table":{"headers":["Categoría","Criterio general","Función operativa","Precisión indispensable"],"rows":[["Sospechoso","Cumple criterios clínicos o epidemiológicos iniciales compatibles","Activa notificación, investigación y toma de muestra","No equivale a diagnóstico definitivo"],["Probable","El sospechoso reúne evidencia adicional de apoyo","Aumenta la certeza operacional y orienta la respuesta","La evidencia exigida cambia según el evento"],["Confirmado","Cumple el criterio confirmatorio de la definición oficial","Permite la clasificación final y el análisis epidemiológico","Puede ser por laboratorio, nexo o criterio clínico autorizado"],["Descartado","No cumple criterios o se demuestra otra explicación","Cierra o reclasifica el registro y evita inflar el conteo","Un negativo aislado no siempre descarta"]]}},{"title":"Definiciones operativas que activan la respuesta","depth":"core","bullets":["Dengue probable: fiebre de hasta siete días, antecedente de residencia o visita a zona con transmisión en las dos semanas previas y al menos dos manifestaciones compatibles.","En niños, la definición admite fiebre sin foco aparente de hasta siete días con el mismo antecedente epidemiológico.","Los signos de alarma, como dolor abdominal intenso y continuo, vómitos persistentes o sangrado de mucosas, exigen evaluación urgente.","El dengue grave implica choque o dificultad respiratoria por extravasación de plasma, hemorragia grave o compromiso grave de órganos.","En sarampión y rubéola, la fiebre con erupción maculopapular generalizada activa sospecha, notificación e investigación inmediata.","La confirmación combina criterios clínicos, epidemiológicos y de laboratorio, y la exposición sola no confirma infección.","La norma técnica de vigilancia incluye como sospechoso también a quien el personal asistencial considera que tiene sarampión o rubéola."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un hospital de Lima, una enfermera de emergencia atiende a un niño de cuatro años con fiebre y erupción maculopapular generalizada. El niño no tiene vacunas registradas y llega después de un viaje familiar. El personal lo reporta el mismo día al responsable de vigilancia, toma la muestra y lo ubica en una sala con precauciones por aerosoles. Al día siguiente, otro niño del área de espera presenta fiebre y exantema.","El equipo revisa los registros de emergencia, busca casos compatibles en la misma fecha y verifica los carnés de vacunación de los contactos. La clasificación inicial fue sospechoso, no descartado, y la investigación siguió sin esperar el resultado de laboratorio."],"bullets":["Lectura del caso: fiebre y erupción maculopapular generalizada activan la sospecha, la notificación y la investigación del caso.","Lectura del caso: revisar registros y contactos es vigilancia activa, porque el equipo busca lo que la notificación pasiva no reportó.","Alternativa descartada: esperar el resultado de laboratorio para notificar retrasa la investigación y las medidas sobre contactos.","Error que se evita: tratar el viaje o la exposición como confirmación, cuando el antecedente solo eleva la sospecha."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: esperar la confirmación de laboratorio para notificar un evento priorizado, porque la notificación inmediata existe para investigar y responder.","Distinción: notificar no es confirmar, porque la notificación informa una sospecha y la confirmación clasifica el caso.","Distinción: vigilancia pasiva no es inactiva, porque el servicio notifica según su propia observación clínica.","Error: equiparar la proporción de positivos de un tamizaje con la prevalencia poblacional, porque depende de quién fue convocado.","Distinción: vigilancia centinela no es censo, porque observa con protocolo común en unidades seleccionadas.","Error: cerrar un caso como descartado con un único resultado negativo, porque el momento de la muestra y el evento condicionan la utilidad de la prueba.","Error: reducir la vigilancia al conteo semanal, porque sin análisis, difusión ni intervención no se completa el ciclo."]},{"title":"Puntos clave","depth":"core","bullets":["Pasiva, activa y centinela responden a cómo y dónde se captan los casos, y su elección depende del evento y del recurso disponible.","La definición de caso manda: sin criterio común no hay comparación válida entre semanas, servicios ni territorios.","La notificación inmediata se hace con la sospecha, porque la respuesta temprana reduce la transmisión y protege a los contactos.","Un resultado negativo aislado no siempre descarta, porque depende del evento, de la muestra y del momento de toma.","La oportunidad, la sensibilidad, la representatividad, la simplicidad y la aceptabilidad permiten evaluar el sistema.","La retroalimentación al servicio que notifica sostiene la calidad del dato y la continuidad del sistema."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Pasiva, activa y centinela","text":"Pasiva y activa explican cómo se buscan los casos; centinela señala dónde y con qué red seleccionada se observa. La definición específica del evento siempre prevalece. Notificar no es confirmar: la notificación inmediata se hace para investigar y responder, y el distractor habitual propone esperar el laboratorio."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Notificación de enfermedades y eventos sujetos a vigilancia epidemiológica, definiciones operativas.","Fuente: CDC Perú — Vigilancia de enfermedades prevenibles por vacunas, sarampión-rubéola, NTS 247.","Fuente: MINSA — Prevención, diagnóstico y manejo del sarampión en el Perú, numeral 5.1.","Fuente: MINSA — Atención integral de pacientes con dengue en el Perú, numeral 5.2."]}],"sheet-psi-sp-1-10":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["La precaución adicional se elige por la vía de transmisión identificada o sospechada, no por el nombre de la enfermedad.","El equipo de protección personal se selecciona según la tarea y el riesgo de exposición, y no como un conjunto fijo.","La higiene de manos se practica al colocar y al retirar los guantes cuando corresponde a uno de los cinco momentos.","Los guantes se cambian entre pacientes y entre tareas contaminadas, y no se lavan ni se reutilizan.","El manejo seguro de punzocortantes, ropa, residuos, equipos y ambiente completa el control de infecciones.","La vigilancia de IAAS compara la frecuencia observada con la línea basal para detectar incrementos o conglomerados."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La cadena de transmisión exige un reservorio, una vía de salida, un modo de transmisión, una puerta de entrada y un huésped susceptible. Las precauciones no eliminan el microorganismo: interrumpen el eslabón que depende de la conducta del personal. En el entorno del cuidado, ese eslabón es sobre todo la vía de contacto y la vía respiratoria.","La higiene de manos actúa sobre la transmisión por contacto, que es la más frecuente y la menos visible. Su eficacia depende del momento, la técnica y la duración, no solo del producto elegido. Los guantes protegen al personal de la exposición, pero se contaminan como la piel, por lo que se cambian entre pacientes y tareas y nunca sustituyen la higiene.","La distinción entre colonización e infección ordena la conducta: portar un microorganismo sin signos clínicos no es estar enfermo, pero sí puede transmitirlo. Por eso las precauciones estándar no dependen del diagnóstico y se mantienen ante toda persona, incluida aquella cuyo estado infeccioso se desconoce o aún no se investigó."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Precaución","Vía o situación","Medidas nucleares","Cuándo se aplica"],"rows":[["Estándar","Toda atención, cualquier diagnóstico","Higiene de manos y equipo según riesgo","Siempre, en toda persona atendida"],["Contacto","Superficies, manos y contacto directo","Guantes, bata, equipo y ambiente seguro","Infecciones por contacto y microorganismos resistentes"],["Gotas","Partículas respiratorias de corto alcance","Mascarilla médica y distancia indicada","Influenza estacional y eventos con transmisión por gotas"],["Aerosoles","Partículas que permanecen suspendidas","Respirador con ajuste y ventilación adecuada","Procedimientos que generan aerosoles y eventos específicos"]]}},{"title":"Procedimiento de higiene de manos y uso de equipo de protección","depth":"full","bullets":["1. Identificar el momento de higiene: antes de tocar, antes de una tarea aséptica, después del riesgo de fluidos, después del contacto y después del entorno.","2. Retirar anillos y pulseras, mantener uñas cortas y descubrir los antebrazos antes de la técnica.","3. Aplicar la solución o el jabón según la técnica establecida y respetar el tiempo de fricción indicado.","4. Colocar el equipo en orden, verificando la integridad de guantes, mascarilla o respirador antes del contacto.","5. Ajustar el respirador con prueba de sellado cuando el procedimiento genere aerosoles.","6. Retirar el equipo sin tocar la superficie contaminada y realizar higiene de manos al terminar.","7. Registrar la exposición si ocurre un accidente con material punzocortante y activar el protocolo institucional."]},{"title":"Influenza y procedimientos que generan aerosoles","depth":"core","bullets":["En influenza estacional se aplican precauciones estándar y por gotas, con mascarilla médica en la atención indicada.","Los procedimientos que generan aerosoles exigen respirador N95 o equivalente con ajuste adecuado, además de protección ocular, bata y guantes.","El equipo se elige según la actividad y el riesgo, porque no toda entrevista exige el mismo conjunto de barreras.","La ventilación del ambiente reduce la concentración de partículas suspendidas y complementa el equipo de protección.","La vigilancia de IAAS mide la frecuencia basal, detecta incrementos o conglomerados e investiga las causas."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En el consultorio de psicología de un hospital de Trujillo, una persona con tos y fiebre acude a una entrevista individual. El personal había previsto aplicar solo precauciones estándar porque no hay diagnóstico confirmado. Durante la espera, otra persona en tratamiento oncológico comparte la sala sin mascarilla y sin distancia.","El psicólogo coloca mascarilla médica a la persona sintomática, mantiene la distancia indicada, ventila el ambiente y realiza higiene de manos antes y después del contacto. Al confirmarse influenza estacional, revisa los contactos de la sala y notifica el caso. La barrera inicial no esperó el diagnóstico, y el equipo revisó por qué la sala de espera permitió la exposición."],"bullets":["Lectura del caso: la sospecha clínica basta para aplicar precauciones por gotas, porque esperar la confirmación expone a otras personas.","Lectura del caso: la higiene de manos se realiza antes y después del contacto, y el uso de guantes no la reemplaza.","Alternativa descartada: mantener solo precauciones estándar con una persona sintomática en sala compartida prolonga la exposición.","Error que se evita: reservar las precauciones para quien tiene diagnóstico confirmado, cuando el estado infeccioso puede ser desconocido."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: usar guantes como sustituto de la higiene de manos, porque el guante se contamina y la higiene sigue siendo obligatoria al retirarlo.","Distinción: colonización no es infección, porque la colonización carece de manifestaciones clínicas y aun así puede transmitirse.","Distinción: aislamiento no es precaución, porque el aislamiento es una medida organizativa y la precaución describe barreras según la vía.","Error: indicar precauciones por aerosoles en toda entrevista, porque el respirador se reserva para procedimientos que generan aerosoles.","Error: lavar o reutilizar guantes, porque son de un solo uso y su reutilización contamina al paciente y al personal.","Distinción: limpieza no es desinfección, porque la limpieza retira materia orgánica y la desinfección reduce microorganismos viables.","Error: vigilar IAAS solo con el conteo global, porque sin denominador ni línea basal no se detectan conglomerados."]},{"title":"Puntos clave","depth":"core","bullets":["Las precauciones estándar no dependen del diagnóstico conocido, porque el estado infeccioso puede ignorarse al momento de la atención.","La vía de transmisión define la precaución adicional y, con ella, el tipo de mascarilla, respirador y ambiente requerido.","La higiene de manos tiene cinco momentos y su omisión es el fallo más frecuente en la transmisión por contacto.","El equipo de protección se elige por tarea y riesgo, porque el exceso de barreras reduce la adherencia y no agrega protección.","La ventilación y el distanciamiento complementan el equipo en la transmisión respiratoria, sobre todo en espacios cerrados.","La vigilancia de IAAS permite detectar aumentos, investigar causas y evaluar el efecto de las medidas aplicadas."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Precauciones para todos","text":"Las precauciones estándar no dependen del diagnóstico conocido: se aplican a toda persona. La vía de transmisión define la precaución adicional; los guantes no reemplazan la higiene de manos. El distractor habitual propone respirador para toda entrevista o guantes para todo contacto."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS — Cinco momentos para la higiene de manos.","Fuente: OMS — Preguntas frecuentes, Día Mundial de la Higiene de Manos 2025, apartado sobre guantes e higiene de manos.","Fuente: CDC — Infection Prevention and Control Strategies for Seasonal Influenza in Healthcare Settings."]}],"sheet-psi-sp-1-11":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El uso racional se verifica en cuatro puntos: indicación, esquema, costo y seguimiento; basta fallar en uno para que la decisión deje de ser racional.","La indicación responde a una necesidad diagnóstica concreta; sin diagnóstico que la sostenga, el medicamento se convierte en riesgo sin beneficio esperado.","El esquema comprende dosis, intervalo, vía y duración; su ajuste depende de la edad, el peso, la función renal y hepática, el embarazo y los otros tratamientos.","El costo se evalúa para la persona y para el sistema, porque un gasto que impide completar el tratamiento termina en un costo sanitario mayor.","La esencialidad se decide por prioridad sanitaria y no por el precio ni por la marca; un producto barato sin eficacia demostrada no es esencial.","El PNUME ordena la selección nacional y sus listas complementarias amplían esa base según la necesidad sanitaria del país.","La farmacovigilancia convierte la sospecha de reacción adversa en información útil para ajustar el uso y prevenir daño en otras personas."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El uso irracional no suele originarse en una sola decisión equivocada. Se sostiene en información incompleta: quien prescribe no ve lo que otros prescribieron, quien dispensa no siempre conoce el motivo y la persona usuaria completa el esquema con lo que recuerda o con lo que compra por su cuenta. Cuando ningún actor tiene la lista completa, los duplicados y las interacciones pasan inadvertidos.","Cada eslabón tiene un mecanismo propio de falla. Una indicación sin diagnóstico agrega riesgo sin beneficio; un esquema mal ajustado produce falta de efecto o toxicidad; una duración excesiva prolonga la exposición; y una suspensión brusca puede devolver el síntoma que el tratamiento controlaba. La suma de fallas pequeñas explica más daño que un error grave aislado.","La adherencia es una conducta y no un rasgo de personalidad. Depende de que la persona entienda para qué sirve el tratamiento, pueda pagarlo, recuerde el esquema y confíe en quien lo indica. Por eso las intervenciones que simplifican el esquema, lo vinculan a rutinas diarias y abordan el costo funcionan mejor que las que solo advierten sobre las consecuencias.","La resistencia antimicrobiana opera como una externalidad: el uso inadecuado en una persona reduce la eficacia futura para toda la comunidad. El mecanismo es la presión selectiva, que favorece a los microorganismos capaces de sobrevivir y facilita su propagación. De ahí que la contención sea un problema de salud pública y no solo una decisión clínica individual."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Etapa","Decisión central","Criterio de uso racional","Consecuencia si falla"],"rows":[["Selección","Qué medicamento entra en la lista institucional","Relevancia sanitaria, eficacia, seguridad y costo comparado","Falta de disponibilidad o gasto en productos de bajo valor"],["Prescripción","Qué se indica, a quién y por cuánto tiempo","Necesidad diagnóstica, contraindicaciones e interacciones","Uso sin indicación y daño evitable"],["Dispensación","Cómo se entrega y se explica el tratamiento","Receta legible, instrucciones claras y verificación de duplicados","Error de entrega y abandono por incomprensión"],["Uso y adherencia","Cómo cumple la persona el esquema acordado","Comprensión, costo, complejidad y seguimiento","Tratamiento incompleto y recaída"],["Vigilancia","Qué se hace ante una sospecha de reacción adversa","Registro, evaluación y comunicación del riesgo","Daño repetido en otras personas"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Establecer la necesidad clínica y formular la impresión diagnóstica antes de elegir un medicamento.","2. Considerar primero las alternativas no farmacológicas disponibles, como consejería, cambios de rutina o intervención psicosocial.","3. Verificar si el medicamento figura en el petitorio institucional y si existe una alternativa equivalente disponible.","4. Revisar contraindicaciones, interacciones y la lista completa de lo que la persona ya toma, incluido lo comprado por su cuenta.","5. Acordar el esquema con la persona y explicar el propósito, el tiempo esperado de efecto y qué hacer ante un síntoma nuevo.","6. Asegurar una dispensación comprensible y comprobar que la receta y las instrucciones coinciden.","7. Programar el seguimiento del efecto y de la adherencia, y registrar cualquier sospecha de reacción adversa para su evaluación.","8. Derivar al médico ante falta de respuesta, sospecha de interacción o necesidad de ajuste, sin modificar el tratamiento por cuenta propia."]},{"title":"Adherencia, polimedicación y revisión del tratamiento","depth":"full","body":["La polimedicación se define por la pertinencia y no por el número de productos. Un tratamiento con varios fármacos puede ser correcto si cada uno responde a una indicación vigente; en cambio, dos productos con la misma acción o una indicación ya expirada constituyen un problema aunque sean pocos. El riesgo crece cuando los prescriptores no comparten historia clínica y la persona agrega lo que compra sin receta.","La revisión del tratamiento es un acto de equipo. Consiste en contrastar cada indicación con la situación actual, verificar duplicados, revisar interacciones y confirmar que la persona comprende y puede cumplir el esquema. El psicólogo aporta la lectura de creencias, temores y barreras, y el médico decide los ajustes.","Sostener la adherencia exige acuerdos concretos: simplificar horarios, asociar la toma a actividades cotidianas, escribir las indicaciones, involucrar a quien acompaña y prever qué hacer si aparece un efecto no deseado. La entrevista motivacional ayuda a explorar la ambivalencia sin imponer, y el seguimiento permite corregir antes del abandono."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de Lima Norte, una persona de 68 años acude al servicio de psicología por insomnio y mareos. Trae una bolsa con varios medicamentos: algunos indicados por especialistas distintos, otros que compra en la botica de la esquina y uno que le recomendó una vecina. Refiere que olvida algunas dosis y que suspendió por su cuenta un producto porque le producía somnolencia. El psicólogo identifica posible polimedicación, registra la lista completa y coordina con el servicio de medicina para la revisión.","Mientras espera la cita médica, acuerda con la persona un horario único para los medicamentos ya indicados, le pide no iniciar ningún producto nuevo sin consultar y explora qué la llevó a automedicarse. La revisión médica encuentra duplicidad de una misma acción terapéutica y ajusta el esquema. El insomnio mejora cuando se ordena el tratamiento y se aborda la preocupación que sostenía la automedicación."],"bullets":["Lectura del caso: la lista completa, incluida la compra por cuenta propia, es el dato que ningún prescriptor tenía y el que permite detectar duplicidad.","Lectura del caso: correspondía identificar el riesgo y derivar, porque el ajuste del esquema es competencia médica y no del psicólogo.","Lectura del caso: el acuerdo de horario único y la indicación de no iniciar productos nuevos son apoyo a la adherencia y no prescripción.","Alternativa descartada: atribuir el insomnio a los nervios y agregar otro producto habría sumado riesgo sin revisar la causa.","Error que se evita: interpretar el olvido de dosis como desinterés, cuando expresa un esquema demasiado complejo para la vida diaria."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: creer que uso racional equivale a no prescribir, porque el criterio es la indicación correcta y no la ausencia de tratamiento.","Distinción: esencial no es sinónimo de barato ni de genérico, porque la esencialidad se decide por prioridad sanitaria, eficacia y seguridad.","Error: atribuir la resistencia al organismo de la persona, porque son los microorganismos los que la desarrollan y se propagan.","Distinción: dispensación no es prescripción, porque la primera ejecuta y explica una indicación que ya fue decidida.","Error: confundir adherencia con obediencia, porque la adherencia es una conducta acordada y sostenida con la persona.","Distinción: farmacovigilancia no es control de calidad del producto, porque su objeto es la reacción adversa en el uso real.","Error: sumar un fármaco para tratar un síntoma que probablemente proviene de otro tratamiento, porque se acumula riesgo sin revisar la causa."]},{"title":"Puntos clave","depth":"core","bullets":["El uso racional se demuestra en la indicación, el esquema, el costo y el seguimiento, no en la cantidad de medicamentos recetados.","La revisión de la lista completa evita duplicados e interacciones que ningún prescriptor ve por separado.","La adherencia mejora cuando el esquema se adapta a la vida diaria y la persona entiende para qué sirve cada indicación.","La resistencia antimicrobiana es un efecto colectivo: el uso individual inadecuado reduce opciones para toda la comunidad.","La farmacovigilancia cierra el ciclo, porque devuelve al sistema lo que ocurre después de la prescripción.","El psicólogo identifica riesgos, sostiene la adherencia y deriva; no ajusta ni suspende tratamientos médicos."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Racional no es menos","text":"Uso racional combina indicación, esquema, tiempo y seguimiento; no significa reducir la cantidad de medicamentos. El distractor habitual confunde al regulador con el abastecedor o presenta la esencialidad como una categoría comercial. La regulación y vigilancia corresponden a DIGEMID, el abastecimiento de recursos estratégicos a CENARES y la salud ambiental e inocuidad a DIGESA."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS — Essential medicines, definición y criterios de selección.","Fuente: RM N.° 633-2023/MINSA — PNUME, Petitorio Nacional Único de Medicamentos Esenciales.","Fuente: OMS — ficha Resistencia a los antimicrobianos.","Fuente: DIGEMID — información institucional y ROF MINSA DS 008-2017-SA.","Fuente: CENARES — información institucional oficial sobre abastecimiento de recursos estratégicos."]}],"sheet-psi-sp-1-12":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El ASIS parte de una pregunta territorial y no de un formulario: qué problema, en quién, dónde, desde cuándo y con qué recursos.","Describe y explica a la vez; sin explicación de determinantes, el análisis se queda en un inventario de daños.","La sala situacional es una rutina de análisis con responsables y periodicidad, no un salón con mapas en la pared.","La priorización convierte el listado de problemas en una agenda acotada y defendible ante la comunidad.","El plan necesita objetivos, responsables, indicadores y momento de revisión; sin esos elementos la prioridad se diluye.","La participación comunitaria aporta la lectura de lo cotidiano y legitima las prioridades ante la población.","El análisis se actualiza porque el territorio cambia: un brote, una migración o una obra modifican el riesgo."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El ASIS existe porque el daño en salud no se distribuye al azar. Los grupos con menos ingresos, educación o acceso a servicios concentran enfermedad y muerte evitable, y esa desigualdad no se corrige atendiendo solo a quienes llegan al establecimiento. El análisis hace visible la distribución y la explica, de modo que la decisión pública no dependa de la impresión de quien atiende.","La priorización responde a una restricción real de recursos. Sin criterios explícitos, la agenda se arma con la demanda más ruidosa o con el caso más visible, y la decisión queda indefendible. Los cinco criterios ordenan la discusión y obligan a explicar por qué un problema entra y otro espera; el valor está en el argumento y no en un puntaje exacto.","La sala situacional sostiene el ciclo porque una decisión tomada una vez se desactualiza. Su mecanismo es la comparación periódica contra una línea de base, con alertas cuando un indicador se aparta de lo esperado. También reduce la asimetría de información entre el equipo de salud, el gobierno local y la comunidad, siempre que los datos se compartan agregados y sin identificar personas.","El uso de la información tiene un límite: un dato sin denominador, sin periodo o sin fuente comparable produce conclusiones frágiles. Por eso el ASIS triangula registros, estudios y relatos, y declara sus vacíos en lugar de rellenarlos con supuestos."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Momento","Pregunta que responde","Producto","Riesgo si se omite"],"rows":[["Caracterizar","Cómo es el territorio y quiénes lo habitan","Perfil territorial y de recursos","Intervenciones diseñadas para una población imaginaria"],["Medir","Qué daños, brechas y tendencias existen","Problemas cuantificados y comparados","La percepción reemplaza al dato y el problema se minimiza"],["Explicar","Por qué ocurre y qué lo sostiene","Determinantes y relaciones identificadas","Se actúa sobre el síntoma y el problema retorna"],["Priorizar","Qué se atiende primero y con qué argumento","Agenda sanitaria acotada","Agenda inflada sin decisión real"],["Actuar y monitorear","Qué se hace, quién responde y cómo se mide","Plan con indicadores y sala situacional","Plan sin seguimiento ni aprendizaje"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir el alcance y el periodo del análisis, con la población y el territorio que se van a describir.","2. Reunir datos de las fuentes disponibles y verificar su calidad, su fecha y su denominador.","3. Caracterizar el territorio, la población, los recursos y los determinantes que condicionan la salud local.","4. Medir daños y brechas comparando grupos y momentos, en lugar de promediar la población entera.","5. Explicar los problemas con información cuantitativa, evidencia cualitativa y la voz de la comunidad.","6. Priorizar con criterios explícitos y registrar el argumento de inclusión y de exclusión de cada problema.","7. Convertir la prioridad en objetivos, actividades, responsables, recursos e indicadores con fecha de revisión.","8. Sostener la sala situacional con una rutina de actualización, alertas y rendición de cuentas ante la comunidad."]},{"title":"Priorización: criterios y matriz de decisión","depth":"full","table":{"headers":["Criterio","Pregunta que ordena","Señal de alerta"],"rows":[["Magnitud","A cuántas personas afecta o qué proporción compromete","Se usa el número absoluto sin denominador"],["Gravedad","Qué daño produce y qué consecuencias deja","Se confunde frecuencia con severidad"],["Vulnerabilidad","Qué grupos concentran el riesgo","Se promedia y desaparecen los más afectados"],["Factibilidad","Qué capacidad real existe para intervenir","Se prioriza lo imposible y se frustra el plan"],["Percepción social","Qué importancia le atribuye la comunidad","Se impone la prioridad técnica sin diálogo"],["Decisión argumentada","Cómo se combinan los criterios y por qué","Se llena la matriz sin explicar el resultado"]]}},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un distrito de la sierra, el equipo de salud cierra el ASIS con los problemas identificados: anemia infantil, consumo de alcohol en adolescentes, dengue y barreras de acceso. El informe tiene mapas y tablas, y la reunión concluye sin acuerdos. La directora del centro de salud pide convertirlo en insumo del presupuesto participativo de la municipalidad. El psicólogo propone una matriz con los cinco criterios, revisar con la comunidad qué problema se siente más urgente y llevar a la reunión municipal solo las prioridades con objetivos, responsables e indicadores.","El equipo advierte que el dengue tiene baja magnitud local pero alta letalidad potencial, y que las barreras de acceso explican por qué la anemia se detecta tarde. La prioridad no se decide por el número de casos aislado, sino por la combinación de gravedad, vulnerabilidad y capacidad de respuesta."],"bullets":["Lectura del caso: sin priorización explícita el ASIS queda como informe descriptivo y no habilita ninguna decisión.","Lectura del caso: la matriz obliga a justificar por qué un problema entra y otro espera, y hace auditable la elección.","Lectura del caso: la voz de la comunidad corrige la lectura técnica, porque el acceso tardío no aparece en el conteo de casos.","Alternativa descartada: llevar los cuatro problemas sin jerarquía diluye la solicitud y favorece a quien plantea la demanda más visible.","Error que se evita: priorizar solo por número de casos y dejar sin respuesta un problema grave pero poco frecuente."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: presentar el ASIS como un informe descriptivo anual, porque sin explicación ni priorización no habilita decisiones.","Distinción: ASIS no es diagnóstico situacional, porque el diagnóstico retrata un momento y el ASIS añade priorización y plan.","Error: priorizar por cantidad de casos, porque un problema poco frecuente y grave puede exigir respuesta inmediata.","Error: usar promedios distritales, porque el promedio oculta las brechas entre grupos y territorios.","Distinción: sala situacional no es un archivo de datos, porque su función es análisis continuo, alerta y ajuste de la decisión.","Error: confundir un indicador con un dato aislado, porque un indicador requiere denominador, periodo y fuente comparables.","Distinción: participación no es validación, porque la comunidad interviene en la definición del problema y no solo en la presentación final."]},{"title":"Puntos clave","depth":"core","bullets":["El ASIS explica antes de priorizar, porque una prioridad sin determinantes se convierte en una lista de deseos.","Los criterios explícitos protegen la decisión, ya que permiten sostener ante la comunidad por qué se eligió un problema.","El promedio distrital esconde desigualdad, por eso el análisis compara grupos y no solo territorios.","La sala situacional sostiene la decisión en el tiempo, porque el territorio cambia y la prioridad debe revisarse.","Un plan sin responsables ni indicadores no es producto del ASIS, sino una declaración de intenciones.","El presupuesto participativo es una oportunidad de decisión local, y el ASIS es el argumento técnico que la sostiene."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"ASIS analiza, sala decide","text":"ASIS analiza y prioriza; la sala situacional actualiza y acompaña la decisión. El distractor típico ofrece un listado de problemas como producto final o propone priorizar por el criterio más visible, como el número de casos. Si el enunciado menciona seguimiento, alertas o actualización permanente, la respuesta se refiere a la sala situacional."}},{"title":"ASIS, APS y planificación territorial","depth":"core","body":["El ASIS es la base diagnóstica de la gestión territorial en APS. No se limita a describir daños: caracteriza la población y el territorio, identifica determinantes, mide brechas y explica por qué ciertos grupos enferman más o acceden menos.","El producto del ASIS debe alimentar el plan local de salud y la cartera de la RIS. Un informe que no se traduce en prioridades, responsables, recursos e indicadores no cambia la respuesta del sistema.","El ASIS local lo elabora el equipo de gestión de la RIS con el gobierno local y las instituciones de la RIS. Usa HIS, REUNIS, ENDES, ENAHO e INEI, y complementa con la sala situacional, que incluye autoridades, sectores y representantes comunales. La priorización se ordena en magnitud, trascendencia (gravedad), vulnerabilidad (equidad), factibilidad y percepción social; la tendencia se lee dentro de magnitud y trascendencia."],"bullets":["Caracterizar población, territorio, determinantes y respuesta de los servicios.","Triangular datos cuantitativos, cualitativos y la voz de la comunidad.","Priorizar con magnitud, gravedad, tendencia, factibilidad y equidad.","Convertir prioridades en objetivos, indicadores y responsables del plan local."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Metodología para el análisis de situación de salud local, documento técnico de ASIS local.","Fuente: OMS — Primary health care, servicios integrados, acción multisectorial y participación.","Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, ejes temáticos, escenarios y enfoques transversales.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017."]}],"sheet-psi-sp-1-13":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["La vigilancia es un ciclo y no un trámite: detección, notificación, investigación, control, análisis y difusión se encadenan.","La definición de caso separa lo que se cuenta de lo que no se cuenta, y por eso su aplicación debe ser uniforme.","El flujo de información tiene canales y plazos definidos, y la urgencia se comunica antes de completar el formulario.","La investigación no espera a que termine el estudio para iniciar el control, porque el riesgo sigue activo.","El análisis busca cambios en tiempo, lugar y persona; un caso aislado informa poco y un patrón orienta la acción.","La difusión devuelve la información a quienes deciden y a la comunidad, y sostiene la confianza en el sistema.","La vigilancia no sanciona a quien notifica: la notificación temprana protege a la población y no busca culpables."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["Un evento que no se detecta no se puede controlar. La vigilancia reduce el tiempo entre la aparición de un caso y la respuesta, y ese intervalo es su verdadero producto. El circuito funciona porque cada eslabón tiene un responsable identificable: quien atiende sospecha, quien vigila verifica y tramita, y quien dirige decide con la información recibida.","La definición de caso es una regla de decisión epidemiológica. Permite que dos servicios cuenten lo mismo y que la comparación entre semanas, distritos o regiones tenga sentido. Si se aplica de forma laxa, el número sube sin que exista más enfermedad; si se aplica de forma restrictiva, el evento desaparece del registro y la respuesta llega cuando el brote ya se extendió.","La distinción entre notificación inmediata y regular es una decisión de diseño basada en el costo de la demora. Algunos eventos cambian de tamaño en cuestión de días y exigen comunicación urgente; otros se benefician del reporte periódico, que sostiene tendencias y comparaciones. El reporte sin casos también informa, porque distingue ausencia de enfermedad de silencio del servicio.","El análisis descriptivo ordena los casos por tiempo, lugar y persona y permite formular hipótesis. Su límite es conocido: un mapa de conteos puede reflejar tanto riesgo como concentración de habitantes, y una asociación ecológica no prueba causalidad individual. La vigilancia orienta la investigación, no la reemplaza."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Componente","Función","Registro que deja","Falla típica"],"rows":[["Definición de caso","Decide qué evento se cuenta y cuál no","Criterios aplicados al caso","Se amplía o restringe según conveniencia"],["Notificación","Comunica el evento por el canal y el plazo correspondiente","Reporte con fecha y responsable","Se espera la confirmación de laboratorio"],["Investigación","Verifica diagnóstico, contactos y expuestos","Listado de casos y contactos","Se cierra el caso sin buscar expuestos"],["Control","Interrumpe la transmisión o reduce la exposición","Medidas aplicadas y fechas","Se posterga hasta tener el informe final"],["Análisis y difusión","Describe el patrón y devuelve la información","Reporte con recomendaciones","Se archiva el dato sin que circule"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Detectar el evento a partir de la atención, la comunidad o el reporte de otro servicio.","2. Aplicar la definición de caso y clasificar el evento como sospechoso, probable o confirmado según los criterios vigentes.","3. Comunicar de inmediato al responsable de vigilancia del establecimiento o a su delegado, sin esperar pruebas.","4. Registrar el caso con los datos que exige la ficha y verificar la fecha y la identificación de la persona.","5. Tramitar la notificación por el canal establecido, según el tipo de evento y el plazo que le corresponde.","6. Iniciar la investigación: verificar el diagnóstico, listar contactos y expuestos y buscar la fuente.","7. Activar las medidas de control en paralelo, sin esperar el cierre de la investigación.","8. Analizar el conjunto de casos por tiempo, lugar y persona, y difundir lo encontrado con recomendaciones."]},{"title":"Definiciones de caso y unidades notificantes","depth":"full","body":["La definición de caso no es un diagnóstico: es el acuerdo que permite contar de la misma manera en todos los servicios. Su aplicación exige revisar los criterios completos y no solo el síntoma más llamativo, porque un caso mal clasificado distorsiona el denominador y la tendencia. La unidad notificante, a su vez, es la que responde por el reporte de su ámbito, incluso cuando no tiene laboratorio propio."],"table":{"headers":["Elemento","Qué aporta","Consecuencia de un error"],"rows":[["Caso sospechoso","Cumple los criterios clínicos o epidemiológicos iniciales","Se descarta sin evaluación y se pierde la oportunidad de control"],["Caso probable","Suma evidencia epidemiológica o de laboratorio parcial","Se trata como confirmado y se comunica un dato que no lo es"],["Caso confirmado","Cuenta con el resultado que la definición exige","Se atiende como caso aislado y el brote pasa inadvertido"],["Caso descartado","Fue evaluado y no cumple la definición","Se elimina del registro sin dejar trazabilidad"],["Unidad notificante","Reporta los eventos de su ámbito en el plazo correspondiente","El silencio del servicio se interpreta como ausencia de enfermedad"]]}},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En una institución educativa de un distrito rural, después de una actividad escolar, varios estudiantes presentan vómitos y diarrea en menos de dos días. La psicóloga que conducía un taller de habilidades sociales identifica el agrupamiento, conversa con los docentes y confirma que los afectados compartieron un alimento preparado en el local. El director pide esperar los resultados de laboratorio antes de avisar, para no alarmar a las familias. La psicóloga comunica el hecho al responsable de vigilancia del puesto de salud, quien verifica la definición de caso y activa la investigación de la fuente.","En paralelo se retira el alimento sospechoso, se recomienda hidratación y se coordina con la municipalidad la revisión del expendio. El análisis posterior muestra que los casos se concentraron en un solo turno, lo que apoyó la hipótesis de una fuente común."],"bullets":["Lectura del caso: el agrupamiento en tiempo y lugar es una señal que activa la vigilancia, aunque no exista confirmación de laboratorio.","Lectura del caso: la comunicación al responsable de vigilancia no requiere certeza diagnóstica, porque la respuesta depende de la velocidad.","Lectura del caso: retirar el alimento y recomendar hidratación son medidas de control que avanzan en paralelo a la investigación.","Alternativa descartada: esperar el laboratorio deja activa la fuente y amplía el número de personas expuestas.","Error que se evita: tratar el evento como un problema disciplinario del colegio en lugar de un evento sujeto a vigilancia."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: esperar la confirmación de laboratorio para notificar, porque la respuesta pierde el tiempo que la vigilancia debía ganar.","Distinción: vigilancia no es diagnóstico, porque el diagnóstico explica a una persona y la vigilancia describe un patrón poblacional.","Distinción: notificación inmediata no es notificación regular, porque la primera responde a un evento que no admite espera.","Error: confundir la definición de caso con el diagnóstico clínico, porque la definición ordena el registro y no reemplaza la evaluación.","Error: leer un mapa de casos como prueba de causalidad, porque un mapa de conteos puede reflejar la concentración de habitantes.","Distinción: investigar no es sancionar, porque la investigación busca fuente, contactos y control del riesgo.","Error: tratar el reporte sin casos como un trámite vacío, porque su ausencia impide distinguir falta de enfermedad de falta de reporte."]},{"title":"Puntos clave","depth":"core","bullets":["La vigilancia se mide por la respuesta que activa y no por la cantidad de formularios completados.","La definición de caso hace comparables los datos, y su aplicación uniforme sostiene la credibilidad del sistema.","La notificación inmediata existe porque hay eventos en los que cada día cambia el tamaño del brote.","La investigación y el control avanzan juntos, ya que el riesgo no espera el cierre del estudio.","Un mapa orienta hipótesis, y la hipótesis necesita denominadores y comparaciones para sostenerse.","La difusión cierra el ciclo, porque la información que no llega a quien decide no modifica nada."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Notificar es obligación","text":"Notificar oportunamente es una responsabilidad funcional y no una tarea opcional; la urgencia activa la respuesta sin esperar el trámite completo ni el laboratorio. El distractor habitual propone esperar la confirmación, reunir al equipo o trasladar el caso antes de avisar. La definición de caso decide qué se registra, pero no reemplaza el diagnóstico ni la evaluación clínica."}},{"title":"Arquitectura y flujo nacional de notificación","depth":"core","body":["La vigilancia epidemiológica peruana se organiza en una red nacional. El nivel nacional es conducido por el CDC Perú / Dirección General de Epidemiología; el nivel regional por las DIRIS, DIRESA o GERESA; y el nivel local por las unidades notificantes (establecimientos de salud) y las redes. La notificación no es un acto aislado: alimenta la investigación, la respuesta y la difusión.","La Directiva Sanitaria N° 046-MINSA/DGE-V.01 establece que la notificación puede ser inmediata, semanal o mensual según el evento. Los eventos de notificación inmediata se reportan dentro de las 24 horas; la notificación semanal se consolida según el calendario epidemiológico y las DIRIS/DIRESA/GERESA envían la información al CDC los martes antes de las 14:00. Los brotes y epizootias tienen circuito inmediato propio.","La información se registra en los sistemas oficiales (NOTISP y SIEPIBROTE, según el evento), se analiza por persona, tiempo y lugar, y se devuelve a los equipos y a la población mediante boletines, sala situacional y alertas. Sin retroalimentación, la unidad notificante pierde sentido: notificar no es llenar un formato, es activar una respuesta."],"bullets":["Nacional: CDC Perú / Dirección General de Epidemiología; conduce, analiza y difunde.","Regional: DIRIS, DIRESA o GERESA; consolida, verifica y apoya la respuesta.","Local: unidad notificante y red; detecta, registra y notifica.","Inmediata: dentro de 24 horas para los eventos definidos.","Semanal: consolidación según calendario; envío al CDC los martes antes de las 14:00.","Mensual: solo para los eventos que la norma lo indica.","Difusión: boletín, sala situacional, alertas y retroalimentación a la unidad."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Notificación de enfermedades y eventos sujetos a vigilancia epidemiológica, definiciones operativas.","Fuente: CDC Perú — Vigilancia de enfermedades prevenibles por vacunas.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 1: causalidad e historia natural.","Fuente: MINSA — Directiva Sanitaria N.° 046-MINSA/DGE-V.01, notificación de enfermedades y eventos sujetos a vigilancia epidemiológica, RM N.° 506-2012/MINSA, 18/06/2012.","Fuente: CDC Perú — Calendario epidemiológico 2026: notificación semanal consolidada al CDC los martes antes de las 14:00; notificación inmediata dentro de 24 horas.","Fuente: MINSA — Directiva Sanitaria N.° 047-MINSA/DGE-V.01, notificación de brotes, epidemias y otros eventos de importancia para la salud pública, RM N.° 545-2012/MINSA."]}],"sheet-psi-sp-2-1":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["Los determinantes sociales describen la estructura de oportunidades y no una lista de factores de riesgo individuales.","La posición socioeconómica integra educación, ocupación, ingresos, clase social, género y etnia, y no se reduce al ingreso.","Los determinantes estructurales fijan quién tiene qué; los intermedios definen a qué se expone cada persona.","El sistema de salud actúa después de la estratificación y puede amortiguar o profundizar la brecha.","La inequidad exige tres condiciones: la diferencia es injusta, evitable y sistemática.","La equidad reconoce necesidades distintas y ajusta la respuesta, en lugar de repartir lo mismo.","El curso de vida explica por qué una desventaja temprana se convierte en enfermedad décadas después."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El marco de los determinantes sociales propone una arquitectura causal y no un listado. En el nivel estructural se ubican el contexto político, económico y social, las políticas que distribuyen recursos y la posición socioeconómica que resulta de ellos. Ese nivel configura la estratificación: quién nace en una familia con más educación, mejores ingresos y mayor capacidad de exigir derechos.","Los determinantes intermedios traducen esa posición en exposición concreta. La vivienda, el trabajo, el agua, la alimentación y las redes de apoyo definen a qué se expone cada persona y con qué recursos cuenta para protegerse. El mecanismo se entiende en tres pasos: exposición diferencial, vulnerabilidad diferencial y consecuencias diferenciales del mismo daño.","La exposición diferencial explica por qué algunos grupos se enferman más: viven cerca de la fuente de riesgo o trabajan en condiciones que los exponen. La vulnerabilidad diferencial explica por qué, ante la misma exposición, unos enferman con mayor gravedad: cuentan con menos reservas materiales y psicosociales. Las consecuencias diferenciales explican por qué el mismo diagnóstico produce más discapacidad o gasto en quienes tienen menos acceso a la atención.","El sistema de salud pertenece al nivel intermedio porque media entre la posición social y el resultado. Su cobertura, sus horarios, la distancia, el trato y los copagos pueden acercar el servicio o expulsar a quien más lo necesita. No crea la estratificación, pero puede compensarla o reproducirla."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Nivel","Qué incluye","Mecanismo","Lectura local"],"rows":[["Estructural","Contexto político, económico y social; posición socioeconómica","Distribuye poder, prestigio y recursos entre grupos","Familias con empleo informal y menor escolaridad concentran el riesgo"],["Intermedio material","Vivienda, trabajo, agua, saneamiento y alimentación","Define la exposición concreta y su intensidad","Viviendas sin agua segura elevan la exposición a infecciones"],["Intermedio psicosocial","Redes de apoyo, violencia, discriminación y estigma","Actúa sobre el estrés crónico y la búsqueda de ayuda","El estigma retrasa la consulta por salud mental"],["Intermedio conductual y biológico","Conductas, carga genética y estado nutricional","Modula la vulnerabilidad ante la misma exposición","La desnutrición infantil agrava el efecto de una infección"],["Sistema de salud","Cobertura, acceso, oportunidad, trato y continuidad","Media entre la posición social y el resultado","La distancia y el horario explican la atención tardía"]]}},{"title":"Ejes de inequidad y curso de vida","depth":"full","body":["Las inequidades se organizan en ejes que se cruzan: género, etnia, territorio, discapacidad, nivel educativo, ingreso y condición migratoria. Una misma persona puede acumular varios. La lectura correcta no suma etiquetas, sino que observa cómo la combinación produce una exposición distinta; una mujer rural con empleo informal no enfrenta la misma barrera que un varón urbano con seguro formal.","El curso de vida aporta la dimensión temporal. La gestación y los primeros años concentran periodos críticos en los que la desnutrición, la violencia o la falta de estímulo dejan efectos que persisten. La adolescencia define trayectorias de salud mental y de continuidad escolar. La adultez acumula exposición laboral y carga de cuidado, y la vejez transforma la desventaja previa en dependencia y gasto.","En el servicio, la inequidad se reconoce por tres preguntas: quién no llega, quién llega tarde y quién abandona. La respuesta exige datos desagregados por grupo y territorio, porque el promedio puede mejorar mientras la brecha se amplía. Una intervención que solo sube el promedio de atención puede estar dejando intacta la exclusión de quienes tienen más barreras."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Delimitar la población y el problema de salud que se quiere explicar, con su magnitud y su tendencia.","2. Describir la distribución del problema por grupo, territorio, género, etnia y nivel educativo.","3. Identificar los ejes de inequidad que concentran el daño y descartar que la diferencia sea solo biológica o esperable.","4. Rastrear los determinantes estructurales que explican esa distribución y los intermedios que producen la exposición.","5. Reconocer el tramo del curso de vida donde la intervención tiene mayor efecto y menor costo de oportunidad.","6. Definir qué parte del problema puede abordar el sector salud y qué parte exige acuerdo con otros sectores.","7. Acordar con los actores una medida verificable, un responsable y un plazo, y registrarlos en el plan local.","8. Revisar el resultado por grupo y no solo el promedio, para comprobar si la brecha se cerró."]},{"title":"Del determinante a la intervención","depth":"full","table":{"headers":["Determinante estructural","Sector o actores competentes","Ejemplo de acción"],"rows":[["Posición social/clase","Todos los ministerios","Reducir brechas entre quintiles"],["Género","MIDIS, MIMP, MTPE, MINEDU, MEF","Reducir asimetrías de acceso y carga de cuidado"],["Raza/etnia","MIDIS, MINCUL, MIMP, MINEDU","Combatir discriminación y exclusión étnico-racial"],["Educación","MINEDU, MTC, MEF, MIDIS","Acceso y calidad educativa en el quintil inferior"],["Ocupación","MINTRA, MINSA, MEF","Empleo formal, seguridad social y salario digno"]]},"body":["La inequidad se reporta como brecha absoluta y razón entre el grupo más y menos favorecido, no como promedio. Cada determinante tiene un sector competente; sin esa asignación, la intersectorialidad queda declarativa."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un distrito rural de la sierra, el centro de salud registra más síntomas depresivos entre familias con menor escolaridad y empleo informal. El equipo organiza un taller de relajación y reparte folletos, y la asistencia es baja. El psicólogo revisa los datos desagregados y observa que quienes no llegan son, sobre todo, mujeres que trabajan en el mercado y cuidadoras sin relevo. Propone trasladar el taller al horario del mercado, coordinar con la municipalidad y el colegio una respuesta intersectorial y mantener la atención individual para quienes ya presentan síntomas.","El equipo discute si basta con mejorar la difusión. El psicólogo señala que el problema no es la información sino la organización del tiempo y del cuidado, que es un determinante intermedio sostenido por la posición socioeconómica de esas familias."],"bullets":["Lectura del caso: la baja asistencia no indica desinterés, sino una barrera de tiempo y cuidado que el diseño del servicio no consideró.","Lectura del caso: educación y empleo informal son determinantes estructurales y no se modifican con una charla.","Lectura del caso: la atención individual sigue siendo necesaria para quienes ya tienen síntomas y no sustituye la acción intersectorial.","Alternativa descartada: aumentar la difusión supone que el problema es de información y deja intacta la barrera de acceso.","Error que se evita: responsabilizar a las personas de su situación sin analizar la distribución de oportunidades."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: tratar los determinantes sociales como factores de riesgo individuales, porque describen la distribución de oportunidades en una población.","Distinción: determinante estructural no es intermedio, porque el primero configura la posición social y el segundo produce la exposición concreta.","Error: ubicar el sistema de salud entre los estructurales, porque el marco lo sitúa entre los intermedios, aunque dependa del contexto.","Distinción: inequidad no es cualquier diferencia, porque la inequidad es injusta, evitable y sistemática.","Distinción: equidad no es igualdad, porque la equidad ajusta la respuesta a necesidades distintas.","Error: evaluar una intervención solo con el promedio, porque el promedio puede mejorar mientras la brecha se amplía.","Error: reducir la posición socioeconómica al ingreso, porque también la componen educación, ocupación, clase, género y etnia."]},{"title":"Puntos clave","depth":"core","bullets":["Los determinantes sociales explican la distribución del daño, y por eso su análisis es poblacional y no solo clínico.","La posición socioeconómica se construye con varios ejes, y el ingreso aislado no la resume.","El sistema de salud es intermedio y puede reducir o reproducir inequidades según su cobertura, acceso y trato.","La inequidad requiere injusticia, evitabilidad y sistematicidad; sin esos tres rasgos se trata de una diferencia.","El curso de vida muestra que la desventaja temprana se acumula y que la intervención tardía cuesta más.","La respuesta intersectorial es necesaria porque los determinantes estructurales no dependen del sector salud."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Estructural no es intermedio","text":"El contexto político, la educación, la ocupación y los ingresos pertenecen al nivel estructural; la vivienda, el trabajo, los factores psicosociales y el sistema de salud, al intermedio. El distractor habitual coloca el sistema de salud entre los estructurales. La equidad no reparte lo mismo: ajusta la respuesta a la necesidad de cada grupo."}},{"title":"APS y acción sobre los determinantes","depth":"core","body":["La APS no se limita a la consulta: organiza la acción sobre los determinantes estructurales e intermedios. Ingreso, educación, ocupación, género, etnia, vivienda, trabajo y entorno explican por qué dos personas con el mismo diagnóstico tienen trayectorias distintas.","La acción sobre determinantes exige intersectorialidad y participación. El sector salud puede liderar la lectura y la abogacía, pero no puede resolver solo vivienda, transporte, empleo o violencia. La RIS y el gobierno local son espacios concretos para acordar responsabilidades."],"bullets":["Distinguir determinantes estructurales (poder, ingresos, educación, género, etnia) de intermedios (vivienda, trabajo, conductas, sistema de salud).","Evitar explicar la enfermedad solo por decisiones individuales.","Acordar con otros sectores objetivos, recursos y responsables verificables.","Medir inequidades y no solo promedios poblacionales."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS — A conceptual framework for action on the social determinants of health, secciones 5.5-5.6.","Fuente: OMS — Primary health care, servicios integrados, acción multisectorial y participación.","Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, ejes temáticos y enfoques transversales.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017."]}],"sheet-psi-sp-2-4":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La sectorización organiza el territorio en sectores con límites reconocibles y asigna a cada uno una población y un equipo responsable. Su función no es dibujar un mapa, sino distribuir la responsabilidad sanitaria para conocer riesgos, familias y recursos.","La ficha familiar registra la composición del hogar, sus condiciones de vida, sus necesidades y sus redes de apoyo. Aplicada con visita domiciliaria, permite seguimiento nominal: saber quién es cada familia, qué le ocurrió y qué se acordó con ella.","La carpeta familiar reúne y ordena los formatos e información de la familia; la ficha es uno de sus registros centrales. Confundir ambas lleva a creer que se conoce el hogar por tener un formulario archivado."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La sectorización y la ficha familiar funcionan como una tecnología de conocimiento del territorio: convierten la población dispersa en familias identificables y el riesgo abstracto en prioridades concretas. Su efecto depende de que el dato circule y se use, no de la cantidad de formatos."],"bullets":["Asignar población crea responsabilidad: un equipo que sabe a quién cubre puede detectar ausencias y no solo esperar la demanda espontánea.","El seguimiento nominal convierte el dato agregado en una decisión, porque permite identificar qué familia necesita visita, derivación o apoyo concreto.","Los determinantes sociales se leen en la vivienda, el agua, el hacinamiento, el trabajo y las redes; la ficha los recoge para explicar el riesgo y no solo describirlo.","La acumulación de riesgos explica por qué dos familias con el mismo diagnóstico difieren: vivienda, cuidado, ingresos y redes modifican su capacidad de respuesta.","El uso de la información cierra el ciclo de registrar, analizar, priorizar, actuar y volver a registrar; si falta el uso, la ficha se convierte en archivo.","Toda medición tiene límites: el autorreporte puede ocultar violencia, hacinamiento o ingresos, y la visita con confianza mejora la calidad del dato.","La actualización responde al cambio familiar: nacimientos, migración, fallecimientos, enfermedad o pérdida de vivienda alteran el riesgo y la prioridad."]},{"title":"Criterios de sectorización y aplicación","depth":"full","body":["El sector se delimita con los cinco criterios del MCI: tamaño de la población, cobertura prestacional, accesibilidad geográfica, densidad poblacional y circunscripción política administrativa. Se registra en SISFAC y se representa en el mapeo geosanitario; la revisión periódica evita que la asignación quede obsoleta cuando crece la población o cambia el equipo."],"table":{"headers":["Criterio oficial","Pregunta que ordena","Uso operativo"],"rows":[["Tamaño de la población","¿Cuántas personas y familias se asignan?","Equilibrar carga del equipo"],["Cobertura prestacional","¿Qué cartera se ofrece en el sector?","Evitar duplicidad y brechas"],["Accesibilidad geográfica","¿Puede llegarse en tiempo razonable?","Definir rutas y visitas"],["Densidad poblacional","¿Cómo se distribuye la población?","Ajustar frecuencia y prioridad"],["Circunscripción política","¿Coincide con límites distritales o comunales?","Facilitar gobernanza local"]]}},{"title":"Registro, uso y confidencialidad","depth":"full","body":["El registro se organiza por dimensiones que luego se usan para decidir. Una ficha extensa que nadie consulta consume tiempo de la visita y expone datos sin beneficio para la familia."],"table":{"headers":["Dato que se registra","Para qué se usa","Límite o cuidado"],"rows":[["Composición y etapa del ciclo familiar","Ajustar la demanda esperada y detectar cuidadores sobrecargados.","No inferir riesgo por el solo tipo de familia."],["Vivienda, agua y saneamiento","Explicar enfermedades y priorizar visitas.","Evitar registrar datos que no se usarán."],["Salud, discapacidad y cuidado","Identificar dependencia y barreras de acceso.","No sustituir la evaluación clínica."],["Redes y apoyo","Activar recursos comunitarios antes de derivar.","No exponer información familiar en espacios públicos."],["Riesgo y prioridad","Ordenar visitas y seguimiento.","Revisar la clasificación cuando cambie la situación."]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir sectores con límites reconocibles y validarlos con el municipio y con la comunidad.","2. Asignar familias y responsabilidad de equipo por sector, considerando carga y accesibilidad.","3. Aplicar la ficha durante la visita domiciliaria, con consentimiento y lenguaje comprensible.","4. Verificar los datos con la familia y con los registros disponibles antes de clasificar el riesgo.","5. Archivar la ficha en la carpeta familiar y restringir el acceso a la información.","6. Clasificar prioridades y acordar con la familia el plan de seguimiento.","7. Actualizar la ficha cuando cambie la composición, la vivienda o la situación de salud.","8. Usar la información en el análisis del sector y en la programación de visitas y derivaciones."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un pueblo joven de la costa, el equipo programa sus visitas con fichas de dos años atrás. Una ficha indica varios integrantes y ninguna condición crónica. Al visitar por otra razón, la enfermera encuentra que la abuela con diabetes se mudó con la familia, que una adolescente dejó el colegio y que hay un bebé recién nacido. El psicólogo revisa la carpeta, actualiza la ficha con la familia y detecta que la adolescente necesita evaluación y que la abuela requiere control. El equipo reordena sus prioridades, coordina con el colegio y programa una nueva visita. La coordinación municipal recibe solo el dato agregado del sector, no la información nominal. La ficha actualizada queda con fecha y responsable, y el equipo acuerda revisarla en la siguiente visita."],"bullets":["Lectura del caso: la ficha desactualizada produjo una decisión equivocada; el problema no era el formato sino el uso de un dato vencido.","Lectura del caso: la visita domiciliaria permitió corregir la composición y detectar riesgos que el registro anterior no contenía.","Lectura del caso: la información nominal quedó en la carpeta y se compartió de forma agregada, para proteger la confidencialidad.","Lectura del caso: actualizar no es volver a llenar el formulario, sino ajustar la prioridad y el plan de cuidado."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: sectorizar no es dividir el mapa porque implica asignar población, equipo y responsabilidad sobre un territorio.","Distinción: ficha familiar no es carpeta familiar porque la carpeta contiene otros documentos y la ficha es un registro dentro de ella.","Error: llenar la ficha y archivarla → sin uso en la programación, el registro no mejora ninguna decisión.","Distinción: actualizar no es duplicar porque la versión nueva reemplaza el dato anterior con fecha y responsable.","Error: confundir seguimiento nominal con lista de asistencia → el seguimiento verifica situación y continuidad, no solo presencia.","Distinción: georreferenciar no es sectorizar porque ubicar viviendas no asigna responsabilidad ni prioriza familias.","Error: compartir la ficha completa con otras instituciones → expone datos familiares y excede el fin sanitario."]},{"title":"Puntos clave","depth":"core","bullets":["La sectorización asigna población y responsabilidad, no solo un espacio en el mapa; eso permite detectar a quien no llega.","La ficha familiar sirve cuando se usa para priorizar y dar continuidad, no cuando se archiva.","La carpeta familiar contiene la ficha y otros documentos; confundirlas distorsiona el registro.","La visita domiciliaria contrasta el dato y revela cambios que el formulario no capturó.","La confidencialidad protege a la familia y sostiene la confianza necesaria para el seguimiento."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Sectorizar no es dividir el mapa","text":"Sectorizar implica asignar población, equipo y responsabilidad territorial; el mapa solo ayuda a ubicarla. La ficha familiar es un registro central de la carpeta, no toda la carpeta. Si la pregunta pide priorizar familias vulnerables, la respuesta se apoya en seguimiento nominal, visita domiciliaria y actualización, no en la demanda espontánea ni en el número de formatos archivados."}},{"title":"Sectorización, ficha familiar y APS","depth":"core","body":["La sectorización organiza el territorio y asigna población nominal a un equipo. No es solo dividir un mapa: permite conocer familias, riesgos, recursos y prioridades, y sostener el seguimiento en el tiempo.","La ficha familiar registra composición, vivienda, condiciones de vida, riesgos y necesidades. Es un instrumento de cuidado y de planificación, no un formulario para archivar. Su uso exige actualización, confidencialidad y devolución de la información a la familia."],"bullets":["Definir sectores con población y equipo responsables.","Actualizar la ficha en visitas y contactos, no solo al inicio.","Usar la información para priorizar familias y coordinar apoyos.","Proteger datos nominales y compartir solo lo necesario."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Metodología para el análisis de situación de salud local, territorio, población y recursos.","Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, escenarios y participación.","Fuente: MINSA — NTS N.° 138-MINSA/2017/DGIESP, RM 574-2017/MINSA, funciones del Centro de Salud Mental Comunitaria.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial."]}],"sheet-psi-sp-2-5":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["Una intervención comunitaria es una acción planificada que responde a un problema priorizado con la población, define a quiénes se dirige y qué cambio busca, y elige una estrategia viable y aceptable en ese territorio.","El diagnóstico participativo antecede al diseño: identifica cómo se vive el problema, qué recursos existen y qué barreras explican que las soluciones disponibles no se usen.","La teoría de cambio hace explícita la cadena entre recursos, actividades, productos y resultados, junto con los supuestos que deben cumplirse. Sin esa cadena, la ejecución se confunde con el efecto."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["Una intervención comunitaria se sostiene en una explicación del cambio: qué mecanismo se activará, en quiénes y bajo qué condiciones. Cuando esa explicación falta, el equipo confunde actividades visibles con efectos y atribuye al taller lo que dependió del acceso o del apoyo social.","La APOC opera en dos fases: primero inventaría factores de riesgo y protectores del territorio —lluvias, basurales, humos, derrumbes, pandillaje, alcohol, vectores—; luego despliega un paquete de educación, vigilancia, salud ambiental, salud ocupacional y preparación para emergencias. El agente comunitario capta, convoca y sostiene el vínculo; no reemplaza al equipo de salud."],"bullets":["La teoría de cambio obliga a declarar supuestos: si se supone que la información basta para cambiar una conducta, la intervención fallará ante barreras de acceso o normas sociales adversas.","Los determinantes sociales explican por qué una actividad educativa rinde distinto en dos barrios: vivienda, trabajo, seguridad y redes modifican la oportunidad de aplicar lo aprendido.","La participación aumenta la pertinencia porque el problema se define con quienes lo viven; también mejora la asistencia al ajustar horario, lengua y lugar.","La implementación oscila entre fidelidad y adaptación: sin fidelidad la estrategia pierde su núcleo, y sin adaptación choca con la cultura y el territorio.","Los mecanismos de cambio más frecuentes son autoeficacia, apoyo social, acceso oportuno y reducción del estigma; cada uno exige una actividad distinta.","La intervención vertical falla porque decide desde el escritorio, ignora barreras locales y deja de funcionar cuando el equipo externo se retira."]},{"title":"Tipos de intervención y criterios de elección","depth":"full","table":{"headers":["Tipo","Criterio","Ejemplo","Límite"],"rows":[["Promocional","Fortalece capacidades y entornos para el cuidado.","Talleres de crianza con madres y padres.","No garantiza cambio si el entorno no acompaña."],["Preventiva","Actúa antes de que el problema aparezca o se agrave.","Tamizaje y consejería en escolares.","Sin ruta de derivación genera detección sin atención."],["De detección y derivación","Identifica casos y los conecta con servicios.","Búsqueda activa de personas con consumo de riesgo.","La detección sin cierre aumenta la frustración."],["De continuidad","Sostiene el vínculo y la adherencia después del alta.","Acompañamiento telefónico y visitas.","Depende de registro y de responsables definidos."],["De abogacía y entorno","Modifica condiciones que producen el problema.","Gestión de espacios públicos seguros.","Requiere acción intersectorial y plazos largos."]]}},{"title":"Teoría de cambio e indicadores","depth":"full","body":["Cada nivel de la cadena exige un indicador distinto y una línea de base. Medir solo actividades produce informes extensos que no responden si el problema priorizado cambió."],"table":{"headers":["Nivel","Qué describe","Ejemplo de indicador"],"rows":[["Recurso","Capacidad disponible para ejecutar.","Horas del equipo, ambiente y materiales."],["Actividad","Acción realizada.","Número de sesiones efectivamente realizadas."],["Producto","Entrega o alcance operativo.","Personas contactadas y derivadas."],["Resultado","Cambio en acceso, conducta o salud.","Personas que inician y continúan atención."],["Impacto","Cambio poblacional sostenido.","Reducción de la brecha priorizada."]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Convocar a la comunidad y a los actores del territorio para definir el problema y su magnitud.","2. Revisar los datos disponibles y complementarlos con recorrido, entrevistas y grupos.","3. Priorizar el problema con criterios explícitos y acordar la población objetivo.","4. Formular el objetivo con cambio, población y plazo, y revisar su factibilidad.","5. Construir la teoría de cambio con actividades, productos, resultados y supuestos.","6. Diseñar la evaluación con línea de base, indicadores y fuentes verificables.","7. Implementar con adaptación cultural y registro de cobertura y calidad.","8. Evaluar con la comunidad, documentar a quiénes no llegó y decidir continuidad o ajuste."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En una comunidad amazónica, el centro de salud organiza talleres de manejo del estrés en español, a media mañana, en el local escolar. Después de varias convocatorias asisten pocas personas y el equipo concluye que la comunidad no participa. Una lideresa explica que la mayoría trabaja en la chacra en ese horario y que varias personas mayores prefieren su lengua originaria. El psicólogo propone un diagnóstico con líderes, agentes comunitarios y docentes, ajustar el horario, usar intérpretes y complementar con radio local. El equipo redefine la teoría de cambio y acuerda medir asistencia, comprensión y continuidad, no solo número de talleres. Con esos ajustes la convocatoria mejora y el equipo entiende que el problema era de diseño. La intervención deja de ser una actividad aislada y pasa a tener objetivo, población e indicadores."],"bullets":["Lectura del caso: la baja asistencia no probaba desinterés, sino un diseño que ignoraba trabajo, lengua y horario.","Lectura del caso: el diagnóstico participativo corrigió la explicación del problema y evitó culpar a la comunidad.","Lectura del caso: la teoría de cambio permitió distinguir talleres realizados de cambios en comprensión y continuidad.","Lectura del caso: se evita la intervención vertical, que habría repetido la convocatoria y aumentado el gasto sin mejorar el acceso."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: actividad no es intervención porque la intervención tiene problema, población, objetivo, estrategia e indicadores.","Distinción: producto no es resultado porque el producto describe lo entregado y el resultado el cambio logrado en las personas.","Distinción: eficacia no es efectividad porque la eficacia se evalúa en condiciones controladas y la efectividad en condiciones reales.","Error: celebrar la cobertura promedio → oculta a quienes no llegaron por lengua, distancia, discapacidad o costo.","Distinción: promoción no es atención asistencial porque busca capacidades y entornos, no solo resolver casos.","Error: adaptar tanto la estrategia que se pierde su núcleo → la evaluación ya no puede atribuir ningún efecto."]},{"title":"Puntos clave","depth":"core","bullets":["El diagnóstico participativo define el problema antes de elegir la actividad; invertir el orden produce intervenciones pertinentes solo en apariencia.","La teoría de cambio conecta recursos con resultados y revela supuestos que deben verificarse.","Un indicador de resultado exige línea de base y seguimiento; sin ellos no se sabe si hubo cambio.","La cobertura promedio puede ocultar barreras, por lo que hay que revisar a quiénes no llegó.","La adaptación cultural mejora el acceso, pero debe preservar el núcleo de la estrategia."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Actividad no es intervención","text":"Una actividad aislada no es una intervención si no responde a objetivo, población e indicador. Si el enunciado solo menciona charlas, talleres o materiales entregados, todavía no demuestra un cambio en salud. Para evaluar hace falta una línea de base, indicadores de proceso y de resultado, y seguimiento de la cobertura y la calidad. El distractor típico propone ampliar el presupuesto sin medir el efecto."}},{"title":"APOC e intervención comunitaria en APS","depth":"core","body":["La Atención Primaria Orientada a la Comunidad (APOC) combina la clínica preventiva con el diagnóstico y la acción comunitaria. No es una campaña masiva ni una suma de talleres: es una forma de organizar el cuidado con la comunidad y sobre sus prioridades.","Una intervención comunitaria en APS parte de un problema priorizado, define población y objetivo medible, elige una estrategia viable y culturalmente aceptable, y establece indicadores de proceso y resultado. La teoría de cambio ayuda a explicitar por qué se espera que funcione."],"bullets":["Diagnóstico participativo antes de diseñar la intervención.","Objetivo medible y población delimitada.","Estrategia viable, pertinente y sostenible.","Indicadores de proceso, resultado e impacto.","Evaluación con la comunidad y ajuste del plan."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, ejes temáticos y escenarios.","Fuente: MINSA — Metodología para el análisis de situación de salud local, priorización y participación de actores.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 2: medidas estadísticas.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017."]}],"sheet-psi-sp-2-6":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["El trabajo intersectorial coordina al sector salud con educación, municipalidad, protección, justicia, trabajo y organizaciones sociales para responder a problemas que ningún sector resuelve solo.","La multisectorialidad describe la concurrencia de varios sectores; la intersectorialidad exige además un problema común, objetivos compartidos, roles definidos y seguimiento.","La responsabilidad compartida no diluye la conducción sanitaria: salud orienta técnicamente, y cada sector aporta recursos, normas y capacidad de acción en su ámbito."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La coordinación entre sectores no se produce por buena voluntad ni por decreto: depende de intereses, recursos y reglas que hagan previsible el cumplimiento. Entender esos mecanismos permite diseñar acuerdos que sobrevivan a los cambios de autoridad."],"bullets":["Los determinantes sociales se producen en varios sectores; una respuesta solo sanitaria trata la consecuencia y deja intacta la causa.","La interdependencia de recursos explica la coordinación: ningún sector controla toda la información, el presupuesto o la capacidad de acción que el problema exige.","Los costos de coordinación son reales, pues demandan tiempo, reuniones, desacuerdos y trámites; por eso la articulación necesita reglas simples y productos concretos.","La confianza se construye con cumplimiento verificable, ya que cada acuerdo cumplido reduce el costo de la siguiente negociación.","La gobernanza en red requiere una instancia que convoque, reglas de decisión y rendición de cuentas; sin ellas la red se dispersa.","El cierre de la derivación es un mecanismo de continuidad, porque verifica que la persona fue atendida y que la información regresó a quien la envió."]},{"title":"Niveles de articulación y criterios","depth":"full","table":{"headers":["Tipo de acción intersectorial","Qué implica","Riesgo o costo"],"rows":[["Informativa","Un sector presenta datos o recomendaciones a otro","Relación unidireccional; no compromete acciones"],["Cooperación","Interacción para ganar eficiencia en un tema de interés común","Pérdida parcial de autonomía; suele quedarse en ejecución"],["Coordinación","Ajuste de políticas y trabajo horizontal en red","Mayor dependencia y necesidad de financiamiento común"],["Integración","Política o programa único con varios sectores","Exige gestión transversal y acuerdos explícitos"],["Salud en todas las políticas","Decisiones de otros sectores consideran su efecto en salud y equidad","Requiere gobernanza y rendición de cuentas"]]},"body":["Cada nivel cede autonomía y exige acuerdo escrito; la salud en todas las políticas es el nivel más alto, no un sinónimo de reunión. La instancia local es el Comité Multisectorial o Consejo Local de Salud."]},{"title":"Sectores, competencias y aportes","depth":"full","bullets":["Educación aporta detección en la escuela, asistencia y seguimiento pedagógico; no reemplaza la atención clínica.","La municipalidad aporta territorio, presupuesto, espacios y programas locales; la DEMUNA interviene en protección de niñas, niños y adolescentes.","Protección aporta rutas frente a violencia y desprotección; el CEM atiende violencia contra la mujer y los integrantes del grupo familiar.","Justicia aporta medidas de protección y acceso a derechos; su tiempo procesal no siempre coincide con la urgencia sanitaria.","Trabajo y promoción del empleo aportan inserción laboral y orientación; su efecto depende de la demanda local.","Las organizaciones sociales aportan confianza, convocatoria y sostenibilidad; no sustituyen la responsabilidad estatal.","Salud aporta evaluación, consejería, tratamiento y conducción técnica; no puede asumir las competencias de los demás."]},{"title":"Condiciones para que funcione","depth":"full","body":["La articulación se sostiene en condiciones verificables y no en declaraciones de voluntad. Revisarlas antes de firmar un acuerdo evita que la red se active solo durante la emergencia y se apague después."],"table":{"headers":["Condición","Pregunta que ordena","Riesgo si falta"],"rows":[["Problema común","¿Qué problema compartimos y a quiénes afecta?","Cada sector persigue objetivos distintos."],["Roles y responsables","¿Quién hace qué y quién responde por cada parte?","Nadie asume el cierre de las acciones."],["Plazos","¿Cuándo se espera cada producto o resultado?","La respuesta se posterga sin fecha de revisión."],["Seguimiento","¿Cómo y con qué indicadores se revisará el avance?","No se detectan brechas ni retrasos."],["Retroalimentación","¿Qué información vuelve a quien derivó el caso?","Se pierde la continuidad del cuidado."]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir el problema común con datos y con la voz de la población afectada.","2. Identificar qué sectores tienen competencia, recursos o información pertinente.","3. Acordar objetivo, población y resultado esperado con un lenguaje compartido.","4. Asignar roles, responsables, plazos y recursos por cada acción.","5. Diseñar la ruta de derivación y el mecanismo de retroalimentación.","6. Establecer indicadores y una instancia de seguimiento con fechas.","7. Registrar los acuerdos y comunicar avances a las instituciones y a la población.","8. Cerrar cada caso derivado y evaluar el resultado conjunto antes de renovar el acuerdo."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un distrito urbano, una docente reporta que un estudiante de secundaria falta con frecuencia y presenta hematomas. El centro de salud lo evalúa, pero la familia no acude a la cita. El psicólogo convoca a la municipalidad, a la DEMUNA, al colegio y al CEM. Cada institución llega con su propio formato y su propia urgencia; la primera reunión termina sin acuerdos. En la segunda, el grupo define un problema común, asigna una responsable del caso, fija plazos y acuerda que la atención psicológica continúe en el centro de salud. La DEMUNA verifica la medida de protección y el colegio informa la reincorporación. El psicólogo recibe retroalimentación y cierra la derivación. El equipo aprende que la concurrencia sin ruta no protege a nadie."],"bullets":["Lectura del caso: la primera reunión fue multisectorial sin integración; cada sector conservó su objetivo y nadie asumió el cierre.","Lectura del caso: el problema común y la responsable del caso convirtieron la concurrencia en una ruta con seguimiento.","Lectura del caso: la retroalimentación permitió saber si la medida de protección y la atención psicológica se cumplieron.","Lectura del caso: se evita el error de derivar y suponer que otra institución resolvió, que deja el caso en un circuito abierto."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: multisectorial no es intersectorial porque la primera suma sectores y la segunda integra objetivos y responsabilidades.","Distinción: derivar no es cerrar porque la derivación envía y el cierre verifica la atención y retroalimenta.","Error: confundir reunión con acción → sin acuerdos, responsables y plazos nada cambia para la persona.","Distinción: responsabilidad compartida no es diluir la conducción porque salud mantiene la orientación técnica.","Error: firmar convenios sin ruta operativa → el documento no define quién atiende, cuándo ni cómo se reporta.","Distinción: coordinar no es integrar porque la coordinación puede mantener acciones paralelas sin un resultado común."]},{"title":"Puntos clave","depth":"core","bullets":["Un problema común alinea a los sectores; sin él cada institución persigue su propia agenda.","La intersectorialidad exige roles, plazos y seguimiento, no solo voluntad de reunirse.","La derivación con cierre protege la continuidad y evita que todos supongan que otro atendió.","La conducción sanitaria se mantiene aunque la responsabilidad sea compartida.","La confianza entre instituciones se construye con acuerdos pequeños y verificables."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Intersectorialidad es responsabilidad compartida","text":"Intersectorialidad significa responsabilidad compartida con objetivos comunes. Si el enunciado muestra instituciones que solo se reúnen o se pasan casos sin seguimiento, hay coordinación débil, no acción intersectorial. La respuesta completa incluye problema común, roles, plazos, seguimiento y retroalimentación. El distractor típico propone más reuniones o un convenio sin ruta operativa."}},{"title":"Intersectorialidad y APS","depth":"core","body":["La APS actúa sobre problemas que exceden al sector salud. La intersectorialidad exige objetivos compartidos, responsabilidades definidas, recursos y mecanismos de seguimiento; no se agota en reuniones o declaraciones conjuntas.","La diferencia con la multisectorialidad es operativa: varios sectores pueden concurrir sin integrar sus acciones. La salud en todas las políticas propone que las decisiones de otros sectores consideren sus efectos en la salud y la equidad."],"bullets":["Definir un problema común y un resultado esperado.","Asignar responsabilidades y recursos a cada sector.","Acordar indicadores y rendición de cuentas.","Gestionar conflictos de competencia e intereses.","Verificar que el acuerdo se traduzca en acciones."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS — Primary health care, acción multisectorial y participación.","Fuente: MIMP — Lineamientos de coordinación CEM-UPE-DEMUNA, RM 237-2024-MIMP.","Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, enfoques transversales y escenarios.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial."]}],"sheet-psi-sp-2-7":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["El plan local de salud traduce las prioridades del territorio en objetivos, actividades, responsables, recursos, cronograma e indicadores. Es un instrumento de conducción y no una lista de deseos.","Un problema bien formulado describe qué ocurre, a quiénes afecta, dónde se concentra y con qué magnitud; sin esos elementos la priorización se vuelve opinión.","El plan operativo desagrega el plan local en acciones con fechas, responsables y presupuesto; el plan local fija el rumbo y el operativo organiza la ejecución."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El plan local combina técnica y política: los criterios ordenan la priorización, pero la decisión final involucra actores con poder e intereses. Los mecanismos de planificación sirven para hacer explícitos los supuestos y para que el seguimiento corrija antes de que termine el periodo."],"bullets":["La planificación situacional parte de problemas concretos y de actores con intereses distintos; por eso el plan debe explicar a quién beneficia y a quién afecta cada decisión.","El marco lógico conecta problema, objetivo, actividades, indicadores y supuestos; cuando un eslabón falta, la evaluación no puede atribuir resultados.","La priorización combina magnitud, gravedad, tendencia, factibilidad y equidad; sin criterios explícitos gana el problema de quien tiene más poder de convocatoria.","La factibilidad presupuestal y operativa evita planes que no pueden ejecutarse; un objetivo sin recurso ni responsable es una declaración.","El monitoreo corrige durante la ejecución y la evaluación valora al final; confundirlos lleva a decidir tarde o a juzgar sin evidencia.","La participación en la priorización y en la valoración de resultados aumenta la legitimidad del plan y la disposición a sostenerlo."]},{"title":"Criterios de priorización","depth":"full","table":{"headers":["Criterio","Pregunta que ordena","Riesgo si se omite"],"rows":[["Magnitud","¿A cuántas personas afecta y con qué frecuencia?","Se prioriza lo visible o lo que reporta más demanda."],["Trascendencia (gravedad)","¿Qué consecuencias produce si no se atiende?","Se posterga un problema silencioso pero grave."],["Vulnerabilidad (equidad)","¿Afecta con mayor intensidad a grupos en desventaja?","El promedio oculta brechas por territorio o pertenencia."],["Factibilidad","¿Existe capacidad, recurso y competencia para intervenir?","Se promete lo que no puede ejecutarse."],["Percepción social","¿La comunidad reconoce el problema como prioritario?","El plan se ejecuta sin apropiación ni demanda sostenida."],["Decisión argumentada","¿Cómo se combinan los criterios y por qué?","Se llena la matriz sin explicar el resultado."]]},"body":["La lista canónica del ASIS local se ordena en magnitud, trascendencia (gravedad), vulnerabilidad (equidad), factibilidad y percepción social; la tendencia se lee dentro de magnitud y trascendencia. La decisión final debe explicar cómo se combinaron los criterios, porque la matriz no reemplaza el juicio."]},{"title":"Del problema al indicador","depth":"full","body":["La cadena se construye desde el problema y no desde la actividad disponible. Si se empieza por lo que el equipo sabe hacer, el plan justifica la oferta en lugar de responder a la necesidad."],"table":{"headers":["Elemento","Regla de formulación","Error frecuente"],"rows":[["Problema","Describe qué ocurre, a quiénes, dónde y con qué magnitud.","Formular una solución como si fuera el problema."],["Objetivo","Expresa el cambio, la población y el plazo.","Usar verbos vagos o metas sin fecha."],["Actividad","Indica qué se hará y con qué recurso.","Confundir la actividad con el resultado."],["Indicador","Define fórmula, fuente, unidad y frecuencia.","Medir sin línea de base ni denominador comparable."],["Meta","Fija el valor esperado en un periodo.","Fijar una meta sin sustento en la capacidad disponible."]]}},{"title":"Presupuesto, cronograma y responsabilidades","depth":"full","bullets":["Presupuesto: cada actividad necesita costo, fuente de financiamiento y responsable de ejecución; sin ello el plan no es viable.","Cronograma: las fechas deben considerar clima, cosecha, calendario escolar y disponibilidad del equipo.","Responsables: una persona por actividad y no un área genérica, porque la responsabilidad difusa no se ejecuta.","Recursos: humanos, materiales, transporte y tiempo del equipo; el tiempo suele ser el recurso más escaso.","Coordinación: las actividades que dependen de otro sector requieren acuerdo previo y confirmación.","Riesgos: prever qué puede fallar y qué alternativa existe evita suspender la actividad completa.","Seguimiento: definir reuniones, responsables y tablero de indicadores antes de empezar la ejecución."],"body":["El plan lo conduce el gobierno local con el Comité Local de Salud y se encadena al plan de desarrollo local y al POI mediante acuerdos de gestión. El municipio distrital o provincial lidera la convocatoria; la Autoridad Local de Salud presenta el plan y la RIS aporta la lectura sanitaria. Sin decisión política municipal, diagnóstico basal, financiamiento y gestión por resultados, el plan queda como documento."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Conformar el equipo que elabora el plan e identificar a los actores que deben participar.","2. Analizar la situación local con datos, recorrido y voces de la comunidad.","3. Priorizar problemas con criterios explícitos y justificar la selección.","4. Formular objetivos medibles y temporales para cada problema priorizado.","5. Diseñar actividades con responsables, recursos, cronograma y presupuesto.","6. Definir indicadores con fórmula, fuente, frecuencia, línea de base y meta.","7. Validar el plan con los actores y ajustarlo según la factibilidad.","8. Monitorear la ejecución, evaluar resultados y actualizar el plan con la comunidad."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. El comité local de salud de un distrito presenta un plan con talleres de salud mental y ningún indicador. La municipalidad pregunta cuánto cuesta, quién ejecuta y cómo se sabrá si funcionó. El psicólogo propone reformular el problema con datos del sector, priorizar la detección de depresión en adultos mayores y definir un objetivo medible. El comité acuerda actividades, responsables y presupuesto, y añade una línea de base y un indicador de continuidad. También programa revisar avances cada trimestre. Al final del año, el informe muestra actividades cumplidas y personas que iniciaron atención, pero advierte que no puede atribuir mejoría en salud sin seguimiento. El comité aprende a distinguir ejecución de resultado y acuerda documentar los supuestos del plan para no prometer más de lo que puede medir."],"bullets":["Lectura del caso: el plan inicial confundía actividades con resultados y no permitía decidir ni rendir cuentas.","Lectura del caso: la pregunta municipal por costo y responsable obligó a convertir el plan en una herramienta operativa.","Lectura del caso: la línea de base y el indicador de continuidad permitieron interpretar el avance sin exagerar el efecto.","Lectura del caso: se evita declarar éxito por talleres realizados y se explicita qué no puede afirmarse con el diseño usado."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Distinción: plan local no es plan operativo porque el primero fija prioridades y el segundo desagrega acciones y fechas.","Distinción: producto no es resultado porque el producto cuenta lo entregado y el resultado el cambio logrado.","Distinción: monitoreo no es evaluación porque el monitoreo corrige la marcha y la evaluación valora el efecto.","Error: formular el problema como falta de un servicio → convierte la solución en diagnóstico y oculta la necesidad real.","Distinción: meta no es indicador porque la meta es el valor esperado y el indicador la forma de medirlo.","Error: medir el éxito por el gasto ejecutado → el gasto prueba ejecución presupuestal, no cambio en la población."]},{"title":"Puntos clave","depth":"core","bullets":["El problema se formula con población, magnitud, lugar y efecto; sin esos datos la prioridad es discutible.","El objetivo expresa cambio, población y plazo, y no la actividad que el equipo prefiere realizar.","El indicador necesita fórmula, fuente, frecuencia y meta para poder interpretarse y compararse.","El presupuesto y el cronograma hacen viable el plan; sin ellos queda como declaración de intenciones.","El monitoreo ajusta la ejecución y la evaluación valora resultados; confundirlos retrasa las correcciones."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Cada actividad necesita responsable, plazo e indicador","text":"Si el plan solo enumera actividades, todavía no es un plan evaluable. Un objetivo debe expresar un cambio medible y temporal, y un indicador debe incluir fórmula, fuente, frecuencia y meta. Una cobertura promedio puede ocultar barreras por lengua, discapacidad, distancia o recursos, por lo que también hay que revisar a quiénes no llegó la intervención. El distractor típico confunde gasto ejecutado con resultado."}},{"title":"Plan local y APS","depth":"core","body":["El plan local de salud traduce las prioridades del ASIS en objetivos, actividades, responsables, recursos, cronograma e indicadores. En APS es el puente entre el diagnóstico territorial y la acción cotidiana del equipo.","Un plan no se evalúa por la cantidad de actividades, sino por los cambios en acceso, continuidad y condiciones de vida. La participación comunitaria y la articulación intersectorial son condiciones de implementación, no adornos del documento.","El plan local no es un anexo del ASIS: es el instrumento que traduce prioridades en objetivos, responsables, recursos, cronograma e indicadores. Su seguimiento se hace con la comunidad y con el Comité Local de Salud, y se ajusta cuando cambia el territorio."],"bullets":["Problema priorizado con población, magnitud y territorio.","Objetivo medible y temporal.","Actividades con responsable, recurso y plazo.","Indicadores de proceso, resultado e impacto.","Monitoreo y evaluación con la comunidad."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Metodología para el análisis de situación de salud local, priorización y agenda sanitaria.","Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, enfoques transversales y escenarios.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 2: medidas estadísticas.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017."]}],"sheet-psi-sp-2-8":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["Un sistema de información sanitaria reúne registros, procesos y plataformas que transforman la atención cotidiana en insumos para decidir. Lo integran el registro de atenciones del sistema de información en salud, la historia clínica, la receta electrónica y los datos de aseguramiento. A ello se suman las plataformas que permiten intercambiar información entre servicios. Ninguno de esos componentes sirve por separado: el valor aparece cuando el conjunto conserva la identidad de la persona y el significado de cada variable.","El registro describe lo que ocurrió en una atención concreta; el indicador resume un fenómeno en una población y un periodo. Confundirlos lleva a conclusiones falsas, porque una cifra puede crecer por más tamizajes y no por más enfermedad. La cadena se completa cuando el dato se analiza y sostiene una decisión verificable, con responsable y seguimiento.","La tecnología es un medio y no sustituye el consentimiento informado, el juicio clínico ni la responsabilidad profesional. Un formulario nuevo o una tableta no corrigen prácticas de registro deficientes; las hacen más visibles. Por eso la calidad del dato se gestiona con reglas, capacitación y devolución periódica de resultados al equipo que registra.","El denominador de la RIS sale del padrón nominal de población asignada. SISFAC registra familia, vivienda y entorno; el HIS registra la atención; REUNIS, ENDES, ENAHO e INEI aportan contexto y denominadores poblacionales; RENHICE sostiene la historia clínica electrónica y la interoperabilidad. Sin población nominalizada, la cobertura se infla y las brechas desaparecen."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","bullets":["La cadena de valor del dato avanza del registro a la consolidación, del análisis a la decisión y de allí a la verificación del efecto; cada eslabón distorsiona y el error se amplifica al agregar.","La perspectiva socio-técnica explica que el resultado depende de la interacción entre tecnología, procesos, personas y reglas; una plataforma moderna sobre un proceso confuso produce datos confusos.","La carga de registro opera como impuesto silencioso: cuando el formulario pide datos que nadie usa, el personal completa de memoria o copia del turno anterior y aumenta el error.","El bucle de retroalimentación sostiene la calidad: si el equipo nunca ve sus propias cifras, no tiene motivo para corregir lo que registra.","El uso secundario de datos, para gestión, vigilancia o investigación, amplía el valor del registro y a la vez exige gobernanza, acceso limitado y resguardo de la identidad.","El indicador convertido en meta única se distorsiona, porque se mejora la cifra sin mover el problema; conviene leer varios indicadores y contrastarlos con la observación directa."]},{"title":"Clasificación de sistemas y criterios de aplicación","depth":"full","body":["Los sistemas se distinguen por su propósito y por la unidad que describen. El registro asistencial describe personas y atenciones; el aseguramiento describe afiliación y cobertura; la plataforma de interoperabilidad describe el intercambio. El criterio práctico consiste en preguntar qué decisión se tomará con la información y qué unidad exige esa decisión, antes de elegir la fuente y antes de calcular."],"table":{"headers":["Sistema","Qué registra","Uso principal","Límite frecuente"],"rows":[["Registro de atenciones","Atenciones por servicio, diagnóstico y procedimientos","Consolidar producción y morbilidad atendida","No describe a quien no acudió al servicio"],["Historia clínica","Curso longitudinal de la persona y sus decisiones de cuidado","Sostener continuidad y juicio clínico","Duplicados y notas incompletas"],["Receta electrónica","Prescripción, dispensación y trazabilidad del medicamento","Controlar legibilidad, uso y stock","Exige conectividad y catálogo común"],["Aseguramiento","Afiliación, cobertura y elegibilidad","Verificar acceso a las prestaciones","No informa la atención recibida"],["Interoperabilidad","Intercambio entre sistemas distintos","Evitar doble captura y pérdida de historia","Requiere identificadores y reglas comunes"]]}},{"title":"Calidad del dato y control de atributos","depth":"full","table":{"headers":["Atributo","Pregunta de control","Riesgo si falla"],"rows":[["Completo","¿Están todos los campos necesarios para interpretar el registro?","Se pierden casos o variables y el indicador queda incompleto."],["Consistente","¿El mismo dato coincide entre formatos y momentos?","Aparecen cifras contradictorias y se pierde confianza."],["Oportuno","¿Está disponible cuando se necesita para decidir?","La respuesta llega tarde y la alerta pierde utilidad."],["Válido","¿El dato mide realmente lo que dice medir?","Se decide sobre una interpretación errónea del fenómeno."],["Trazable","¿Se sabe quién registró, cuándo y qué modificó?","No se puede auditar ni corregir el origen del error."],["Resguardado","¿El acceso está limitado a quien lo necesita?","Se expone información sensible y se pierde la confianza."]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir la pregunta y el uso antes de registrar: qué decisión se tomará con ese dato y quién la tomará.","2. Verificar la identificación única de la persona antes de abrir o completar un registro.","3. Registrar durante la atención, con los campos obligatorios y el lenguaje estandarizado del servicio.","4. Revisar el registro al cierre de la jornada y rectificar con nota de enmienda, sin borrar lo anterior.","5. Consolidar y depurar duplicados con trazabilidad, dejando constancia de cada cambio realizado.","6. Calcular el indicador con numerador, denominador, población y periodo explícitos en la ficha.","7. Comparar con la meta, la tendencia y las características de la población, y revisar a quién no llegó la acción.","8. Devolver el resultado al equipo y a la comunidad, y dejar registro de la decisión y de su seguimiento."]},{"title":"Indicadores y lectura de la brecha","depth":"full","bullets":["Un indicador sin denominador explícito no es comparable, porque la misma cantidad de casos puede reflejar más tamizajes o más enfermedad.","La positividad describe el rendimiento del tamizaje en el grupo y periodo medidos; no demuestra prevalencia comunitaria ni confirma diagnósticos.","La cobertura no equivale a acceso efectivo, ya que puede haber atenciones registradas sin continuidad del cuidado.","Duplicar personas infla numeradores y coberturas, por lo que unificar la identidad es requisito previo a cualquier comparación.","Los promedios ocultan barreras por lengua, discapacidad, distancia o costo; la revisión se hace por subgrupos y por territorio.","La ficha mínima del indicador incluye nombre, propósito, fórmula, unidad, población, periodo, fuente, frecuencia, responsable, línea de base, meta y limitaciones."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de la selva, sin conectividad estable, el psicólogo anota los tamizajes en un cuaderno y los transcribe al sistema semanas después, cuando hay señal. El servicio de psicología informa sus tamizajes sobre las personas que acudieron a consulta, mientras enfermería usa como denominador a toda la población asignada al establecimiento. En la reunión mensual ambas cifras se presentan como cobertura y nadie logra explicar la diferencia. Además, una persona figura con dos historias porque su segundo apellido se escribió distinto en cada registro. El equipo decide fijar una sola definición de denominador, unificar la identificación y registrar el día de la atención, con respaldo en papel cuando no haya señal."],"bullets":["Lectura del caso: el problema no era la falta de señal, sino la ausencia de una regla común de cálculo y de identificación.","Lectura del caso: transcribir semanas después reduce la oportunidad y facilita el error de digitación; conviene un registro mínimo en papel con los mismos campos.","Lectura del caso: comparar coberturas exige denominadores equivalentes, porque con poblaciones distintas la diferencia es aritmética y no sanitaria.","Lectura del caso: se descarta suspender el reporte o borrar los registros duplicados sin revisión, porque ambas decisiones destruyen la trazabilidad."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: confundir el registro con el indicador, porque el registro describe a una persona y el indicador resume a una población en un periodo.","Distinción: el HIS no es el SIS, porque el primero registra y consolida las atenciones prestadas y el segundo administra la afiliación y el financiamiento del aseguramiento.","Distinción: confidencialidad no es seguridad informática, porque la primera es un deber sobre el uso del dato y la segunda un conjunto de medidas que lo protegen.","Error: cambiar el denominador para mejorar la cifra, porque altera el significado del indicador y rompe la comparación entre periodos.","Distinción: dato agregado no es dato nominal, porque el primero no permite identificar personas y el segundo sí, con obligaciones distintas de resguardo.","Error: creer que la interoperabilidad consiste en compartir archivos, porque exige identificadores, vocabularios y reglas de acceso comunes.","Distinción: trazabilidad no es auditoría, porque la trazabilidad deja rastro de quién y cuándo, y la auditoría revisa ese rastro para verificar cumplimiento."]},{"title":"Puntos clave","depth":"core","bullets":["Un dato cambia decisiones solo cuando es completo, consistente, oportuno y válido; sin análisis se acumula información sin efecto.","El indicador se define antes de calcularlo, con numerador, denominador, población y periodo; cambiar cualquiera de ellos cambia el resultado.","La identificación única de la persona evita duplicados y sostiene la continuidad del cuidado entre servicios.","El control de accesos y el resguardo de datos sensibles son parte de la calidad y no un trámite posterior al registro.","La interoperabilidad reduce la doble captura y devuelve la historia a quien atiende, siempre que existan reglas comunes.","Devolver las cifras al equipo y a la comunidad cierra el circuito y mejora la calidad del registro siguiente."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Registro frente a indicador","text":"Cuando el enunciado describe una cifra que se compara entre servicios o periodos, la pregunta gira sobre el denominador y la definición del indicador. El distractor habitual propone cambiar el numerador o presentar el dato tal como está. Si el caso menciona dos historias o reportes incompatibles, la respuesta pertinente unifica la identificación y el criterio de cálculo antes de interpretar cualquier resultado."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Sistema de Información en Salud (HIS) y gestión de la historia clínica.","Fuente: MINSA — Metodología para el análisis de situación de salud local, uso de la información para la decisión.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition, lección 2: medidas estadísticas.","Fuente: OMS — Informe sobre sistemas de información sanitaria y salud digital."]}],"sheet-psi-sp-2-9":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La seguridad alimentaria describe una situación: el alimento existe, puede obtenerse, se aprovecha de forma adecuada y esa condición se mantiene. Sus cuatro dimensiones se encadenan, de modo que un alimento disponible puede no ser accesible y uno accesible puede no ser inocuo. La inocuidad, en cambio, califica al alimento concreto y pregunta si su consumo puede dañar la salud por agentes biológicos, químicos o físicos.","La malnutrición abarca desnutrición, deficiencias de micronutrientes, sobrepeso y obesidad, y puede coexistir en una comunidad e incluso en una misma familia. Por eso la valoración combina antropometría, clínica, dieta y condiciones del hogar, y no se agota en el peso. La promoción alimentaria considera cultura, economía y ciclo de vida para que las recomendaciones sean posibles de cumplir.","La vigilancia nutricional identifica riesgos y orienta acciones del equipo y de otros sectores; su utilidad depende de que el dato se analice y se traduzca en decisiones. El psicólogo interviene en la consejería, en la adherencia al tratamiento y en la comunicación del riesgo, sin reemplazar la evaluación nutricional ni el manejo clínico."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","bullets":["Los determinantes sociales explican la elección alimentaria: ingreso, precio, territorio y tiempo de cuidado pesan más que la información disponible en el hogar.","El enfoque de curso de vida sostiene que la nutrición temprana condiciona crecimiento, desarrollo cognitivo y riesgo de enfermedad, y que el efecto se acumula.","La transición nutricional describe la convivencia de desnutrición y obesidad por cambios en la dieta y en la actividad, con frecuencia dentro de la misma familia.","La inseguridad alimentaria activa estrategias de afrontamiento que reducen primero la variedad y la calidad de la dieta, y producen déficits que no se ven en el peso.","El tiempo y la temperatura gobiernan la multiplicación microbiana, por lo que la cadena de frío y la cocción son los puntos de mayor impacto sobre la carga de peligros.","La consejería modifica conductas cuando trabaja con metas pequeñas, ensayo y refuerzo; la información aislada rara vez cambia la práctica cotidiana."]},{"title":"Cuatro dimensiones de la seguridad alimentaria","depth":"full","body":["Las dimensiones se evalúan por separado porque cada falla admite una respuesta distinta. Si el problema es de disponibilidad, la acción es productiva o de abastecimiento. Si la falla es de acceso, la respuesta es económica o de transporte. Si es de utilización, la acción es educativa y sanitaria, y si es de estabilidad, la respuesta es de protección y reserva. Confundirlas conduce a intervenciones que no tocan la causa."],"table":{"headers":["Dimensión","Pregunta que responde","Ejemplo de falla"],"rows":[["Disponibilidad","¿Hay alimentos suficientes y adecuados en el territorio?","Escasez estacional o pérdida de cosechas."],["Acceso","¿Las familias pueden obtenerlos con sus recursos y a una distancia razonable?","Precio alto o falta de transporte."],["Utilización","¿Se usan en cantidad, calidad y preparación adecuadas?","Falta de agua segura o prácticas de higiene insuficientes."],["Estabilidad","¿La situación se mantiene en el tiempo?","Crisis recurrentes que interrumpen el abastecimiento."]]}},{"title":"Inocuidad: peligros y cadena alimentaria","depth":"full","body":["El control de la inocuidad se organiza en la cadena, desde la producción y el transporte hasta la preparación y el consumo. Los peligros ingresan en puntos distintos y se multiplican cuando fallan el frío, el agua o la higiene. Un alimento puede ser seguro en origen y volverse peligroso en la cocina si se rompe la separación entre crudos y cocidos o si se enfría lentamente."],"table":{"headers":["Tipo de peligro","Qué incluye","Control prioritario"],"rows":[["Biológico","Bacterias, virus y parásitos que llegan por agua, manos, superficies o animales","Higiene de manos y superficies, agua segura, cocción y control de temperatura"],["Químico","Residuos de plaguicidas, metales, aditivos mal usados o productos de limpieza","Insumos autorizados, enjuague, dosificación y almacenamiento separado"],["Físico","Vidrio, metal, piedra o plástico duro que puede lesionar al consumidor","Inspección del alimento, mantenimiento de equipos y protección del área de preparación"]]}},{"title":"Malnutrición, anemia y curso de vida","depth":"core","bullets":["La valoración nutricional combina antropometría, examen clínico, dieta y entorno; un indicador aislado no describe el estado nutricional.","La anemia por deficiencia de hierro se sospecha por la clínica y se confirma con laboratorio; la consejería acompaña el tratamiento y no lo reemplaza.","El sobrepeso y la obesidad conviven con la desnutrición en una misma comunidad, por lo que ambas caras se evalúan en el mismo servicio.","El control de crecimiento y desarrollo es la puerta de entrada para detectar riesgo nutricional en la infancia y para orientar a la familia.","La lactancia materna protege frente a infecciones y desnutrición; su promoción requiere sostén práctico y acompañamiento, no solo mensajes.","El embarazo, la primera infancia y la vejez concentran vulnerabilidad porque aumentan los requerimientos y reducen las reservas del organismo."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Identificar qué está fallando: disponibilidad, acceso, utilización, inocuidad o estado nutricional, porque cada falla exige respuesta distinta.","2. Medir y registrar peso, talla y edad con técnica verificada y la referencia que usa el servicio.","3. Revisar la dieta y las prácticas de preparación, conservación y acceso al agua en el hogar.","4. Clasificar el riesgo y decidir si corresponde consejería, suplementación, tratamiento o derivación.","5. Acordar con la familia un cambio concreto y verificable, ajustado a sus recursos y a su cultura.","6. Coordinar con el quiosco escolar, el comedor o el mercado local cuando el problema es del entorno.","7. Verificar la adherencia y el resultado en el control siguiente, ajustando sin repetir el mismo mensaje.","8. Notificar el evento ante la sospecha de un brote o de un alimento contaminado, conservando la evidencia disponible."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Tras el desayuno escolar en una escuela de la sierra, ocho estudiantes presentan diarrea y dolor abdominal en la misma mañana, y dos docentes refieren lo mismo. La dirección propone suspender las clases y desinfectar el comedor antes de avisar a la red de salud. El psicólogo advierte que la prioridad es caracterizar el evento y cortar la exposición. Propone conservar los alimentos servidos, revisar el agua y la cadena de frío, buscar otros casos en las familias y notificar al establecimiento de salud. Mientras se investiga, el equipo acuerda medidas de higiene, agua segura y comunicación con las familias para evitar la automedicación y la estigmatización de la persona que manipula los alimentos."],"bullets":["Lectura del caso: el evento es de inocuidad y no de acceso, porque el alimento estaba disponible y fue consumido.","Lectura del caso: conservar muestras y buscar casos permite identificar la fuente; desinfectar antes de recolectar evidencia la destruye.","Lectura del caso: comunicar con las familias reduce la automedicación y evita culpar a una sola persona sin datos.","Lectura del caso: la notificación activa la vigilancia y convierte un episodio local en información útil para otros servicios."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: responder con una charla educativa a un alimento contaminado, porque el problema es de inocuidad y exige control del peligro.","Distinción: seguridad alimentaria no es inocuidad, porque la primera mira el acceso sostenido y la segunda la ausencia de peligro en el alimento.","Distinción: disponibilidad no es acceso, porque puede haber alimento en el mercado y familias que no logran comprarlo.","Distinción: inocuidad no es calidad, porque la calidad incluye atributos nutricionales y sensoriales, y la inocuidad se refiere al daño.","Error: reducir el precio para resolver un problema de higiene, porque mejora el acceso y mantiene la exposición al peligro.","Distinción: desnutrición no es malnutrición, porque la malnutrición incluye también sobrepeso, obesidad y deficiencias.","Error: dar por suficiente la vigilancia con pesar y medir, porque sin análisis ni decisión no orienta ninguna acción."]},{"title":"Puntos clave","depth":"core","bullets":["La seguridad alimentaria se juega en el acceso sostenido; la inocuidad, en la ausencia de peligros en el alimento consumido.","Cada dimensión tiene su respuesta: precio y transporte para el acceso, higiene y frío para la utilización y la inocuidad.","La malnutrición incluye desnutrición, deficiencias, sobrepeso y obesidad, y puede presentarse en la misma familia.","La vigilancia nutricional sirve cuando el dato se analiza y cambia una decisión del servicio.","La consejería funciona con acuerdos pequeños y verificables, ajustados a los recursos y a las prácticas locales.","Ante un brote, la prioridad es cortar la exposición y notificar, antes que educar o tranquilizar."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Inocuidad o acceso","text":"Cuando el enunciado señala alimento presente pero inasequible, la dimensión comprometida es el acceso; cuando el alimento existe y puede dañar, el problema es de inocuidad. El distractor típico ofrece una charla para un alimento contaminado o una medida de higiene para un problema de precio. Leer el verbo del caso, obtener, comprar, conservar o manipular, orienta la respuesta correcta."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Lineamientos de alimentación y nutrición saludable en el curso de vida.","Fuente: DIGESA — Vigilancia sanitaria e inocuidad alimentaria.","Fuente: OMS — Informe sobre seguridad alimentaria e inocuidad de los alimentos."]}],"sheet-psi-sp-2-2":[{"title":"Conceptos que sostienen el tema","depth":"core","bullets":["El ambiente no es un escenario pasivo: distribuye exposición y convierte la desigualdad social en enfermedad.","Hablar de determinante ambiental exige nombrar el agente, la vía, la población y el efecto posible.","El peligro existe aunque nadie esté expuesto; el riesgo aparece cuando hay exposición y vulnerabilidad.","La dosis distingue una exposición tolerable de una que produce daño, y no se deduce de la sola presencia del agente.","El agua, el saneamiento y la vivienda son determinantes ambientales con efecto directo sobre enfermedades infecciosas.","El ruido, el calor y los desastres afectan la salud mental además de la física.","La respuesta ambiental casi nunca es individual: reclama coordinación con municipalidad, saneamiento y comunidad."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El efecto de un agente ambiental sigue una cadena: fuente, medio, vía de contacto y cantidad que llega al organismo. La salud se altera cuando esa cadena se completa con una intensidad suficiente y durante un tiempo suficiente. Por eso encontrar una sustancia en el ambiente no equivale a demostrar daño: falta establecer si hubo contacto, en qué cantidad y en quién.","El riesgo ambiental se valora combinando tres elementos: el peligro, la exposición y la vulnerabilidad. El peligro describe la capacidad de dañar; la exposición, quién entra en contacto y cuánto; la vulnerabilidad, qué condiciones amplifican el efecto. Un mismo nivel de exposición produce consecuencias distintas en un niño, una gestante, una persona con enfermedad respiratoria o un trabajador sin protección.","La desigualdad ambiental explica por qué el daño se concentra. Los barrios con menos servicios conviven con agua insegura, aire contaminado, calor extremo y criaderos de vectores, y además tienen menos recursos para protegerse o mudarse. El determinante ambiental se cruza así con el social: la exposición no se distribuye al azar.","En salud mental los mecanismos son variados. El calor sostenido altera el sueño y la irritabilidad; el ruido crónico fragmenta el descanso; los desastres producen desplazamiento, duelo y pérdida de redes; y la incertidumbre sobre una exposición desconocida sostiene ansiedad en la comunidad. La comunicación de riesgo forma parte de la intervención, porque el silencio también produce daño."]},{"title":"Clasificación y criterios de aplicación","depth":"full","table":{"headers":["Componente ambiental","Vía principal","Población vulnerable","Medida de control"],"rows":[["Agua y saneamiento","Ingestión y contacto","Niños y niñas, gestantes, familias sin red de agua","Cloración, almacenamiento seguro y disposición de excretas"],["Aire y humo doméstico","Inhalación","Personas con enfermedad respiratoria y cocinas sin ventilación","Ventilación, cocinas mejoradas y reducción del humo"],["Vectores","Picadura","Familias con recipientes sin tapar","Eliminar criaderos, tapar y limpiar recipientes"],["Ruido","Auditiva y estrés","Personas que viven o trabajan cerca de la fuente","Control de la fuente y regulación de horarios"],["Residuos y químicos","Contacto, ingestión o inhalación","Trabajadores informales y población cercana","Disposición adecuada y uso de protección"],["Calor y eventos extremos","Exposición directa","Personas mayores, menores y trabajadores al aire libre","Refugio, hidratación y planes de respuesta"]]}},{"title":"Peligro, riesgo y exposición","depth":"full","table":{"headers":["Concepto","Definición operativa","Error que se comete"],"rows":[["Peligro","Condición del entorno capaz de causar daño","Se declara riesgo sin evaluar la exposición"],["Exposición","Contacto efectivo por una vía, con intensidad y duración","Se supone contacto por cercanía a la fuente"],["Dosis","Cantidad que llega al organismo en un tiempo determinado","Se iguala presencia del agente con dosis dañina"],["Vulnerabilidad","Condición que amplifica el efecto de la misma exposición","Se evalúa el riesgo sin mirar a quién afecta"],["Riesgo","Probabilidad de daño según peligro, exposición y vulnerabilidad","Se confunde con la simple existencia del peligro"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Describir la queja o el hallazgo y delimitar el lugar y el periodo en que ocurre.","2. Identificar el agente o la condición sospechosa e indagar su fuente.","3. Determinar la vía de exposición y la intensidad del contacto.","4. Caracterizar a la población expuesta y reconocer los grupos más vulnerables.","5. Estimar el riesgo combinando peligro, exposición y vulnerabilidad, y explicitar la incertidumbre.","6. Priorizar el control de la fuente y, cuando no sea posible, reducir la exposición.","7. Comunicar lo que se sabe y lo que se investiga, sin prometer certeza ni minimizar el riesgo.","8. Activar la ruta sanitaria y epidemiológica, y coordinar con los sectores que controlan la fuente."]},{"title":"Dengue y control de vectores","depth":"full","body":["El dengue se transmite principalmente por la picadura de hembras infectadas de Aedes aegypti. El vector tiene actividad diurna, con mayor intensidad al amanecer y al final de la tarde, y puede picar en otros momentos del día. Se cría en recipientes con agua, de modo que el entorno doméstico explica buena parte del riesgo y también buena parte de la solución.","El control combina acciones sobre la fuente y protección de las personas. Eliminar criaderos, tapar y limpiar los recipientes con agua y evitar picaduras son medidas centrales, sostenidas por la participación comunitaria. La fumigación reduce el mosquito adulto y se usa como complemento; no reemplaza las medidas domiciliarias porque no elimina los hábitats de reproducción."],"bullets":["El control de criaderos actúa sobre la fuente del vector y por eso es la medida de base.","Tapar y limpiar los recipientes elimina el hábitat de cría y reduce la densidad del mosquito.","La protección personal complementa el control domiciliario y comunitario.","La fumigación no sustituye la eliminación de criaderos, porque no interrumpe la reproducción."]},{"title":"Clave oficial y manejo técnico","depth":"full","body":["En el examen de Psicología 2026-II, una pregunta sobre exposición a mercurio tuvo una clave oficial orientada a la notificación epidemiológica. Esa clave se conserva como referencia de examen y no sustituye la evaluación de seguridad ni el protocolo técnico para proteger a las personas.","La diferencia importa: una respuesta de examen elige la opción esperada por el cuadernillo, mientras que el manejo de una exposición real exige evaluar la fuente, la vía, la dosis y la población expuesta, y activar la ruta sanitaria. Convertir la alternativa marcada en una regla universal puede retrasar la protección de las personas."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En una comunidad de la selva, varias familias ribereñas presentan dolores de cabeza, irritabilidad y molestias digestivas. Cerca del caserío funciona un establecimiento que usa mercurio para el procesamiento de mineral y los residuos se acumulan en el suelo. Algunos vecinos atribuyen los síntomas al calor y otros al agua del río. Una promotora comenta que los niños juegan en la zona donde se acumulan los residuos.","El psicólogo del centro de salud documenta lo observado, evita afirmar la causa sin evaluación y coordina con el responsable de vigilancia y con la autoridad sanitaria. En paralelo propone alejar a los niños del área, informar sin alarmar y sostener contención emocional para las familias, mientras se evalúa la exposición y se activa la ruta correspondiente."],"bullets":["Lectura del caso: los síntomas inespecíficos no identifican por sí solos el agente, y por eso la evaluación precede a la conclusión.","Lectura del caso: la acumulación de residuos cerca de la vivienda define la fuente y la vía de exposición probable.","Lectura del caso: los niños son el grupo más vulnerable y alejarlos del área es una medida de protección inmediata.","Alternativa descartada: atribuir todo al calor evita la evaluación de la fuente y deja la exposición activa.","Error que se evita: prometer a la comunidad que no hay riesgo antes de contar con la evaluación."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: afirmar que existe intoxicación porque se detectó una sustancia, porque la presencia no equivale a dosis dañina.","Distinción: peligro no es riesgo, porque el peligro es la capacidad de dañar y el riesgo depende de la exposición.","Distinción: exposición no es dosis, porque la exposición describe el contacto y la dosis la cantidad que llega al organismo.","Error: evaluar el riesgo sin identificar la población vulnerable, porque la misma exposición afecta de distinto modo.","Error: confundir una queja inespecífica con un diagnóstico ambiental, porque los síntomas no identifican el agente.","Error: reemplazar el control de criaderos por fumigación, porque la fumigación no elimina los hábitats de reproducción.","Distinción: vigilancia sanitaria no es vigilancia epidemiológica, porque la primera vigila el ambiente y la segunda los eventos de salud de la población."]},{"title":"Puntos clave","depth":"core","bullets":["La evaluación ambiental empieza por la fuente y la vía, y solo después considera el efecto en la salud.","El riesgo no se deduce de la presencia del agente, porque depende de la exposición y de la vulnerabilidad.","Los grupos más expuestos suelen ser también los que tienen menos recursos para protegerse.","El control de criaderos es la medida de base frente al dengue y la fumigación solo la complementa.","La comunicación de riesgo debe distinguir lo confirmado de lo que sigue en investigación.","La respuesta ambiental es intersectorial, porque el sector salud no controla el agua, el suelo ni los residuos."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"No todo es intoxicación","text":"Primero se identifica la fuente, la vía y la población vulnerable; después se controla la fuente. El distractor habitual afirma que la sola presencia de un contaminante demuestra daño o que la fumigación reemplaza la eliminación de criaderos. En dengue, el control de recipientes con agua es la medida de base y la fumigación es un complemento."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: OMS Europa — Public health advice on dengue fever, actividad de Aedes aegypti.","Fuente: CENEPRED — Manual para la evaluación de riesgos originados por fenómenos naturales, 2.ª edición, clasificación de peligros.","Fuente: CENEPRED — Manual para la elaboración de riesgos inducidos por la acción humana.","Fuente: MINSA — Atención integral de pacientes con dengue en el Perú, definiciones y clasificación clínica."]}],"sheet-psi-sp-2-3":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La participación comunitaria designa la intervención activa de la población en el diagnóstico, la priorización, la planificación, la ejecución y la evaluación de las acciones de salud. No es un acto único ni una autorización que el servicio solicita al final, sino un proceso con momentos, reglas y responsabilidades.","Hablar de participación situada implica delimitar el territorio, reconocer a quienes lo habitan y a sus organizaciones, y habilitar espacios donde sea posible deliberar y decidir. Sin territorio ni actores identificados, la convocatoria se vuelve genérica y suele reunir solo a los habituales.","La apropiación ocurre cuando la comunidad incorpora el proceso a su vida organizativa y puede sostenerlo con recursos, liderazgos y acuerdos propios. En ese punto la población deja de ser receptora pasiva y se convierte en actor del cuidado colectivo."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La participación no depende solo de la voluntad de convocar: se explica por el poder disponible, las redes de confianza y las expectativas que cada actor tiene sobre los demás. Estos mecanismos permiten prever qué espacio sostendrá acuerdos y cuál se vaciará cuando cambie la coyuntura."],"bullets":["El espectro IAP2 (informar, consultar, involucrar, colaborar y empoderar) ordena la participación según el poder cedido; la escalera de Arnstein es otra propuesta clásica de ocho peldaños y no debe confundirse con el espectro IAP2.","El capital social, entendido como redes, confianza y reciprocidad, reduce los costos de coordinar y hace más probable que los acuerdos se cumplan sin vigilancia permanente.","La autoeficacia colectiva explica por qué una comunidad participa cuando comprueba que su acción produce efectos; sin resultados visibles el interés se agota.","La acción colectiva depende de incentivos, costos y expectativas mutuas: si cada actor espera que los demás no cumplirán, la convocatoria se vacía aunque el problema sea grave.","El mecanismo de apropiación encadena información comprensible, confianza, capacidad de decisión y relevo de liderazgos; si falla un eslabón, el proceso se interrumpe al retirarse el equipo.","La exclusión opera cuando se convoca por redes ya establecidas: quienes tienen menos tiempo, otra lengua o carga de cuidado quedan fuera y su ausencia se interpreta como desinterés."]},{"title":"Niveles de participación y criterios de aplicación","depth":"full","body":["Los niveles del espectro IAP2 no forman una escalera que siempre deba recorrerse completa: describen cuánto poder se comparte en un momento dado. Un servicio puede informar sobre un tema y colaborar en otro, siempre que explicite el nivel y no prometa decisión donde solo habrá consulta."],"table":{"headers":["Nivel","Qué implica","Cómo se reconoce","Riesgo si se confunde"],"rows":[["Informar","Comunicar decisiones y resultados de forma comprensible.","La comunidad recibe datos y no influye en la decisión.","Se presenta como participación y se legitima una decisión externa."],["Consultar","Recoger opiniones o necesidades antes de decidir.","Hay preguntas y devolución, pero la decisión queda en el servicio.","La consulta se usa para validar lo que ya estaba decidido."],["Involucrar","Incorporar a la comunidad en el análisis y en el diseño.","Hay trabajo conjunto en el diagnóstico y en las propuestas.","Se pide opinión sin compartir información ni recursos."],["Colaborar","Compartir decisiones, responsabilidades y recursos.","Existen acuerdos con responsables y seguimiento verificable.","La corresponsabilidad se declara pero no se opera."],["Empoderar","Trasladar capacidad de decisión y control a la organización comunitaria.","La comunidad conduce, evalúa y sostiene las acciones.","Se confunde apoyo técnico con tutela permanente."]]}},{"title":"Actores, consejo de salud y conflictos","depth":"full","bullets":["La población organizada incluye juntas vecinales, comités, asociaciones y grupos de base; los liderazgos informales también movilizan y deben ser reconocidos.","El consejo de salud sirve si prioriza, acuerda y vigila; sin reglamento, actas ni seguimiento se reduce a una reunión protocolar.","El presupuesto participativo abre una ventana de incidencia municipal; la demanda compite mejor si presenta problema, objetivo, costo y responsable.","Los conflictos por recursos, representación o afinidad política son propios del proceso; se gestionan con reglas y actas, no se evitan ni se atribuyen a falta de cultura.","La cooptación aparece cuando el servicio usa el espacio para legitimar decisiones tomadas; se reconoce porque la comunidad no puede proponer ni objetar.","La sostenibilidad depende de capacidades locales, relevo de liderazgos, información accesible y financiamiento estable, no de la permanencia de una sola persona.","Sumar actores con recursos y competencias amplía el alcance, siempre que la agenda no sea impuesta y los acuerdos se registren."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Delimitar el territorio y la población con la que se trabajará, usando el mapa del sector y los registros disponibles.","2. Mapear actores, recursos y conflictos, incluidos los grupos que no suelen asistir a las reuniones del servicio.","3. Convocar con anticipación, en horario y lugar accesibles, con agenda escrita y materiales comprensibles.","4. Presentar la información técnica, explicar sus límites y abrir la deliberación sobre el problema y sus alternativas.","5. Priorizar con criterios explícitos y registrar acuerdos, responsables, plazos y forma de seguimiento.","6. Vincular los acuerdos con espacios formales, como el consejo de salud o el presupuesto participativo.","7. Ejecutar con corresponsabilidad y dejar actas accesibles para que la comunidad pueda verificar avances.","8. Evaluar con la comunidad, ajustar lo que no funcionó y preparar el relevo de liderazgos antes de cerrar el proceso."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un distrito de la sierra, el centro de salud convoca al consejo de salud para presentar un plan de salud mental ya redactado. Asisten el alcalde, juntas vecinales, la directora del colegio y una organización de mujeres, pero la reunión consiste en leer diapositivas y pedir firmas de conformidad. Una lideresa pregunta por qué no se incluyó el consumo de alcohol en adolescentes, que la comunidad considera prioritario. El psicólogo responsable advierte que el plan no tiene actividades para ese problema y propone abrir un diagnóstico participativo breve, con recorrido por el sector y reuniones por grupos. La municipalidad ofrece incluir la demanda en el presupuesto participativo si se presenta con problema, objetivo y costo. El consejo acuerda priorizar el consumo de alcohol, convocar a jóvenes y revisar avances en dos meses."],"bullets":["Lectura del caso: la convocatoria existía, pero el nivel era informar; sin deliberación no hay participación efectiva.","Lectura del caso: el diagnóstico participativo permitió que el problema priorizado surgiera del territorio y no del escritorio.","Lectura del caso: el presupuesto participativo se usó como oportunidad de incidencia, con formato técnico y no como trámite.","Lectura del caso: se evita firmar conformidad sin capacidad de decisión y se establece seguimiento con plazo."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: medir la participación por el número de asistentes → la asistencia no revela quién habla, quién decide ni si los acuerdos se cumplen.","Distinción: informar no es consultar porque la consulta recoge opinión antes de decidir, aunque no garantice influencia sobre la decisión final.","Distinción: consultar no es colaborar porque colaborar comparte decisiones, responsabilidades y recursos, no solo opiniones.","Error: convocar solo a quienes ya participan → refuerza los liderazgos de siempre y deja fuera a grupos con barreras de horario, lengua o cuidado.","Distinción: un comité existente no es participación efectiva si no delibera ni decide; la estructura sin poder se vacía.","Error: tratar el conflicto como fracaso → evitarlo desplaza la tensión y debilita los acuerdos; gestionarlo con reglas lo vuelve productivo.","Distinción: participación instrumental no es empoderamiento porque usa a la comunidad para legitimar una decisión ajena."]},{"title":"Puntos clave","depth":"core","bullets":["La participación se ubica por el poder de decisión y no por la cantidad de reuniones; eso evita declarar éxito con espacios vacíos.","El mapeo de actores incluye a los ausentes, porque su ausencia suele indicar barreras y no desinterés.","El consejo de salud sirve si prioriza y vigila; sin actas ni seguimiento se convierte en trámite.","El presupuesto participativo exige propuesta técnica; sin problema, costo y responsable la demanda no compite.","La sostenibilidad se construye con capacidades y relevo; depender de una persona hace frágil el proceso."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Asistencia no es participación","text":"Cuando el enunciado describe una reunión donde la comunidad solo escucha, o un comité que existe pero no decide, el nivel es informativo. La respuesta correcta suele exigir deliberación, capacidad de decisión y acuerdos con responsables y seguimiento. El distractor típico confunde convocar con participar y propone más reuniones en lugar de redistribuir el poder de decisión."}},{"title":"Participación y APS","depth":"core","body":["La participación comunitaria es un componente de la APS, no un acto protocolario. Implica que la población intervenga en la identificación de problemas, la deliberación, la priorización, la ejecución y la evaluación de las acciones de salud.","Participar no es solo asistir a una reunión ni firmar un acta. La participación efectiva exige información comprensible, capacidad de decisión y rendición de cuentas. El consejo de salud, el presupuesto participativo y los comités locales son espacios posibles, no garantías automáticas.","La participación tiene dos vías: la comunitaria —diagnóstico, priorización, ejecución y evaluación— y la vigilancia ciudadana del cumplimiento y la rendición de cuentas. El Comité Local de Salud, con la RIS y la sociedad civil organizada, es un espacio de deliberación y monitoreo, no solo de convocatoria."],"bullets":["Diferenciar información, consulta, deliberación, decisión y cogestión.","Mapear actores, intereses y conflictos antes de convocar.","Acordar qué se decide, quién decide y cómo se verificará.","Evitar convocar solo para validar una decisión ya tomada."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Metodología para el análisis de situación de salud local, participación de actores y priorización.","Fuente: OMS — Primary health care, servicios integrados, acción multisectorial y participación.","Fuente: MINSA — NTS N.° 138-MINSA/2017/DGIESP, RM 574-2017/MINSA, funciones del Centro de Salud Mental Comunitaria.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017.","Fuente: OMS — Carta de Ottawa, 21/11/1986; cinco campos de acción para la promoción de la salud.","Fuente: International Association for Public Participation (IAP2) — Spectrum of Public Participation.","Fuente: Arnstein SR. — A ladder of citizen participation. J Am Inst Plann. 1969;35(4):216-224."]}],"sheet-psi-sp-2-10":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La gestión de residuos en un establecimiento de salud es una cadena de decisiones que empieza cuando alguien genera el residuo y termina en el tratamiento y la disposición final. Cada etapa conserva la identificación de la clase, de modo que el biocontaminado, el especial, el común y el punzocortante siguen rutas distintas sin mezclarse.","La segregación es la decisión más importante porque define todo lo que ocurre después: un residuo mal separado contamina el resto, encarece el tratamiento y expone a quien lo manipula. El acondicionamiento, con la bolsa o el recipiente que corresponde, materializa esa decisión y la hace visible a lo largo de la ruta.","Retirar la bolsa al alcanzar tres cuartas partes de su capacidad y prohibir la compactación manual no son formalismos: reducen derrames, pinchazos y aerosoles. La trazabilidad del residuo protege al personal de limpieza, al personal asistencial y a la comunidad, y permite responder ante un derrame o una exposición."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","bullets":["El control en la fuente ordena todo el sistema: separar donde se genera evita contaminar el resto y reduce el volumen que requiere tratamiento especial.","La jerarquía de manejo prioriza evitar la generación, luego reducir, reutilizar y reciclar, y deja el tratamiento y la disposición final como últimas opciones.","La vía de exposición explica el accidente: el pinchazo deposita material contaminado bajo la piel, y el derrame acerca el agente a mucosas y piel lesionada.","La carga microbiana del residuo crece con el tiempo y la humedad, por lo que la demora en el retiro aumenta el riesgo aunque la bolsa esté bien cerrada.","La economía del residuo es un argumento de gestión: cuanto mejor se segrega, menor es el volumen peligroso y menor el costo de su tratamiento.","La responsabilidad es compartida y escalonada: quien genera segrega, quien transporta conserva la integridad y quien trata certifica el destino final."]},{"title":"Clases, colores y cuidados","depth":"full","table":{"headers":["Clase","Color o recipiente","Ejemplos","Cuidado principal"],"rows":[["Biocontaminado","ROJO · bolsa","Gasas con sangre, cultivos y material contaminado","Cerrar al llegar a 3/4; no compactar"],["Especial","AMARILLO · bolsa","Químicos, fármacos peligrosos y otros especiales","Manejar según su riesgo específico"],["Común","NEGRO · bolsa","Papel, envolturas y material sin contaminación","No mezclar con residuos peligrosos"],["Punzocortante","RÍGIDO · recipiente","Agujas, lancetas, hojas y ampollas rotas","No reencapuchar; cierre hermético"]]}},{"title":"Ruta de gestión y puntos de control","depth":"full","body":["Cada etapa tiene un punto de control verificable. Si el control falla en la segregación, ninguna etapa posterior lo corrige sin riesgo; si falla en el almacenamiento o en el transporte, el residuo pierde identificación y se mezcla. La verificación se hace en el turno y se registra, porque un residuo sin registro no tiene destino demostrable."],"table":{"headers":["Etapa","Qué se hace","Criterio de verificación","Responsable"],"rows":[["Generación y segregación","Separar en el punto de generación según clase y riesgo","Cada residuo está en el recipiente que le corresponde","Quien genera el residuo"],["Acondicionamiento","Usar bolsa o recipiente con color y rótulo correctos","Recipiente íntegro, rotulado y con símbolo cuando corresponde","Personal asistencial y de limpieza"],["Almacenamiento primario","Retener el residuo en el servicio hasta su retiro","Bolsa cerrada al llegar a tres cuartas partes y sin compactar","Servicio que lo genera"],["Almacenamiento central","Concentrar los residuos hasta el transporte externo","Ambiente diferenciado por clase y con acceso restringido","Responsable de residuos"],["Transporte","Trasladar con ruta, horario y recipientes diferenciados","Ruta que no cruza zonas limpias ni horarios de atención","Personal de limpieza"],["Tratamiento y disposición","Reducir la carga y entregar a la empresa autorizada","Registro de entrega y constancia del destino","Establecimiento y empresa operadora"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Identificar la clase del residuo antes de tocarlo y verificar el color del recipiente disponible.","2. Separar en el punto de generación y no trasvasar el contenido de una bolsa a otra.","3. Depositar los punzocortantes directamente en el recipiente rígido, sin reencapuchar la aguja.","4. Cerrar la bolsa al llegar a tres cuartas partes de su capacidad, sin comprimirla con manos ni pies.","5. Rotular y trasladar por la ruta establecida, en horario distinto al de la atención.","6. Almacenar por clase en el ambiente destinado, con acceso restringido y sin mezclar bolsas.","7. Verificar la entrega al tratamiento y conservar el registro que demuestra el destino del residuo.","8. Ante una exposición o un derrame, aplicar el procedimiento de respuesta y registrar el incidente ocurrido."]},{"title":"Riesgo ocupacional y comunitario","depth":"core","bullets":["La exposición ocurre por vía percutánea, por contacto con mucosas o piel lesionada y también por inhalación o ingestión.","La exposición es el contacto con el agente; el efecto es el daño que aparece después y puede tardar semanas en manifestarse.","El personal de limpieza y transporte concentra riesgo porque manipula residuos ya mezclados y sin identificación clara.","Un derrame de residuo biocontaminado exige delimitar el área, usar protección, desinfectar y registrar lo ocurrido.","La comunidad se expone cuando los residuos se disponen en espacios abiertos, se reciclan sin control o se queman.","Los punzocortantes mal dispuestos lesionan a trabajadores de limpieza y a recolectores municipales, fuera de la vista del servicio."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de la costa, el psicólogo observa que las bolsas rojas se guardan junto a los tachos de papel en el pasillo. El recipiente de punzocortantes está lleno y sin tapa, y el camión municipal recoge todo junto al final del día. El personal de limpieza refiere que no existe ambiente de almacenamiento y que la empresa no siempre pasa. El equipo decide ordenar primero el punto de generación y conseguir un recipiente rígido rotulado. Luego define un espacio cerrado para el almacenamiento y acuerda con la municipalidad y con la red de salud la entrega diferenciada, con registro de cada salida."],"bullets":["Lectura del caso: la falla principal está en la segregación y en el acondicionamiento, y se arrastra a todas las etapas posteriores.","Lectura del caso: un recipiente rígido lleno y sin tapa anula su función protectora aunque la clase sea la correcta.","Lectura del caso: el acuerdo con la municipalidad convierte una práctica informal en una ruta con responsable y constancia.","Lectura del caso: se descarta cambiar los colores o aumentar la frecuencia de recolección, porque no corrigen la separación en origen."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: mezclar residuos peligrosos con comunes, porque contamina todo el volumen y obliga a tratar como peligroso lo que no lo era.","Error: usar bolsa roja para papel o envolturas, porque cambia la ruta del residuo y aumenta el costo sin proteger a nadie.","Error: llenar la bolsa hasta el tope y comprimirla con las manos, porque produce derrames y pinchazos al cerrar y trasladar.","Error: reencapuchar una aguja antes de desecharla, porque el movimiento acerca la punta a la mano y provoca el accidente que se quiere evitar.","Distinción: biocontaminado no es especial, porque el primero tiene riesgo biológico y el segundo riesgo químico o farmacológico.","Distinción: segregar no es acondicionar, porque la segregación decide la clase y el acondicionamiento elige el recipiente que la representa.","Distinción: peligro no es riesgo, porque el peligro es el agente o la fuente y el riesgo es la probabilidad de daño en una situación concreta.","Distinción: almacenar no es disponer, porque el almacenamiento retiene el residuo de forma temporal y la disposición lo entrega a su destino definitivo."]},{"title":"Puntos clave","depth":"core","bullets":["La segregación define la ruta completa, porque un residuo mal separado encarece el tratamiento y expone a quien lo manipula.","Rojo, amarillo y negro identifican biocontaminado, especial y común, y el punzocortante exige recipiente rígido rotulado.","El retiro a tres cuartas partes y la prohibición de compactar previenen derrames y pinchazos durante el cierre.","Los punzocortantes se depositan directamente, sin reencapuchar ni manipular con la mano.","La trazabilidad permite demostrar el destino del residuo y responder ante un incidente con la información completa.","El riesgo no termina en el servicio, porque alcanza al personal de limpieza, al transporte municipal y a la comunidad."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"El color no es el servicio","text":"El color se decide por la clase y el riesgo del residuo, no por el ambiente donde se generó. Si el caso menciona agujas, lancetas o ampollas rotas, la respuesta es recipiente rígido, impermeable y rotulado, nunca una bolsa. El distractor habitual propone bolsa roja para todo lo que parece contaminado o aumentar la frecuencia de recolección sin cambiar la práctica de llenado."}},{"title":"Ciclo municipal y comunitario de los residuos","depth":"core","body":["El ítem pide residuos sólidos y salud comunitaria, no solo residuos de establecimientos de salud. El ciclo municipal incluye generación domiciliaria y comunitaria, segregación, almacenamiento, recolección, transferencia, transporte, tratamiento y disposición final. La quema y el botadero a cielo abierto son prácticas de riesgo que persisten en muchos territorios.","La salud comunitaria se afecta por criaderos de vectores, contaminación del agua y del suelo, exposición de recicladores informales, animales y olores. El municipio es responsable de la gestión y el sector salud de la vigilancia, la educación y la articulación. La NTS 144 regula los residuos de establecimientos de salud; no reemplaza la normativa municipal de residuos sólidos.","La respuesta exige separar en origen, asegurar frecuencia de recolección, formalizar el reciclaje, cerrar botaderos y educar con la comunidad. La participación comunitaria y la vigilancia sanitaria permiten identificar puntos críticos y sostener el cambio."],"bullets":["Generación: domiciliaria, comercial, institucional y de servicios de salud.","Segregación: orgánico, reciclable, no aprovechable y peligroso.","Recolección y transferencia: frecuencia, rutas y puntos críticos.","Disposición final: relleno sanitario; evitar quema y botadero a cielo abierto.","Reciclaje informal: riesgo ocupacional y oportunidad de formalización.","Vigilancia: criaderos, agua, suelo, vectores y exposición humana.","Participación: municipio, comunidad, recicladores y sector salud."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — NTS N.° 144-MINSA/2018/DIGESA, gestión y manejo de residuos sólidos en establecimientos de salud y servicios médicos de apoyo.","Fuente: MINSA — RM N.° 1295-2018-MINSA, aprueba la NTS N.° 144-MINSA/2018/DIGESA.","Fuente: MINSA — RM N.° 250-2022-MINSA, modifica la NTS N.° 144-MINSA/2018/DIGESA.","Fuente: MINSA — RM N.° 901-2024-MINSA, modifica la NTS N.° 144-MINSA/2018/DIGESA.","Fuente: Perú — Decreto Legislativo N.° 1278, Ley de Gestión Integral de Residuos Sólidos, y su reglamento.","Fuente: MINSA — NTS N.° 144-MINSA/2018/DIGESA, gestión y manejo de residuos sólidos en establecimientos de salud y servicios médicos de apoyo, RM N.° 1295-2018/MINSA.","Fuente: Perú — Ley N.° 27972, Ley Orgánica de Municipalidades; competencias municipales en residuos sólidos y salud."]}],"sheet-psi-sp-2-11":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La salud ocupacional identifica, evalúa y controla los riesgos del trabajo para proteger el bienestar físico, mental y social de quien trabaja. Su objeto no es la enfermedad ya instalada sino la relación entre las condiciones de trabajo y la salud, incluida la organización del tiempo, las tareas y el trato.","Los riesgos psicosociales son condiciones de la organización y del entorno laboral: demanda alta, control bajo, apoyo escaso, violencia, jornadas prolongadas y conflicto o ambigüedad de rol. No son rasgos de personalidad ni falta de tolerancia, y por eso no se resuelven pidiendo al trabajador que se adapte.","La intervención se ordena con la jerarquía de controles. Primero se busca eliminar o sustituir el peligro, luego aislar a las personas y cambiar la organización, y al final usar equipo de protección personal. El desgaste profesional requiere medidas organizacionales además del apoyo individual, porque su origen está en la interacción entre demandas y recursos."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","bullets":["El modelo demanda-control explica que la tensión aparece cuando las exigencias son altas y la posibilidad de decidir es baja; la misma carga se tolera mejor con margen de decisión.","La incorporación del apoyo social completa el modelo, porque el respaldo de jefaturas y pares amortigua el efecto de la demanda alta y reduce el aislamiento.","El modelo de desequilibrio esfuerzo-recompensa añade que la falta de reconocimiento, de salario justo o de seguridad en el puesto también desgasta.","La carga alostática describe el costo de una activación sostenida: el organismo mantiene la respuesta de alerta y aparecen alteraciones del sueño, del ánimo y de la salud física.","La justicia organizacional, entendida como trato respetuoso y reglas predecibles, modera el efecto de las demandas sobre el malestar del equipo.","El desgaste profesional se expresa en agotamiento emocional, distancia o cinismo frente al trabajo y sensación de baja eficacia.","La participación de los trabajadores en el diseño de las medidas aumenta su pertinencia, porque conocen el proceso real y detectan efectos no previstos."]},{"title":"Peligros, riesgo y niveles de prevención","depth":"full","body":["El peligro es la fuente con capacidad de causar daño; el riesgo es la probabilidad y la gravedad de que ese daño ocurra en una situación concreta. La distinción importa porque un peligro no se elimina con información y un riesgo no se evalúa sin exposición. En un servicio de salud conviven peligros físicos, químicos, biológicos, ergonómicos y psicosociales, y cada uno admite controles distintos."],"table":{"headers":["Tipo de peligro","Ejemplo en un servicio de salud","Control característico"],"rows":[["Físico","Ruido de equipos, temperatura extrema, radiaciones","Aislamiento, mantenimiento y señalización"],["Químico","Desinfectantes, medicamentos peligrosos, gases anestésicos","Ventilación, manipulación segura y sustitución"],["Biológico","Sangre, fluidos, secreciones y aerosoles","Barreras, higiene de manos y vacunación cuando corresponde"],["Ergonómico","Posturas forzadas, carga física y trabajo frente a pantallas","Diseño del puesto, pausas y ayudas mecánicas"],["Psicosocial","Sobrecarga, turnos, violencia y conflicto de rol","Rediseño de la organización y apoyo de jefaturas"]]}},{"title":"Jerarquía de controles","depth":"full","body":["La jerarquía ordena las medidas de mayor a menor protección y por eso se aplica antes de decidir. Su lógica es directa: lo que actúa sobre la fuente protege a todas las personas expuestas. El equipo de protección personal, en cambio, protege solo a quien lo usa bien y depende de su conducta."],"table":{"headers":["Nivel","Qué implica","Ejemplo de medida"],"rows":[["Eliminación o sustitución","Eliminar el peligro o reemplazarlo por una alternativa menos peligrosa, cuando sea factible.","Rediseñar la tarea o retirar un equipo peligroso."],["Controles de ingeniería","Aislar a las personas del peligro mediante el diseño del ambiente o de los equipos.","Barreras físicas, ventilación o dispositivos seguros."],["Controles administrativos","Cambiar la organización, los flujos, los procedimientos y la capacitación.","Ajustar dotación, horarios, turnos y protocolos."],["Equipo de protección personal","Usar el equipo adecuado, con entrenamiento y ajuste cuando corresponda.","Guantes, mascarilla o protección auditiva."]]}},{"title":"Vigilancia del ambiente y de la salud del trabajador","depth":"core","bullets":["La vigilancia del ambiente laboral mide las condiciones peligrosas; la vigilancia de la salud del trabajador detecta efectos tempranos en las personas.","Los exámenes médicos ocupacionales se realizan según el riesgo del puesto y buscan ubicar a la persona en un trabajo compatible con su estado de salud.","El ausentismo, la rotación y las licencias repetidas son señales agregadas de desgaste que conviene revisar antes de que aparezca el daño declarado.","El reporte de accidentes e incidentes alimenta la prevención, porque un incidente sin lesión revela una falla que puede repetirse con consecuencias mayores.","La información de salud del trabajador es confidencial y se usa para prevenir, no para seleccionar ni sancionar.","La vigilancia se completa cuando el resultado se traduce en medidas y se verifica su efecto en el periodo siguiente."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Identificar los peligros del puesto recorriendo el trabajo real y no solo el procedimiento escrito.","2. Evaluar el riesgo por probabilidad y gravedad, considerando a las personas más expuestas.","3. Priorizar según la jerarquía de controles y descartar primero las medidas que solo actúan sobre el individuo.","4. Diseñar la medida con quienes ejecutan la tarea y definir responsable, plazo y recurso.","5. Implementar y comunicar el cambio, con capacitación cuando la medida lo requiera.","6. Vigilar indicadores de proceso y de efecto, como incidentes, ausentismo y señales de desgaste.","7. Derivar a evaluación y atención individual cuando ya existe daño, sin suspender la intervención organizacional.","8. Revisar la medida, ajustarla según el resultado y dejar registro de lo decidido y de su seguimiento."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de la sierra, una obstetra acumula guardias y turnos dobles porque el servicio tiene personal insuficiente. Refiere insomnio, irritabilidad y sensación de no dar abasto, y evita las reuniones de equipo. La jefatura propone enviarla a un taller de manejo del estrés y pedirle que organice mejor su tiempo. El psicólogo advierte que el problema es de organización: la sobrecarga es crónica, no hay margen para decidir sobre los turnos y el trato de la jefatura es hostil. El equipo acuerda revisar la programación de guardias, redistribuir tareas administrativas y establecer pautas de trato, además de ofrecer apoyo individual y seguimiento."],"bullets":["Lectura del caso: la sobrecarga, la falta de control y el trato hostil son condiciones del servicio y no características de la trabajadora.","Lectura del caso: el taller de estrés puede acompañar, pero no modifica la programación de guardias que sostiene el desgaste.","Lectura del caso: redistribuir tareas y fijar pautas de trato actúan sobre la fuente y son verificables en el tiempo.","Lectura del caso: se descarta el cambio de área como única salida, porque traslada el problema sin corregir la organización."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: responder al desgaste con técnicas de relajación, porque alivia el síntoma y deja intactas la sobrecarga y la falta de control que lo producen.","Distinción: peligro no es riesgo, porque el peligro es la fuente del daño y el riesgo es la probabilidad y gravedad de que ocurra.","Distinción: demanda no es control, porque la demanda mide cuánto se exige y el control mide cuánto puede decidirse sobre el propio trabajo.","Error: confundir el equipo de protección personal con la primera medida, porque protege al individuo y no corrige la fuente ni la organización.","Distinción: burnout no es estrés agudo, porque el desgaste se instala por exposición prolongada y altera la relación con el trabajo.","Error: atribuir el malestar a la personalidad del trabajador, porque oculta el riesgo organizacional y culpabiliza a quien está expuesto.","Distinción: vigilancia del ambiente no es vigilancia de la salud, porque la primera mide condiciones y la segunda efectos en las personas."]},{"title":"Puntos clave","depth":"core","bullets":["El riesgo psicosocial se localiza en la organización, por lo que su corrección exige cambiar tareas, turnos, dotación y trato.","La combinación de demanda alta con control bajo y apoyo escaso es la que más desgasta, y el apoyo amortigua ese efecto.","La jerarquía de controles se aplica de arriba hacia abajo y el equipo de protección personal queda como última barrera.","La vigilancia del ambiente y la de la salud del trabajador son complementarias y responden a preguntas distintas.","El reporte de incidentes sin lesión permite corregir antes de que ocurra el accidente con consecuencias.","La participación de los trabajadores en el diseño de las medidas aumenta su cumplimiento y reduce efectos no previstos."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Organización antes que individuo","text":"Si el enunciado describe sobrecarga, turnos excesivos o trato hostil, la respuesta pertinente actúa sobre la organización del trabajo. Las técnicas de relajación y el equipo de protección personal pueden integrar el plan, pero no reemplazan la corrección de la fuente. El distractor típico propone derivar a la persona o pedirle que se adapte, sin revisar las condiciones del servicio."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: NIOSH — Hierarchy of Controls, jerarquía de controles para el riesgo laboral.","Fuente: OMS — Informe sobre salud ocupacional y riesgos psicosociales en el trabajo.","Fuente: MINSA — Lineamientos de salud ocupacional y vigilancia de riesgos en los servicios de salud."]}],"sheet-psi-sp-2-12":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["El modelo comunitario sitúa la atención lo más cerca posible de la vida cotidiana de la persona, con énfasis en derechos y recuperación. Reúne al primer nivel, a los Centros de Salud Mental Comunitaria, a los hospitales y a los hogares protegidos. Trabaja con la familia y la comunidad en lugar de sustituirlas.","La recuperación no se limita a reducir síntomas: busca autonomía, vínculos, funcionamiento e inclusión, con la alternativa efectiva menos restrictiva. La hospitalización se usa cuando corresponde y se evita la institucionalización prolongada, porque reduce la autonomía y las oportunidades de inclusión.","La derivación traslada la atención y no la responsabilidad: el servicio que deriva conserva la obligación de coordinar y de verificar que la continuidad ocurra. El plan individualizado, el registro compartido y las reuniones de caso sostienen ese vínculo entre niveles."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","bullets":["El modelo de recuperación entiende la salud mental como un proceso personal con conexión, esperanza, identidad, sentido y empoderamiento, y no solo como ausencia de síntomas.","La desinstitucionalización trasladó la atención del hospital al territorio y mostró que la inclusión depende de servicios, vivienda y red social, no solo de la clínica.","Los determinantes sociales explican parte del curso de los trastornos, porque pobreza, violencia, migración y exclusión modifican el riesgo y la posibilidad de recuperarse.","La atención escalonada propone la intensidad mínima suficiente para cada necesidad, con posibilidad de subir o bajar de nivel según la evolución.","La rehabilitación psicosocial actúa sobre habilidades, apoyos y participación, porque el funcionamiento se recupera en escenarios reales y no solo en consulta.","La continuidad del cuidado reduce recaídas y hospitalizaciones, ya que el vínculo sostenido con un equipo conocido pesa más que muchos contactos aislados.","El apoyo entre pares aporta experiencia vivida, reduce el aislamiento y mejora la adherencia cuando se integra con supervisión del equipo tratante."]},{"title":"Dispositivos y niveles de la red","depth":"full","body":["La red se organiza por intensidad y especialización, no por prestigio. El primer nivel resuelve lo frecuente y acompaña. El Centro de Salud Mental Comunitaria atiende lo que requiere equipo interdisciplinario y fortalece al primer nivel. El hospital responde a la crisis y a la complejidad médica. La elección del dispositivo se decide por necesidad clínica, riesgo y apoyos disponibles, y se revisa con la evolución."],"table":{"headers":["Dispositivo","Función principal","Criterio de uso","Límite"],"rows":[["Primer nivel","Detección, consejería, manejo de casos leves y seguimiento cercano","Problema frecuente o en fase estable, con apoyo familiar disponible","No resuelve cuadros complejos ni crisis prolongadas"],["CSMC","Atención ambulatoria especializada, rehabilitación psicosocial y apoyo técnico","Cuadro moderado o severo que requiere equipo interdisciplinario","No reemplaza la hospitalización cuando hay riesgo grave"],["Hospital general","Atención de crisis, comorbilidad médica y ajuste de tratamiento","Riesgo para la vida, descompensación aguda o evaluación especializada","La estancia prolongada favorece la institucionalización"],["Hogar protegido","Alojamiento con apoyo para personas sin soporte habitacional adecuado","Falta de vivienda o de cuidadores, con proyecto de inclusión","No sustituye el tratamiento ni la participación familiar"],["Red comunitaria y familia","Apoyo cotidiano, inclusión, actividades y detección temprana","Siempre, como sostén del plan individualizado","Requiere orientación para no reproducir sobrecarga o exclusión"]]}},{"title":"Red de apoyo y competencias","depth":"full","table":{"headers":["Actor","Función principal","No confundir con"],"rows":[["CEM","Atención especializada frente a violencia.","Nivel de complejidad hospitalaria."],["Policía y justicia","Funciones de denuncia y protección.","Tratamiento clínico especializado."],["DEMUNA y UPE","Protección infantil según su competencia.","Servicio de salud mental."],["OMAPED y CONADIS","Promoción de derechos e inclusión de personas con discapacidad.","Nivel de atención."],["INABIF","Apoyos y asistencia económica según elegibilidad.","Acogimiento residencial automático."]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Recibir la demanda, escuchar el motivo y verificar si existe riesgo para la persona o para terceros.","2. Evaluar la situación con la persona y, cuando corresponda, con la familia o con quienes la cuidan.","3. Identificar los apoyos disponibles: vivienda, red familiar, trabajo, comunidad y servicios de la zona.","4. Elegir la alternativa efectiva menos restrictiva que cubra el riesgo detectado y que sea sostenible.","5. Formular el plan individualizado con objetivos, responsables, plazos y señales de alarma para la familia.","6. Coordinar la referencia con el servicio de destino y asegurar que la persona sea recibida.","7. Mantener el contacto de seguimiento y verificar la adherencia y la continuidad del cuidado.","8. Revisar la decisión cuando cambie el riesgo o la persona lo solicite, dejando registro de lo actuado."]},{"title":"Continuidad y articulación con el primer nivel","depth":"core","bullets":["El Centro de Salud Mental Comunitaria brinda asistencia técnica, supervisión y capacitación a los equipos del primer nivel, además de atender personas.","La asistencia técnica se concreta en reuniones de caso, revisión de situaciones difíciles y criterios comunes de derivación.","La referencia y la contrarreferencia deben llevar información clínica suficiente y una indicación clara de lo que sigue.","El registro compartido evita repetir la historia y reduce el riesgo de que la persona cuente su experiencia desde cero en cada servicio.","La continuidad falla cuando la derivación se usa para cerrar el caso, porque el servicio de origen conserva la coordinación.","La familia y la comunidad participan en el plan con información comprensible y un rol definido que no las sobrecargue."]},{"title":"Orfandad: cuidado y protección coordinados","depth":"core","bullets":["Ante niñas o niños que pierden a sus cuidadores, la primera tarea es valorar quién asegura el cuidado, las necesidades básicas y la seguridad.","Se articula la familia extensa y la comunidad, los servicios de salud mental y los apoyos del INABIF según elegibilidad.","El riesgo de desprotección se comunica a la DEMUNA acreditada y la presunta desprotección a la UPE, conforme a la ruta territorial.","La orfandad no determina por sí sola acogimiento residencial, porque las medidas requieren evaluación competente e interés superior del niño.","La evaluación considera el vínculo previo, la continuidad escolar y la posibilidad de sostener el cuidado en el entorno conocido."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En una ciudad intermedia, un usuario de cuarenta años con diagnóstico de trastorno mental severo deja de asistir al Centro de Salud Mental Comunitaria. Su hermana acude porque lo encuentra desorganizado en el discurso y sin dormir, y pide internamiento inmediato. El psicólogo revisa la historia: la última atención fue hace dos meses y el usuario dejó de acudir cuando cambió su horario de trabajo, no por rechazo al servicio. El equipo valora el riesgo, constata que no hay agresión ni abandono grave del autocuidado y que la hermana puede acompañarlo. Acuerda intensificar la atención ambulatoria, ajustar el tratamiento con evaluación psiquiátrica, programar visitas domiciliarias y dar pautas de alarma a la familia, con revisión en pocos días."],"bullets":["Lectura del caso: la evaluación del riesgo y de los apoyos permitió sostener una alternativa ambulatoria y evitar la restricción innecesaria.","Lectura del caso: la hermana pasa de demandante a parte del plan, con pautas y un rol acotado que reduce su sobrecarga.","Lectura del caso: las visitas domiciliarias recuperan el vínculo con el servicio y detectan barreras que la consulta no muestra.","Lectura del caso: se descarta el internamiento como primera respuesta y también la derivación sin seguimiento, porque ambas interrumpen la continuidad."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: responder a la crisis con separación del entorno por defecto, porque la restricción se justifica solo cuando es la alternativa efectiva disponible y se revisa.","Distinción: comunidad no es institución, porque la primera sostiene la vida cotidiana y la segunda concentra y aísla cuando se prolonga.","Distinción: derivar no es transferir responsabilidad, porque el servicio de origen conserva la coordinación y el seguimiento del caso.","Distinción: recuperación no es curación, porque la primera se refiere a autonomía, vínculos y proyecto de vida, y la segunda a la remisión del cuadro.","Error: confundir hogar protegido con acogimiento residencial automático, porque el hogar protegido es un apoyo habitacional con proyecto de inclusión.","Distinción: rehabilitación psicosocial no es taller recreativo, porque trabaja habilidades y participación con objetivos evaluables.","Error: cerrar el caso al derivar a la DEMUNA o a la UPE, porque cada servicio actúa según su competencia y salud mental mantiene su parte del plan."]},{"title":"Puntos clave","depth":"core","bullets":["La atención se acerca al entorno y usa la restricción mínima necesaria, con revisión periódica de la decisión.","La recuperación incluye autonomía, vínculos, funcionamiento e inclusión, además del alivio de los síntomas.","El Centro de Salud Mental Comunitaria atiende y fortalece al primer nivel con asistencia técnica y supervisión.","La red funciona por competencias, porque cada actor hace su parte y ninguna institución sustituye a otra.","La continuidad del cuidado exige coordinación verificable y no termina con la referencia al otro servicio.","La orfandad exige evaluación y protección coordinada, no una respuesta automática ni un destino único."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Recuperación e inclusión","text":"El eje del modelo es la recuperación con inclusión y no el aislamiento como respuesta principal. Cuando el enunciado propone separar a la persona de su entorno, conviene preguntar si existe una alternativa efectiva menos restrictiva y con qué apoyos. El distractor típico ofrece hospitalización prolongada o derivación sin seguimiento, y confunde la protección con el encierro."}},{"title":"Núcleo del modelo comunitario","depth":"core","body":["El núcleo del modelo comunitario es la atención cercana al entorno, con continuidad, derechos y recuperación. El Centro de Salud Mental Comunitaria (CSMC) atiende a personas con trastornos mentales graves y problemas psicosociales, y a la vez brinda asistencia técnica y supervisión al primer nivel.","La hospitalización es una alternativa cuando la intensidad del riesgo o la complejidad lo exige, no la respuesta por defecto. La recuperación incluye autonomía, vínculos, funcionamiento e inclusión; no se limita a reducir síntomas. La derivación no elimina la responsabilidad de coordinación y seguimiento.","La orfandad y la protección infantil son un componente de red, pero no definen el modelo comunitario. Deben ubicarse como un caso de articulación con DEMUNA, UPE, INABIF y otros servicios, no como el eje de la ficha."],"bullets":["CSMC: atención especializada cercana, continuidad y apoyo al primer nivel.","Primer nivel: detección, atención inicial, seguimiento y coordinación.","Hospital: crisis o complejidad; evitar institucionalización prolongada.","Hogares protegidos y apoyos comunitarios: vida cotidiana e inclusión.","Recuperación: síntomas, autonomía, vínculos y funcionamiento.","Derechos: consentimiento, confidencialidad y alternativa menos restrictiva."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — NTS 138-MINSA/2017/DGIESP, RM 574-2017/MINSA, funciones del Centro de Salud Mental Comunitaria.","Fuente: MIMP — Lineamientos de coordinación CEM-UPE-DEMUNA, RM 237-2024-MIMP.","Fuente: Congreso de la República — Ley 29973, Ley General de la Persona con Discapacidad, artículos 70-73.","Fuente: MINSA — NTS 138-MINSA/2017/DGIESP, funciones del Centro de Salud Mental Comunitaria, RM N.° 574-2017/MINSA.","Fuente: Perú — Ley N.° 30947, Ley de Salud Mental, 22/05/2019; publicada el 23/05/2019.","Fuente: MINSA — DS N.° 007-2020-SA, Reglamento de la Ley N.° 30947, 05/03/2020."]}],"sheet-psi-sp-2-13":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["El acceso se entiende como la relación entre la necesidad de atención y el uso efectivo del servicio. No basta con que el establecimiento exista ni con que la persona esté afiliada: el acceso se concreta cuando la prestación se obtiene, en el momento oportuno y con capacidad de continuar el cuidado.","Las cinco dimensiones ordenan el análisis: disponibilidad, accesibilidad geográfica y económica, aceptabilidad, calidad y protección financiera. La disponibilidad responde si el servicio existe; la accesibilidad, si puede alcanzarse; la aceptabilidad, si resulta pertinente y respetuoso; la calidad, si resuelve con seguridad; la protección financiera, si el gasto no empobrece. Una misma persona puede enfrentar varias barreras a la vez, y la respuesta debe dirigirse a la que interrumpe la ruta."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["El acceso no depende de una sola decisión. Se forma en la interacción entre la necesidad de la persona, los recursos del hogar, la organización del servicio y las condiciones del territorio. Por eso las intervenciones que actúan sobre un solo factor suelen desplazar la barrera en lugar de eliminarla."],"bullets":["El modelo de Andersen agrupa los factores predisponentes, facilitadores y de necesidad; intervenir solo en la oferta deja intactos los factores que desalientan la demanda.","El modelo de Tanahashi distingue cobertura disponible, accesible, aceptable, de contacto y efectiva; cada nivel pierde población y explica por qué la cobertura nominal no se traduce en uso.","Las barreras económicas operan por costo directo, transporte, días de trabajo perdidos y gasto de bolsillo; su efecto es mayor en hogares con ingresos variables.","Las barreras culturales y lingüísticas reducen la comprensión y la confianza, y producen abandono cuando la persona anticipa que no será comprendida.","El estigma agrega un costo social: revelar un problema de salud mental puede exponer a discriminación laboral o familiar y retrasar la búsqueda de ayuda.","La pérdida de personas entre niveles ocurre por referencias sin contrarreferencia, citas distantes y falta de contacto; la navegación reduce esa pérdida.","La adherencia depende del acceso sostenido, porque un tratamiento interrumpido por barreras se lee como incumplimiento cuando en realidad es falla del sistema."]},{"title":"Clasificación y criterios de aplicación","depth":"full","body":["La tabla ordena cada dimensión con una pregunta de exploración y un indicador sencillo de seguimiento. El criterio de aplicación consiste en identificar la dimensión que explica el abandono en una ruta concreta, en lugar de etiquetar a la persona."],"table":{"headers":["Dimensión","Pregunta de exploración","Indicador de seguimiento","Ejemplo de barrera"],"rows":[["Disponibilidad","Existe el servicio y el recurso necesario","Oferta vigente y horario real","Ausencia de psicólogo o de medicamento"],["Accesibilidad geográfica","Puede llegarse en un tiempo razonable","Tiempo y costo de traslado","Trocha interrumpida por lluvias"],["Accesibilidad económica","Puede asumirse el gasto total","Gasto de bolsillo y días perdidos","Pasajes y pérdida del jornal"],["Aceptabilidad","El trato y el idioma son pertinentes","Satisfacción y comprensión del mensaje","Atención solo en español"],["Calidad","Resuelve con seguridad y oportunidad","Oportunidad de cita y resolución","Espera prolongada sin seguimiento"]]}},{"title":"Del aseguramiento al acceso efectivo","depth":"core","body":["El aseguramiento universal en salud es el proceso orientado a que la población disponga de un seguro que permita acceder a prestaciones. La cobertura universal se refiere al acceso a servicios necesarios y de calidad sin dificultades financieras. La APS es un enfoque de toda la sociedad que integra servicios, acción multisectorial y participación, y la atención integral responde a las necesidades de la persona a lo largo del curso de vida.","Estos conceptos se relacionan, pero no son equivalentes: el seguro es un instrumento, la cobertura es un resultado y la APS es un modo de organizar el sistema. Tener seguro reduce el costo directo y, aun así, pueden persistir distancia, horarios, idioma o estigma, por lo que la afiliación no demuestra acceso efectivo."]},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Describir la ruta real que sigue la persona, desde la aparición del problema hasta la atención resuelta, con sus pasos, tiempos y costos.","2. Identificar en qué paso se produce el abandono o el retraso, usando registros de citas, referencias y contactos fallidos.","3. Clasificar la barrera predominante según la dimensión afectada y distinguirla de las barreras secundarias que la acompañan.","4. Consultar a quienes no llegaron, mediante llamadas o visitas domiciliarias, porque los registros de atendidos no muestran esa ausencia.","5. Priorizar la barrera modificable con los recursos disponibles y acordar un responsable y un plazo para la respuesta.","6. Ajustar horarios, idioma, canal de información o acompañamiento según la población, y registrar el cambio en la ficha familiar o en el plan de mejora.","7. Verificar el efecto con indicadores de uso, oportunidad y continuidad, y derivar a otro nivel solo cuando la necesidad supere la capacidad resuelta.","8. Escalar la barrera estructural, como falta de personal o de vías, a la jefatura del establecimiento y a la red, dejando constancia."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro poblado de la selva alta, las lluvias de febrero cortaron la trocha que une dos caseríos con el puesto de salud. Una gestante afiliada al SIS, que acudía a sus controles, dejó de asistir durante tres semanas y el personal registró la inasistencia como abandono. Al revisar la ruta se encontró que el traslado en mototaxi cuesta el jornal de un día, que la atención coincide con la jornada agrícola y que la consejería se ofrece solo en español, aunque varias usuarias hablan quechua. El puesto no tenía datos de cuántas personas dejaron de llegar. La obstetra y la psicóloga acordaron una visita domiciliaria, una coordinación con el agente comunitario para el traslado y una consejería con apoyo de intérprete."],"bullets":["Lectura del caso: la barrera principal fue geográfica y económica, agravada por el horario y el idioma; el registro de inasistencia no era diagnóstico de desinterés.","Lectura del caso: la alternativa descartada fue derivar a otro establecimiento sin verificar el traslado, porque la distancia habría reproducido la misma barrera.","Lectura del caso: se evitó interpretar el abandono como incumplimiento individual y se actuó sobre la ruta completa, con seguimiento.","Lectura del caso: el agente comunitario aportó información y transporte, sin sustituir la responsabilidad del establecimiento."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: confundir cobertura con acceso. La afiliación habilita prestaciones, pero no garantiza que la persona llegue, sea atendida y continúe.","Error: atribuir el abandono a falta de interés. Sin explorar distancia, horario, costo y trato, el abandono se explica por el sistema y no por la persona.","Distinción: disponibilidad no es accesibilidad porque el servicio puede existir y, aun así, quedar fuera del alcance real.","Distinción: aceptabilidad no es calidad porque un trato amable no compensa una atención que no resuelve.","Distinción: aseguramiento no es cobertura universal porque el seguro es un medio y la cobertura efectiva es el resultado.","Distinción: equidad no es igualdad porque la misma oferta produce resultados distintos cuando las condiciones de partida difieren.","Error: medir solo a los atendidos. Quienes no llegaron son la evidencia de la barrera y suelen quedar fuera de las estadísticas."]},{"title":"Barreras, equidad y adherencia","depth":"core","body":["Las barreras no se distribuyen al azar: se concentran en población rural, amazónica, con discapacidad, migrante y con menor ingreso. Esa concentración convierte una dificultad operativa en una inequidad, porque el mismo esfuerzo institucional rinde menos donde las condiciones de partida son más adversas.","La adherencia se sostiene en la continuidad. Cuando el tratamiento exige viajes repetidos, horarios incompatibles o trámites que la persona no comprende, la interrupción es previsible. Un sistema que solo registra la inasistencia traslada la responsabilidad a quien enfrenta la barrera; un sistema que ajusta la ruta la reduce."]},{"title":"Puntos clave","depth":"core","bullets":["El acceso se demuestra con uso efectivo y continuidad, porque la existencia del servicio y la afiliación son solo condiciones previas.","Cada dimensión tiene un indicador propio, y confundirlas lleva a respuestas equivocadas: más personal no resuelve una trocha cortada.","Las barreras se acumulan en los mismos grupos, por lo que reducirlas exige priorizar a quienes enfrentan más desventajas.","Medir abandono y oportunidad revela lo que la cobertura promedio oculta y orienta la mejora donde se pierde la ruta.","La navegación y la contrarreferencia sostienen la continuidad y evitan que la persona quede sin respuesta entre niveles.","La adherencia es un resultado del sistema tanto como una conducta individual, y así debe interpretarse antes de juzgar."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Dimensión antes que etiqueta","text":"Cuando el servicio existe pero no puede alcanzarse, la respuesta es accesibilidad; si el problema es el trato o el idioma, es aceptabilidad; si es la demora o el error, es calidad. La afiliación al seguro es un distractor frecuente, porque habilita el derecho pero no garantiza su ejercicio."}},{"title":"Acceso efectivo y APS","depth":"core","body":["El acceso efectivo exige disponibilidad, accesibilidad, aceptabilidad y calidad. No basta con que el servicio exista o con que la persona tenga seguro: debe poder llegar, ser atendida, entender y continuar el cuidado.","La APS organiza la puerta de entrada y la navegación dentro de la red. Las barreras geográficas, económicas, culturales, organizativas y de trato interrumpen la ruta antes o después del contacto. Medir abandono y oportunidad revela barreras que el promedio oculta."],"bullets":["Disponibilidad: el servicio existe y tiene recursos.","Accesibilidad: puede alcanzarse sin barreras evitables.","Aceptabilidad: es pertinente y respetuoso.","Calidad: resuelve con seguridad y continuidad.","Protección financiera: no empobrece a la persona."]},{"title":"Cascada de acceso y pérdida entre niveles","depth":"full","body":["El acceso se analiza como una cascada: cada nivel se calcula como proporción del anterior y la diferencia revela la barrera que interrumpe la ruta. No basta con medir la cobertura nominal; hay que medir quién llega, quién es atendido, quién comprende y quién continúa."],"table":{"headers":["Nivel","Numerador / denominador","Pérdida que revela"],"rows":[["Disponible","Población con servicio y horario vigente / población asignada","Cobertura nominal"],["Accesible","Puede llegar en tiempo y costo razonables / disponibles","Barrera geográfica y económica"],["Aceptable","Acepta y comprende la oferta / accesibles","Idioma, trato y estigma"],["Contacto","Usa al menos una vez / aceptables","Primera barrera de uso"],["Efectivo","Completa el cuidado / contacto","Continuidad y calidad"]]}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: Congreso de la República — Ley 29344, Ley Marco de Aseguramiento Universal en Salud.","Fuente: Congreso de la República — Incorporación al SIS de peruanos residentes en el exterior, modificación del artículo 3 de la Ley 29344.","Fuente: OMS — Universal health coverage: questions and answers.","Fuente: OMS — Primary health care, servicios integrados, acción multisectorial y participación.","Fuente: MINSA — Modelo de Cuidado Integral de Salud por Curso de Vida, RM N.° 030-2020/MINSA, 27/01/2020; enfoque de curso de vida, componentes y organización territorial.","Fuente: OMS — Informe mundial 2008: cobertura universal y acceso efectivo.","Fuente: Tanahashi T. — Health service coverage and its evaluation. Bull World Health Organ. 1978;56(2):295-303."]}],"sheet-psi-sp-3-1":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La promoción de la salud se define por su propósito: que las personas y las comunidades ganen control sobre aquello que produce salud. Por eso su unidad de trabajo no es la enfermedad, sino la vida cotidiana: la vivienda, la escuela, el barrio, el trabajo y las decisiones públicas que moldean esas condiciones.","Su estrategia es la acción sobre determinantes, con participación de la población y articulación entre sectores. La educación para la salud es un componente necesario, pero insuficiente: sin cambios en las condiciones, el mensaje compite en desventaja con el entorno."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La promoción no se explica por una sola teoría, sino por la convergencia de varias. Todas coinciden en que la salud se produce fuera del establecimiento y que la intervención debe actuar sobre el contexto y sobre la capacidad de decidir."],"bullets":["La Carta de Ottawa sostiene que la salud se crea en la vida diaria y propone cinco campos de acción que se refuerzan entre sí.","El modelo de determinantes sociales explica por qué el gradiente de salud sigue al gradiente social: educación, ingreso y territorio condicionan la exposición y la respuesta.","El modelo ecológico ubica a la persona en niveles interrelacionados, de modo que una intervención en un solo nivel encuentra límites frente a los demás.","El empoderamiento opera por dos vías: aumenta la capacidad de decidir y mejora la exigibilidad de derechos frente a los servicios.","La intersectorialidad funciona cuando existen objetivos compartidos, recursos asignados y responsabilidades explícitas; sin ellos, la coordinación queda en declaración.","La participación sostenida requiere información comprensible, reglas claras y respuesta visible a las demandas, porque la convocatoria sin retorno desgasta la confianza.","La abogacía cambia el marco de decisión: instala el problema en la agenda y hace visible el costo de no intervenir.","Las alianzas amplían la capacidad de respuesta al sumar actores y recursos, y se sostienen cuando el beneficio es visible para todas las partes."]},{"title":"Los cinco campos de acción","depth":"full","body":["Los cinco campos de Ottawa no son actividades alternativas, sino un conjunto que se potencia. La tabla muestra qué transforma cada uno y un ejemplo de aplicación en el primer nivel de atención.","Ottawa distingue tres estrategias: abogar por la salud, mediar entre intereses contrapuestos y habilitar a personas y comunidades para aumentar su control sobre la salud. La línea de promoción va de Ottawa a Shanghái (2016); Astaná (2018) pertenece a la línea de APS y reafirma la APS para la cobertura universal, no es un hito de promoción."],"table":{"headers":["Campo","Qué transforma","Ejemplo en territorio"],"rows":[["Políticas saludables","Normas y decisiones públicas","Ordenanza municipal sobre entornos libres de humo"],["Entornos favorables","Condiciones físicas y sociales","Escuela con agua segura y patios protegidos"],["Acción comunitaria","Participación y poder colectivo","Comité de salud que prioriza y ejecuta"],["Habilidades personales","Capacidades para decidir y cuidarse","Talleres de habilidades para la vida"],["Reorientación de servicios","Organización hacia prevención y comunidad","Atención extramural y consejería domiciliaria"]]}},{"title":"Ejes temáticos, escenarios y enfoques","depth":"full","body":["El modelo de abordaje de promoción de la salud del MINSA, difundido en 2006, organiza el trabajo en tres categorías. Los ejes temáticos son contenidos priorizados: alimentación y nutrición, higiene y ambiente, actividad física, salud sexual y reproductiva, habilidades para la vida, salud mental, buen trato y cultura de paz, y seguridad vial.","Los escenarios son los espacios de intervención: vivienda, escuela, municipio y centro laboral. Los enfoques transversales son derechos en salud, equidad de género e interculturalidad. Estas categorías traducen Ottawa a prioridades y lugares, pero no lo reemplazan."],"table":{"headers":["Categoría","Función","Ejemplo"],"rows":[["Eje temático","Define el contenido priorizado","Salud mental, buen trato y cultura de paz"],["Escenario","Define el espacio de intervención","Municipio o centro laboral"],["Enfoque transversal","Atraviesa el diseño y la ejecución","Interculturalidad en materiales y consejería"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Realizar un diagnóstico participativo con la comunidad y los servicios, usando la ficha familiar y los registros locales para identificar problemas priorizados.","2. Analizar los determinantes del problema y distinguir los modificables desde el sector salud de los que requieren otros sectores.","3. Priorizar con la población según magnitud, gravedad, posibilidad de respuesta y acuerdo de los actores involucrados.","4. Definir el cambio esperado en condiciones y en capacidades, con indicadores verificables antes de elegir las actividades.","5. Seleccionar los campos de Ottawa que correspondan y articularlos con el eje temático y el escenario definidos.","6. Conformar o fortalecer el comité local, con reglas claras, responsables y rendición de cuentas ante la comunidad.","7. Ejecutar acciones educativas, normativas y de entorno de manera simultánea, y registrar avances y obstáculos.","8. Evaluar cambios en condiciones, participación y capacidades, y ajustar el plan con la comunidad antes de cerrar el ciclo."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro poblado de la sierra sur, el puesto de salud detecta anemia y parasitosis frecuentes en niñas y niños de una escuela. La respuesta inicial fue una charla anual sobre alimentación. El comité local observó que la escuela no tenía agua tratada, que el recreo se realizaba junto a un desagüe y que las familias compraban agua de cisterna. Con la municipalidad, la dirección escolar y el puesto de salud se acordó instalar un reservorio, mejorar el almacenamiento de agua en las viviendas y trabajar habilidades para la vida con docentes. La consejería se ajustó al idioma local y se incorporó a la visita domiciliaria."],"bullets":["Lectura del caso: la charla no modificaba las condiciones que producían el problema, por lo que su efecto era limitado aun con buena asistencia.","Lectura del caso: la alternativa descartada fue repetir la charla con más frecuencia, porque aumentaba la información sin cambiar agua, saneamiento ni prácticas posibles.","Lectura del caso: el acuerdo con municipalidad y escuela convirtió un problema sanitario en una respuesta intersectorial con responsabilidades explícitas.","Lectura del caso: el comité local no fue convocado como público, sino como actor que prioriza, ejecuta y vigila."]},{"title":"Promoción y prevención: frontera y articulación","depth":"full","body":["La frontera entre promoción y prevención es analítica, no organizativa: ambas se necesitan. La promoción crea las condiciones para que la prevención sea posible, y la prevención protege a grupos que ya enfrentan un riesgo identificable."],"table":{"headers":["Criterio","Promoción","Prevención"],"rows":[["Objeto","Condiciones y capacidades","Daño específico"],["Población","Comunidad y entorno","Grupos o personas en riesgo"],["Momento","Antes de que el problema se configure","Antes, durante o después de la exposición"],["Resultado","Mayor control y equidad","Menor incidencia o menor secuela"]]}},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: reducir la promoción a charlas. La charla informa, pero no altera precios, horarios, normas ni entornos que sostienen el problema.","Error: responsabilizar a la persona de cambiar sin modificar su contexto. Esa lectura convierte una falla de condiciones en falla individual.","Distinción: promoción no es prevención porque la primera actúa sobre condiciones y poder, y la segunda sobre un daño identificable.","Distinción: multisectorial no es intersectorial porque la primera suma participantes y la segunda comparte objetivos, recursos y responsabilidades.","Distinción: eje temático no es campo de Ottawa porque el eje define el contenido y el campo define el tipo de transformación.","Distinción: participación no es asistencia a una actividad porque participar implica decidir y corresponsabilizarse.","Error: confundir educación para la salud con promoción. La educación desarrolla habilidades; la promoción cambia además las condiciones."]},{"title":"Puntos clave","depth":"core","bullets":["La promoción se juzga por cambios en condiciones y capacidades, porque sin ellos la información compite en desventaja con el entorno.","Los cinco campos se refuerzan: una política sin entornos pierde efecto y una acción comunitaria sin servicios se agota.","Los ejes, escenarios y enfoques peruanos operan como traducción territorial de Ottawa, no como sustituto.","La participación con poder de decisión sostiene los resultados, mientras la convocatoria simbólica los desgasta.","La intersectorialidad exige recursos y responsabilidades compartidas; sin ellos queda en declaración.","El enfoque de derechos e interculturalidad cambia el diseño: la comunidad es sujeto de decisión, no destinataria."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"Promoción no es prevención","text":"Si la intervención transforma condiciones, normas o capacidad colectiva, corresponde a promoción; si busca evitar un daño concreto en un grupo, corresponde a prevención. El distractor habitual presenta una charla como acción de promoción, aunque no modifique ninguna condición."}},{"title":"Ottawa, Yakarta, Astaná y APS","depth":"full","body":["La promoción de la salud se institucionaliza con la Carta de Ottawa (1986), que propone cinco campos de acción: políticas públicas saludables, ambientes favorables, acción comunitaria, aptitudes personales y reorientación de los servicios. La Declaración de Yakarta (1997) actualizó las prioridades para el siglo XXI y Astaná (2018) reafirmó la APS como base de la cobertura universal.","La promoción no es prevención. La prevención actúa sobre riesgos y daños específicos; la promoción actúa sobre las condiciones que producen salud y sobre la capacidad de las personas y comunidades para decidir. En APS, ambas se articulan con la acción intersectorial y la participación."],"table":{"headers":["Hito","Año","Aporte","No confundir"],"rows":[["Alma-Ata","1978","APS como estrategia para Salud para Todos","No es una declaración de promoción"],["Ottawa","1986","Cinco campos de acción de promoción","No es lo mismo que prevención"],["Yakarta","1997","Prioridades de promoción para el siglo XXI","No reemplaza a Ottawa"],["Agenda 2030","2015","17 ODS y 169 metas; ODS 3","No es un tratado de APS"],["Astaná","2018","APS como base de la cobertura universal","Hito de APS, no de promoción"]]}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, 2006; ejes temáticos, escenarios y enfoques transversales.","Fuente: OMS — Carta de Ottawa para la promoción de la salud, 1986, principios y cinco campos de acción.","Fuente: OMS — Primary health care; servicios integrados, acción multisectorial y participación.","Fuente: OMS — Carta de Ottawa, 21/11/1986; cinco campos de acción para la promoción de la salud.","Fuente: OMS — Declaración de Yakarta, 21-25/07/1997; prioridades de promoción para el siglo XXI.","Fuente: OMS/UNICEF — Declaración de Astaná, 25-26/10/2018; APS como base de la cobertura universal.","Fuente: OMS — Declaración de Alma-Ata, 12/09/1978; APS como asistencia sanitaria esencial y estrategia para “Salud para Todos”.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017."]}],"sheet-psi-sp-3-2":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La información, educación y comunicación se organiza como un proceso, no como una suma de piezas. Primero se define qué se espera que la audiencia comprenda o haga; luego se elige el mensaje, el canal y la voz que lo sostiene.","El resultado buscado es la capacidad de decidir y actuar. Un mensaje puede ser claro y, aun así, no producir cambio si la persona no confía en la fuente, no comprende el código o no tiene condiciones para seguir la recomendación."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La comunicación en salud no opera por transmisión directa de datos. Entre el mensaje y la conducta median creencias, confianza, emociones, normas del grupo y posibilidades reales de acción."],"bullets":["El modelo de creencias de salud explica que la acción depende de la percepción de amenaza y de la evaluación de beneficios y barreras; un mensaje que solo asusta no modifica la conducta.","La alfabetización en salud media entre recibir información y usarla: sin comprensión, la persona no puede convertir el mensaje en decisión.","El procesamiento de la información combina una vía rápida e intuitiva con una vía analítica; los mensajes breves y concretos funcionan mejor en contextos de cansancio o emergencia.","La confianza en la fuente pesa más que el volumen de datos: cuando la credibilidad se deteriora, la misma información se interpreta como manipulación.","Los rumores no se corrigen solo con desmentidos, porque su fuerza está en la preocupación que expresan y en la identidad del grupo que los comparte.","La comunicación de riesgo requiere retroalimentación: preguntar qué se entendió permite ajustar el mensaje y detectar efectos no previstos.","La evaluación del cambio exige medir comprensión, intención y acción, además del alcance, porque la exposición no equivale a aprendizaje."]},{"title":"Información, educación y comunicación","depth":"full","body":["Los tres componentes se complementan y tienen límites propios. La tabla permite distinguirlos cuando se diseña una intervención o se lee un caso de examen.","La IEC no cambia conducta solo con información: incorpora mercadeo social y técnicas de aprendizaje social, diferenciadas por escenario. La consejería, la sesión educativa y la comunicación masiva tienen alcances distintos; ninguna sustituye el acceso, el apoyo social ni la modificación del entorno."],"table":{"headers":["Componente","Propósito","Ejemplo","Límite"],"rows":[["Información","Dar a conocer datos verificados","Aviso sobre horarios y puntos de vacunación","No garantiza comprensión ni acción"],["Educación","Desarrollar habilidades y criterio","Taller de habilidades para la vida","Requiere tiempo y participación"],["Comunicación","Construir sentido y confianza","Diálogo con la comunidad y vocería","No sustituye servicios disponibles"]]}},{"title":"Procedimiento y criterios de decisión","depth":"full","bullets":["1. Definir el problema y el cambio esperado en comprensión, confianza o conducta antes de elegir el canal.","2. Segmentar la audiencia por lengua, edad, creencias, territorio y acceso a medios.","3. Formular un mensaje concreto por objetivo, con lenguaje claro y sin tecnicismos innecesarios.","4. Elegir el canal según el hábito de la audiencia y verificar que el mensaje pueda circular en ese formato.","5. Identificar una vocería creíble y preparar respuestas para las preguntas previsibles.","6. Pretestear materiales con representantes de la audiencia y ajustar lenguaje, imágenes y ejemplos.","7. Difundir con espacio para preguntas y registrar dudas, rumores y barreras mencionadas.","8. Evaluar comprensión, confianza y acción, y comparar con quienes no fueron alcanzados."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Durante una campaña de vacunación escolar en un distrito de la costa, circula por redes sociales la versión de que la vacuna causa una enfermedad grave. La asistencia cae y algunas familias exigen firmar una negativa. El equipo había respondido con un comunicado técnico extenso, sin vocería local ni espacio para preguntas. La psicóloga propuso reunirse con madres y padres en la escuela, escuchar sus preocupaciones sin interrumpir, explicar qué se sabía y qué se estaba investigando, y responder con una pediatra y una dirigente reconocida por el barrio. El equipo acordó no suspender la campaña y sostener una segunda reunión en el mercado, con material breve y traducido a lenguaje sencillo. También se registraron las dudas frecuentes para ajustar el siguiente mensaje y se dejó un canal de consulta por teléfono."],"bullets":["Lectura del caso: el rumor expresaba desconfianza y miedo, no simple falta de datos, por lo que un comunicado más extenso no habría cambiado la decisión.","Lectura del caso: la alternativa descartada fue desmentir con lenguaje técnico y sin diálogo, porque refuerza la distancia entre la institución y las familias.","Lectura del caso: la vocería local y el espacio de preguntas permitieron verificar comprensión y corregir malentendidos sin descalificar a nadie.","Lectura del caso: se evitó prometer certeza absoluta; se explicó el estado del conocimiento y el criterio de seguridad aplicado."]},{"title":"Comunicación de riesgo y rumores","depth":"full","body":["La comunicación de riesgo se distingue por explicitar la incertidumbre y sostener la confianza mientras la evidencia cambia. Su tarea no es tranquilizar a cualquier costo, sino permitir decisiones informadas."],"table":{"headers":["Situación","Respuesta pertinente","Riesgo de la alternativa"],"rows":[["Rumor instalado","Escuchar la preocupación y responder con evidencia y vocería creíble","Desmentir sin diálogo y aumentar la desconfianza"],["Información incompleta","Explicar qué se sabe, qué falta y qué se está haciendo","Prometer certeza y perder credibilidad al cambiar"],["Baja comprensión","Simplificar el mensaje y verificar lo entendido","Aumentar el volumen de mensajes sin ajustar el lenguaje"]]}},{"title":"Límites de informar","depth":"core","body":["Informar más no corrige una barrera de acceso: si el servicio no está disponible, si el horario es incompatible o si el traslado es costoso, el mensaje claro no produce uso. La IEC puede mejorar la demanda y la comprensión, pero no sustituye la respuesta del sistema.","También existen límites éticos: la comunicación no debe prometer resultados inciertos, estigmatizar a un grupo ni exponer información identificable. El mensaje debe permitir la decisión sin trasladar a la persona toda la responsabilidad del cambio."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: medir éxito por cantidad de materiales distribuidos. La distribución prueba emisión, no comprensión ni uso.","Error: usar un solo mensaje para toda la población. Sin segmentación, el mensaje llega en un código que parte de la audiencia no comparte.","Distinción: información no es educación porque la primera entrega datos y la segunda desarrolla criterio y habilidad.","Distinción: educación no es comunicación porque la comunicación construye sentido en diálogo con la audiencia.","Distinción: comunicación de riesgo no es propaganda porque reconoce la incertidumbre en lugar de ocultarla.","Distinción: rumor no es mentira deliberada porque suele nacer de una preocupación real y circula sin verificación.","Error: desmentir sin escuchar. Sin comprender la preocupación, el desmentido se percibe como descalificación."]},{"title":"Puntos clave","depth":"core","bullets":["El objetivo de la IEC es comprensión y acción, porque el mensaje emitido no demuestra aprendizaje.","La segmentación cambia el diseño y el canal, ya que la misma información no circula igual en todos los grupos.","El pretesteo detecta malentendidos antes de la difusión y reduce el costo de corregir después.","La comunicación de riesgo sostiene la confianza al explicitar la incertidumbre, en lugar de prometer certeza.","Los rumores se abordan con escucha y evidencia, porque la descalificación refuerza la desconfianza.","La IEC no compensa barreras del servicio, por lo que su evaluación debe incluir la posibilidad real de actuar."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"IEC no es difusión","text":"Si la acción planifica mensajes y experiencias educativas según audiencia, objetivo y contexto, corresponde a IEC; si además explica lo que se sabe y lo que aún es incierto, se trata de comunicación de riesgo. El distractor típico equipara IEC con emitir comunicados o repartir material."}},{"title":"IEC y APS","depth":"core","body":["La información, educación y comunicación en APS no busca solo transmitir mensajes: busca que las personas comprendan, decidan y puedan actuar. La alfabetización en salud, la segmentación de audiencias y la comunicación de riesgo son herramientas para reducir barreras, no para culpar a la persona.","La IEC se articula con la participación comunitaria y con los servicios. Un mensaje sin acceso, sin consejería y sin seguimiento no cambia el comportamiento; una comunicación que ignora la cultura y el contexto puede aumentar la desconfianza."],"bullets":["Definir audiencia, objetivo y comportamiento esperado.","Usar lenguaje claro, pertinente y culturalmente aceptable.","Verificar comprensión y no solo exposición al mensaje.","Articular información con acceso, consejería y seguimiento.","Evaluar cambios en conocimiento, decisión y práctica."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: MINSA — Modelo de abordaje de promoción de la salud en el Perú, 2006; educación para la salud y comunicación.","Fuente: OMS — Carta de Ottawa para la promoción de la salud, 1986, principios y campos de acción.","Fuente: OMS — Primary health care; participación y acción multisectorial.","Fuente: MINSA — Lineamientos de Política de Promoción de la Salud, RM N.° 366-2017/MINSA, 19/05/2017; publicada el 20/05/2017.","Fuente: OMS — Carta de Ottawa, 21/11/1986; cinco campos de acción para la promoción de la salud."]}],"sheet-psi-sp-3-3":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La bioseguridad protege a la persona atendida, al personal y a la comunidad frente a riesgos que circulan en el ambiente de atención. No es un conjunto de rutinas fijas, sino un criterio: evaluar la tarea, identificar la vía de exposición y aplicar la medida proporcional.","El punto de partida es reconocer que toda persona puede portar un agente infeccioso sin que el diagnóstico lo revele. Esa incertidumbre justifica aplicar precauciones estándar de manera universal y sumar precauciones adicionales cuando el mecanismo de transmisión lo exige."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La bioseguridad se organiza sobre dos ideas: la transmisión sigue una cadena y la protección se construye por capas. Interrumpir un eslabón reduce el riesgo, pero ninguno lo elimina por completo."],"bullets":["La cadena de infección se interrumpe en cualquier eslabón; por eso la higiene de manos, la barrera y el manejo de residuos actúan en momentos distintos.","Las precauciones estándar parten de que toda persona puede transmitir un agente, de modo que no se espera un diagnóstico para protegerse.","El riesgo de transmisión crece con la profundidad del contacto, el volumen de fluido y la presencia de piel no íntegra o mucosa expuesta.","La higiene de manos es la medida de mayor alcance porque interrumpe la transmisión por contacto en ambos sentidos.","La ropa, el calzado y los objetos personales pueden actuar como vehículo cuando no se separan las áreas limpias de las sucias.","La percepción de riesgo suele subestimar tareas breves, como acomodar a una persona o recoger un objeto caído, donde ocurre buena parte de las exposiciones.","La notificación del incidente sostiene la vigilancia y permite identificar fallas del procedimiento, no solo atender a la persona afectada."]},{"title":"Clasificación de riesgos y medidas de control","depth":"full","body":["La evaluación del riesgo antecede a la elección de la medida. La tabla ordena los tipos de riesgo, su control básico y la forma de verificar que la medida se sostiene en el tiempo."],"table":{"headers":["Riesgo","Ejemplo en la atención","Medida de control","Verificación"],"rows":[["Biológico","Sangre o fluidos durante la entrevista","Higiene de manos y barreras adecuadas","Insumos disponibles y adhesión observada"],["Químico","Sustancias de limpieza o desinfección","Manipulación indicada y protección pertinente","Etiquetado y ventilación"],["Físico","Cortes, pinchazos o salpicaduras","Dispositivos seguros y protección ocular","Recipientes rígidos y descarte correcto"],["Ergonómico","Posturas y esfuerzos al movilizar","Organización de la tarea y apoyo","Pausas y ayuda disponible"]]}},{"title":"Precauciones estándar y uso de barreras","depth":"full","bullets":["Aplicar higiene de manos antes y después del contacto, después de fluidos y al retirar el equipo de protección.","Usar guantes cuando se prevea contacto con sangre, fluidos, mucosas o piel no íntegra, y retirarlos sin tocar la cara externa.","Proteger ojos y cara cuando exista probabilidad de salpicadura, y cubrir nariz y boca según la tarea y el mecanismo de transmisión.","No reencapsular agujas ni manipularlas; descartarlas de inmediato en recipiente rígido y resistente.","Separar áreas limpias de sucias y retirar el equipo de protección antes de salir del área de atención.","Limpiar, desinfectar y esterilizar según el uso del objeto, sin sustituir un proceso por otro.","Aplicar precauciones adicionales según el mecanismo de transmisión, sin relajar las precauciones estándar."]},{"title":"Procedimiento ante una exposición ocupacional","depth":"full","bullets":["1. Interrumpir la tarea y verificar la seguridad de la persona atendida antes de retirarse.","2. Lavar la piel con agua y jabón; irrigar mucosas con agua o solución fisiológica según disponibilidad, sin frotar.","3. Comunicar el accidente de inmediato a la jefatura o al responsable del turno, sin esperar el final de la jornada.","4. Acudir a evaluación inmediata del riesgo, considerando vía, profundidad, volumen y características del material.","5. Recibir la indicación de profilaxis y el esquema de seguimiento definido por el servicio responsable.","6. Registrar el incidente en el formato institucional, con hora, circunstancia y medidas adoptadas.","7. Identificar la causa del incidente y ajustar el procedimiento o los insumos para evitar la repetición.","8. Acompañar a la persona expuesta durante la espera, porque el impacto emocional también requiere atención."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. En un centro de salud de Lima, una psicóloga atiende a una persona con una crisis de agitación. Al retirar una bandeja con material usado siente un pinchazo en el dedo; el objeto era una aguja mal descartada que sobresalía de un recipiente lleno. La psicóloga se lava las manos, avisa a la jefatura y acude a evaluación. El servicio revisa el caso, indica la profilaxis que corresponde y programa el seguimiento. Al día siguiente, el comité identifica que los recipientes rígidos se llenaban por encima de su capacidad y que el carro de curaciones se trasladaba sin tapa."],"bullets":["Lectura del caso: la exposición ocurrió en una tarea aparentemente administrativa, lo que confirma que el riesgo no se limita a procedimientos invasivos.","Lectura del caso: la conducta inmediata fue lavar, comunicar y evaluar; esperar síntomas habría retrasado la profilaxis y el seguimiento.","Lectura del caso: la alternativa descartada fue cubrir la herida y continuar la jornada, porque oculta el incidente y pierde la oportunidad de evaluar el riesgo.","Lectura del caso: el análisis del incidente derivó en un cambio de procedimiento, no en una sanción individual."]},{"title":"Residuos y protección ambiental","depth":"core","body":["Los residuos generados en la atención completan la cadena de bioseguridad. Su manejo empieza en el punto de generación, con segregación correcta, recipientes adecuados y cierre seguro; continúa con almacenamiento temporal, transporte y disposición final por el servicio autorizado.","Un residuo mal segregado expone al personal de limpieza, contamina áreas comunes y aumenta el volumen de desecho peligroso. La protección ambiental exige además reducir el uso innecesario de materiales y evitar que medicamentos o sustancias químicas lleguen al desagüe sin control."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: usar siempre la barrera máxima. La protección excesiva no mejora la seguridad y dificulta la tarea; la medida se elige según el riesgo.","Error: esperar el diagnóstico para protegerse. Las precauciones estándar se aplican a toda persona, porque el estado infeccioso puede ser desconocido.","Distinción: limpieza no es desinfección porque la primera retira materia orgánica y la segunda reduce microorganismos.","Distinción: desinfección no es esterilización porque la segunda elimina formas resistentes en objetos de uso crítico.","Distinción: bioseguridad no es bioseguridad hospitalaria porque la primera abarca laboratorios, campo y ambiente, y la segunda se limita al establecimiento de salud.","Distinción: exposición no es infección porque el contacto con material potencialmente infeccioso no siempre produce transmisión.","Error: ocultar o minimizar el incidente. Sin registro no hay evaluación del riesgo ni aprendizaje institucional."]},{"title":"Puntos clave","depth":"core","bullets":["La barrera se elige por riesgo y tarea, porque el exceso y el defecto protegen mal.","La higiene de manos interrumpe la transmisión por contacto y sostiene el resto de las medidas.","Las precauciones estándar se aplican a toda persona, ya que el diagnóstico no siempre está disponible.","El manejo de cortopunzantes previene la exposición más frecuente en la atención.","Ante una exposición se actúa de inmediato: lavar o irrigar, comunicar y evaluar.","El incidente registrado se convierte en mejora del procedimiento, no en culpa individual."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"warn","title":"Cadena, no barrera única","text":"La bioseguridad se sostiene en prácticas articuladas: higiene de manos, barreras, manejo de cortopunzantes y residuos. El distractor habitual ofrece una sola medida, como usar guantes, como respuesta suficiente; ante una exposición, en cambio, la prioridad es irrigar, comunicar y evaluar el riesgo."}},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CDC/NIOSH — Bloodborne Infectious Disease Risk Factors; vías de exposición y prevención.","Fuente: CDC — Management of Potentially Infectious Exposures and Illnesses; exposición percutánea, mucosas y piel no íntegra.","Fuente: MINSA — NTS N.° 144-MINSA/2018/DIGESA, gestión y manejo de residuos sólidos en servicios de salud.","Fuente: OMS — Cinco momentos para la higiene de manos; higiene de manos en la atención."]}],"sheet-psi-sp-3-4":[{"title":"Conceptos que sostienen el tema","depth":"core","body":["La gestión del riesgo no comienza con la emergencia. Se organiza como un ciclo que incluye estimar el riesgo, prevenirlo, reducirlo, prepararse, responder, rehabilitar y reconstruir. Cada fase deja capacidades que la siguiente aprovecha.","El riesgo no es el evento: es la probabilidad de daño cuando un peligro encuentra población expuesta y condiciones vulnerables. Esa distinción permite intervenir antes de que ocurra el desastre y explica por qué el mismo fenómeno afecta de manera desigual a dos territorios."]},{"title":"Fundamentos teóricos y mecanismos","depth":"core","body":["La lectura del riesgo combina una dimensión física y una dimensión social. La primera describe el evento y su alcance; la segunda, las condiciones que convierten ese evento en pérdida para las personas."],"bullets":["El riesgo se expresa como interacción entre peligro, exposición y vulnerabilidad, atenuada por la capacidad; la gestión actúa sobre los tres primeros y fortalece la cuarta.","La vulnerabilidad es social además de física: vivienda, ingreso, género, discapacidad y aislamiento condicionan la exposición y la recuperación.","La ocupación informal del territorio y la degradación ambiental aumentan la exposición y convierten un fenómeno natural en desastre.","El impacto psicológico depende de la amenaza percibida, la pérdida sufrida, el apoyo disponible y la continuidad de los servicios básicos.","La mayoría de las reacciones inmediatas son esperables y se atenúan con seguridad, información y apoyo social; no constituyen un trastorno por sí mismas.","La ayuda humanitaria sin participación de la comunidad puede debilitar las redes locales que sostienen la recuperación.","El estrés del personal de respuesta reduce la calidad de la atención y aumenta el riesgo de error, por lo que el relevo y el descanso son medidas operativas."]},{"title":"Componentes del riesgo y clasificación de amenazas","depth":"full","body":["Analizar el riesgo exige descomponerlo y ubicarlo en un territorio concreto. Por su origen, los peligros se clasifican en naturales, como sismos, tsunamis e inundaciones, e inducidos por la acción humana, como derrames químicos, explosiones o incendios industriales. La actividad humana también agrava los fenómenos naturales mediante la degradación ambiental o la ocupación insegura del territorio.","La tabla ordena los componentes del riesgo con la pregunta que permite explorarlos y un ejemplo de lectura local."],"table":{"headers":["Componente","Pregunta","Ejemplo"],"rows":[["Peligro","Qué evento puede ocurrir y con qué intensidad","Lluvias intensas e inundación"],["Exposición","Quiénes y qué bienes están en el área","Viviendas junto al cauce"],["Vulnerabilidad","Qué condiciones aumentan el daño","Material precario y falta de rutas"],["Capacidad","Qué recursos permiten responder","Brigadas, albergue y comunicación"],["Riesgo","Qué daño es probable y con qué severidad","Pérdida de vivienda y de servicios"]]}},{"title":"Fases de la gestión y tareas del equipo de salud","depth":"full","body":["Las fases se encadenan y cada una prepara la siguiente. La tabla resume la acción principal y el aporte específico del equipo de salud, que no se limita a la atención durante la emergencia."],"table":{"headers":["Fase","Acción principal","Aporte del equipo de salud"],"rows":[["Estimación","Caracterizar peligro, exposición y vulnerabilidad","Identificar grupos en riesgo y rutas de derivación"],["Prevención y reducción","Disminuir vulnerabilidad y exposición","Educación, planes locales y coordinación"],["Preparación","Organizar recursos y ensayar respuestas","Simulacros, botiquín y roles definidos"],["Respuesta","Proteger, socorrer y estabilizar","PAP, triaje y derivación"],["Rehabilitación","Restablecer servicios y apoyos","Continuidad de la atención y seguimiento"]]}},{"title":"Procedimiento: PAP, triaje y derivación","depth":"full","bullets":["1. Verificar la seguridad del entorno antes de acercarse y usar los implementos de protección disponibles.","2. Identificar necesidades urgentes, lesiones y personas que requieren asistencia especializada.","3. Presentarse, pedir permiso y explicar qué se va a hacer, con lenguaje comprensible y sin prometer resultados.","4. Escuchar sin presionar el relato y atender necesidades básicas como agua, abrigo, información y contacto con familiares.","5. Conectar con apoyos elegidos por la persona y con los servicios disponibles, facilitando información clara sobre la ruta.","6. Aplicar triaje según necesidad y posibilidad de beneficio, y registrar la priorización para sostener la continuidad.","7. Derivar de inmediato ante confusión aguda, lesión importante, incapacidad de autocuidado o riesgo de daño.","8. Registrar las necesidades detectadas, coordinar con el nivel correspondiente y prever seguimiento para quien persista con deterioro."]},{"title":"Caso razonado","depth":"full","body":["Caso ficticio. Tras una inundación en un asentamiento de Piura, el albergue temporal reúne a varias familias. Una mujer adulta mayor deambula desorientada, sin poder decir dónde está, y se dirige hacia una zona con muros debilitados. Una madre con dos niñas pequeñas no encuentra a su pareja y repite que no puede dormir. El equipo de salud organiza la respuesta: asegura el perímetro, acompaña a la mujer a evaluación urgente, conecta a la madre con el registro de personas y con apoyo para sus hijas, y ofrece información sobre agua segura y albergue. Al final del turno, el equipo realiza un breve espacio de descanso y relevo."],"bullets":["Lectura del caso: la desorientación y el riesgo inmediato exigieron protección y evaluación urgente antes que cualquier intervención de relato.","Lectura del caso: la alternativa descartada fue iniciar un debriefing con todo el albergue, porque no es una práctica de PAP y puede aumentar la exposición al evento.","Lectura del caso: la madre recibió conexión con apoyos e información concreta, no una promesa de que todo se resolvería.","Lectura del caso: el relevo del equipo se trató como medida operativa, porque el agotamiento deteriora la calidad de la ayuda."]},{"title":"Duelo, reacción esperable y trastorno","depth":"core","body":["El duelo es una respuesta ante una pérdida y no un trastorno por definición. Su curso varía según la cultura, el vínculo, las pérdidas acumuladas y el apoyo disponible; la mayoría de las personas se adapta con apoyo de la red cercana y continuidad de la vida cotidiana.","La evaluación clínica se justifica cuando el deterioro persiste, interfiere con el autocuidado o aparece riesgo de daño. Atribuir un trastorno a toda persona expuesta confunde reacción esperable con diagnóstico y puede medicalizar el sufrimiento."]},{"title":"Errores frecuentes y distinciones","depth":"core","bullets":["Error: igualar peligro con desastre. El evento es una condición; el desastre depende de exposición, vulnerabilidad y capacidad.","Error: forzar el relato para prevenir secuelas. La evidencia no sostiene el debriefing obligatorio y la presión puede aumentar el malestar.","Distinción: amenaza no es vulnerabilidad porque la primera es el evento potencial y la segunda, la condición que permite el daño.","Distinción: PAP no es psicoterapia porque el primero es apoyo inicial y la segunda, intervención clínica con evaluación y objetivos.","Distinción: duelo no es trastorno porque el primero es una respuesta adaptativa que suele resolverse con apoyo.","Distinción: triaje no es diagnóstico porque prioriza necesidad y beneficio, no clasifica enfermedades.","Error: intervenir sin asegurar el entorno. El riesgo físico inmediato anula cualquier apoyo psicológico posterior."]},{"title":"Puntos clave","depth":"core","bullets":["El riesgo combina peligro, exposición y vulnerabilidad, por lo que reducir vulnerabilidad reduce el desastre.","La preparación se demuestra en simulacros, roles y suministros, no en documentos sin ensayo.","Los PAP priorizan seguridad, escucha y conexión, y no exigen relato ni intervención clínica inmediata.","El triaje ordena la ayuda según necesidad y beneficio, y sostiene la equidad en la respuesta.","La derivación oportuna protege a quien requiere evaluación urgente y evita daños adicionales.","El cuidado del cuidador es parte de la respuesta, porque el desgaste reduce la calidad y la seguridad.","La mayoría de reacciones son esperables, y solo el deterioro persistente justifica evaluación especializada."]},{"title":"Tips de examen","depth":"core","callout":{"tone":"info","title":"PAP no es debriefing","text":"Los primeros auxilios psicológicos ofrecen seguridad, escucha y conexión con apoyos; no son un interrogatorio ni una sesión obligatoria de relato. El distractor frecuente propone revivir el evento para prevenir secuelas, cuando la prioridad es proteger, atender necesidades y derivar si hay riesgo."}},{"title":"Comunicación de riesgo y reconstrucción","depth":"full","body":["La respuesta incluye comunicación de riesgo: decir qué se sabe, qué no se sabe y qué se está haciendo, con vocería única, canales locales y lenguaje comprensible. La información debe actualizarse y corregirse sin ocultar incertidumbre; el silencio también comunica y suele aumentar el rumor.","La reconstrucción restablece servicios, vivienda, agua y continuidad de la atención; cierra el ciclo y reduce el riesgo futuro. No es una fase solo infraestructural: incluye recuperación psicosocial, participación comunitaria y evaluación de lo aprendido."],"bullets":["Vocería única y canales locales.","Mensajes claros, verificables y actualizados.","Explicar incertidumbre y medidas de protección.","Evitar estigma y rumores.","Reconstruir servicios y continuidad.","Evaluar la respuesta y ajustar planes."]},{"title":"Fuentes y Referencias","depth":"core","bullets":["Fuente: CENEPRED — Manual para la evaluación de riesgos originados por fenómenos naturales, 2.ª versión; clasificación de peligros de origen natural.","Fuente: CENEPRED — Manual para la elaboración de riesgos inducidos por la acción humana.","Fuente: CDC — Principles of Epidemiology in Public Health Practice, 3rd edition; causalidad y medidas estadísticas.","Fuente: OPS — Glosario sobre brotes y epidemias; definiciones de brote, epidemia y endemia."]}]};
